window.QUESTIONS = [{"id":"AUT-001","theme":"autoroute","q":"Je conduis un cyclomoteur. Puis-je emprunter l'autoroute ?","choices":["Oui, si je reste sur la bande de droite","Non, jamais","Oui, mais seulement de jour"],"answer":1,"explain":"L'accès aux autoroutes est interdit aux piétons, aux cyclistes, aux conducteurs de cyclomoteurs et d'animaux.","sign":"F5","ref":"Art. 21.1 AR 01/12/1975"},{"id":"AUT-002","theme":"autoroute","q":"Un véhicule qui ne peut pas atteindre 70 km/h sur une route plate peut-il accéder à l'autoroute ?","choices":["Oui, s'il allume ses feux de détresse","Oui, s'il reste sur la bande d'arrêt d'urgence","Non"],"answer":2,"explain":"L'accès à l'autoroute est interdit aux véhicules (ou trains de véhicules) qui ne peuvent atteindre en palier la vitesse de 70 km/h.","sign":"F5","ref":"Art. 21.1 AR 01/12/1975"},{"id":"AUT-003","theme":"autoroute","q":"Un agriculteur veut emprunter l'autoroute avec son tracteur agricole sur 2 km. Est-ce permis ?","choices":["Non","Oui, à vitesse réduite","Oui, s'il roule sur la bande de droite"],"answer":0,"explain":"L'accès aux autoroutes est interdit aux conducteurs de véhicules agricoles.","ref":"Art. 21.1 AR 01/12/1975"},{"id":"AUT-004","theme":"autoroute","q":"Un quad (quadricycle à moteur sans habitacle) peut-il circuler sur l'autoroute ?","choices":["Oui","Non"],"answer":1,"explain":"Les quadricycles à moteur sans habitacle n'ont pas accès aux autoroutes, ni aux routes pour automobiles.","sign":"F5","ref":"Art. 21.1 et 22.1 AR 01/12/1975"},{"id":"AUT-005","theme":"autoroute","q":"Ma voiture est en panne. Un ami peut-il la remorquer sur l'autoroute jusqu'au garage au moyen d'une corde ?","choices":["Oui, à 25 km/h maximum","Oui, si les feux de détresse sont allumés","Non, c'est interdit sur l'autoroute"],"answer":2,"explain":"Remorquer un véhicule avec une attache de fortune ou une attache secondaire est interdit sur l'autoroute (et sur les routes pour automobiles).","ref":"Art. 21.1 et 21.4.5° AR 01/12/1975"},{"id":"AUT-006","theme":"autoroute","q":"Sur autoroute, en l'absence de signal particulier, quelle est la vitesse minimale à laquelle je dois rouler ?","choices":["50 km/h","70 km/h","90 km/h"],"answer":1,"explain":"Sauf limitation inférieure imposée par un signal C43, on ne peut pas rouler à moins de 70 km/h sur autoroute, tout en adaptant sa vitesse aux circonstances (brouillard, embouteillage…).","sign":"F5","ref":"Art. 21.2 AR 01/12/1975"},{"id":"AUT-007","theme":"autoroute","q":"Sur autoroute, à hauteur d'un chantier, ce signal est placé. Je roule à 50 km/h. Est-ce autorisé ?","choices":["Oui","Non, la vitesse minimale sur autoroute est de 70 km/h"],"answer":0,"explain":"La vitesse minimale de 70 km/h ne s'applique pas lorsqu'un signal C43 impose une limitation inférieure.","sign":"C43-50","ref":"Art. 21.2 AR 01/12/1975"},{"id":"AUT-009","theme":"autoroute","q":"À partir de quel endroit les règles particulières des autoroutes s'appliquent-elles ?","choices":["À partir de l'endroit où ce signal est placé","À partir de la fin de la bande d'accélération","À partir du premier panneau de vitesse"],"answer":0,"explain":"Le signal F5 indique le commencement d'une autoroute ou l'accès à une autoroute : les règles spéciales s'appliquent dès l'endroit où il est placé.","sign":"F5","ref":"Art. 2.3 et 71 (F5) AR 01/12/1975"},{"id":"AUT-010","theme":"autoroute","q":"Que signifie ce signal ?","choices":["Fin de la route pour automobiles","Fin de l'autoroute","Sortie d'autoroute dans 500 m"],"answer":1,"explain":"Le signal F7 indique la fin de l'autoroute : les règles spéciales des autoroutes cessent de s'appliquer.","sign":"F7","ref":"Art. 2.3 et 71 (F7) AR 01/12/1975"},{"id":"AUT-011","theme":"autoroute","q":"Je vois ce signal. Quel véhicule n'est PAS admis sur cette route ?","choices":["Une moto","Une voiture tractant une caravane","Un cyclomoteur"],"answer":2,"explain":"Le signal F9 indique une route pour automobiles, réservée aux véhicules à moteur et à leurs remorques, sauf les cyclomoteurs, les véhicules agricoles, les trains de véhicules forains et les quadricycles sans habitacle.","sign":"F9","ref":"Art. 22.1 AR 01/12/1975"},{"id":"AUT-012","theme":"autoroute","q":"Sur une route pour automobiles, je me suis trompé de direction. Puis-je faire demi-tour en profitant d'une interruption du terre-plein ?","choices":["Non, le demi-tour y est interdit","Oui, si la route est dégagée","Oui, si je mets mon clignotant à temps"],"answer":0,"explain":"Les interdictions de l'autoroute (demi-tour, marche arrière, raccordements transversaux, arrêt et stationnement hors des aires) s'appliquent aussi sur les routes pour automobiles.","grave":true,"sign":"F9","ref":"Art. 22.2 et 21.4 AR 01/12/1975"},{"id":"AUT-013","theme":"autoroute","q":"J'ai manqué ma sortie d'autoroute de quelques mètres. Puis-je faire marche arrière sur la bande d'arrêt d'urgence pour la reprendre ?","choices":["Oui, si je mets mes feux de détresse","Non, je dois continuer jusqu'à la sortie suivante","Oui, si la circulation est faible"],"answer":1,"explain":"Faire marche arrière ou rouler en sens contraire est interdit sur l'autoroute. Il faut continuer jusqu'à la sortie suivante.","grave":true,"ref":"Art. 21.4.3° AR 01/12/1975"},{"id":"AUT-014","theme":"autoroute","q":"Sur l'autoroute, je vois un passage aménagé dans le terre-plein central (raccordement transversal). Puis-je l'emprunter pour repartir dans l'autre sens ?","choices":["Oui, s'il n'y a personne","Oui, mais à moins de 30 km/h","Non"],"answer":2,"explain":"Il est interdit sur autoroute d'emprunter les raccordements transversaux et de faire demi-tour. Ces passages sont réservés aux services de secours et d'entretien.","grave":true,"ref":"Art. 21.4.1° et 2° AR 01/12/1975"},{"id":"AUT-015","theme":"autoroute","q":"Je suis fatigué au volant sur l'autoroute. Où puis-je m'arrêter pour me reposer ?","choices":["Sur la bande d'arrêt d'urgence","Sur une aire de stationnement indiquée par ce signal","Sur la bande de droite, feux de détresse allumés"],"answer":1,"explain":"Sur autoroute, l'arrêt et le stationnement sont interdits, sauf sur les aires de stationnement indiquées par le signal E9a. La bande d'arrêt d'urgence est réservée aux situations de nécessité (panne).","sign":"E9a","ref":"Art. 21.4.4° AR 01/12/1975"},{"id":"AUT-016","theme":"autoroute","q":"Sur l'autoroute, mon téléphone sonne. Puis-je m'arrêter sur la bande d'arrêt d'urgence pour répondre ?","choices":["Non","Oui, si j'allume mes feux de détresse","Oui, pour un appel de moins de 5 minutes"],"answer":0,"explain":"L'arrêt sur autoroute est interdit sauf sur les aires indiquées par le signal E9a. Un appel téléphonique n'est pas une nécessité justifiant un arrêt sur la bande d'arrêt d'urgence.","ref":"Art. 21.4.4° AR 01/12/1975"},{"id":"AUT-017","theme":"autoroute","q":"Embouteillage sur l'autoroute. Ma sortie est à 300 m. Puis-je rouler sur la bande d'arrêt d'urgence pour l'atteindre ?","choices":["Oui, à vitesse réduite","Non","Oui, si je mets mes feux de détresse"],"answer":1,"explain":"Il est interdit de circuler sur la bande d'arrêt d'urgence, sauf pour les véhicules prioritaires en mission urgente, les services requis par la police ou le parquet et les dépanneuses se rendant sur le lieu d'un incident.","grave":true,"ref":"Art. 9.7 AR 01/12/1975"},{"id":"AUT-018","theme":"autoroute","q":"La circulation sur l'autoroute est fortement ralentie. Qui peut circuler sur la bande d'arrêt d'urgence pour se rendre sur le lieu d'un accident ?","choices":["Tout conducteur qui transporte un malade","Une dépanneuse","Les autocars"],"answer":1,"explain":"Les dépanneuses peuvent emprunter la bande d'arrêt d'urgence pour se rendre sur le lieu d'un incident lorsque la circulation est fortement ralentie ou arrêtée, de même que les véhicules prioritaires en mission urgente.","ref":"Art. 9.7 AR 01/12/1975"},{"id":"AUT-019","theme":"autoroute","q":"Autoroute à deux bandes : je roule sur la bande de droite et une file se forme. Que dois-je faire ?","choices":["Serrer à gauche","Rester au milieu de ma bande","Serrer à droite"],"answer":2,"explain":"En cas de file, on forme un couloir de secours : sur une chaussée à deux bandes, ceux de gauche serrent à gauche et ceux de droite serrent à droite.","ref":"Art. 9.8.1° AR 01/12/1975"},{"id":"AUT-020","theme":"autoroute","q":"Autoroute à trois bandes : je roule sur la bande du milieu et une file se forme. Que dois-je faire ?","choices":["Serrer à droite","Serrer à gauche","Me rabattre sur la bande d'arrêt d'urgence"],"answer":0,"explain":"Sur une chaussée de plus de deux bandes, ceux de la bande de gauche serrent à gauche et tous les autres serrent à droite : le couloir de secours se forme à côté de la bande de gauche.","ref":"Art. 9.8.2° AR 01/12/1975"},{"id":"AUT-021","theme":"autoroute","q":"Quand dois-je former un couloir de secours ?","choices":["Uniquement quand j'entends une sirène","Dès qu'une file se forme","Uniquement si la police me le demande"],"answer":1,"explain":"Le couloir de secours doit être formé dès la formation d'une file, sans attendre l'arrivée des véhicules de secours.","ref":"Art. 9.8 AR 01/12/1975"},{"id":"AUT-022","theme":"autoroute","q":"Le couloir de secours est formé. Puis-je l'emprunter pour avancer jusqu'à la prochaine sortie ?","choices":["Oui, à faible vitesse","Non"],"answer":1,"explain":"Le couloir de secours est réservé aux véhicules prioritaires en mission, aux services requis par la police ou le parquet et aux dépanneuses qui se rendent sur le lieu d'un incident.","ref":"Art. 2.70 et 9.8 AR 01/12/1975"},{"id":"AUT-023","theme":"autoroute","q":"Autoroute à trois bandes, circulation fluide. Les bandes de droite et du milieu sont libres. Sur quelle bande dois-je rouler ?","choices":["Sur la bande de droite","Sur la bande du milieu","Sur celle que je veux"],"answer":0,"explain":"Tout conducteur doit se tenir le plus près possible du bord droit de la chaussée. Après un dépassement, il doit reprendre sa place à droite dès que possible.","ref":"Art. 9.3.1 et 16.6 AR 01/12/1975"},{"id":"AUT-024","theme":"autoroute","q":"Circulation fluide sur l'autoroute. Une voiture roule lentement sur la bande de gauche. Puis-je la dépasser en passant par la bande de droite ?","choices":["Oui, si elle roule trop lentement","Oui, si je mets mon clignotant","Non"],"answer":2,"explain":"Le dépassement s'effectue à gauche. Dépasser par la droite n'est permis que si le conducteur à dépasser s'est porté à gauche pour tourner à gauche, ce qui n'arrive pas sur autoroute.","grave":true,"ref":"Art. 16.3 AR 01/12/1975"},{"id":"AUT-025","theme":"autoroute","q":"Circulation dense sur l'autoroute : les véhicules roulent en files sur toutes les bandes. La file de droite avance plus vite que celle de gauche. Est-ce un dépassement interdit par la droite ?","choices":["Oui","Non"],"answer":1,"explain":"Lorsque la circulation s'effectue en files, le fait qu'une file avance plus vite qu'une autre n'est pas considéré comme un dépassement.","ref":"Art. 9.5 et 16.2 AR 01/12/1975"},{"id":"AUT-026","theme":"autoroute","q":"Sur l'autoroute, je dois quitter la bande d'accélération pour m'insérer dans la circulation. Que dois-je faire ?","choices":["Céder le passage aux véhicules qui circulent sur l'autoroute","M'insérer : les véhicules sur l'autoroute doivent me laisser passer","M'arrêter au bout de la bande d'accélération dans tous les cas"],"answer":0,"explain":"Changer de bande est une manœuvre : je dois céder le passage aux usagers qui circulent sur l'autoroute et ne m'insérer que si je peux le faire sans danger, après avoir mis mon clignotant.","grave":true,"ref":"Art. 12.4, 12.5 et 13 AR 01/12/1975"},{"id":"AUT-027","theme":"autoroute","q":"Sur l'autoroute, la bande de droite est fermée plus loin pour travaux. La circulation est fortement ralentie. Où dois-je me rabattre sur la bande de gauche ?","choices":["Le plus tôt possible","Juste devant le rétrécissement","Où je veux"],"answer":1,"explain":"Lorsque la circulation est fortement ralentie, on applique le principe de la tirette : on s'intercale sur la bande libre seulement juste devant le rétrécissement, et les conducteurs de la bande libre cèdent tour à tour le passage.","ref":"Art. 12bis AR 01/12/1975"},{"id":"AUT-028","theme":"autoroute","q":"Sur une autoroute à trois bandes, un camion de 20 tonnes peut-il circuler sur la bande de gauche (sans signal particulier) ?","choices":["Oui, pour dépasser","Non","Oui, si la circulation est fluide"],"answer":1,"explain":"Sur une autoroute de trois bandes ou plus, les véhicules de plus de 3,5 t, les autobus et les autocars ne peuvent emprunter que les deux bandes de droite.","ref":"Art. 21.3 AR 01/12/1975"},{"id":"AUT-029","theme":"autoroute","q":"Ma voiture tombe en panne sur l'autoroute et je l'immobilise sur la bande d'arrêt d'urgence. À quelle distance minimale dois-je placer le triangle de danger ?","choices":["30 mètres","50 mètres","100 mètres"],"answer":2,"explain":"Le triangle se place en deçà du véhicule à au moins 100 m sur autoroute (30 m sur les voies ordinaires), de façon à être visible à environ 50 m.","ref":"Art. 51.2 AR 01/12/1975"},{"id":"AUT-030","theme":"autoroute","q":"En panne sur la bande d'arrêt d'urgence d'une autoroute, je dois sortir de ma voiture. Que dois-je faire ?","choices":["Enfiler une veste de sécurité rétroréfléchissante","Rien de particulier","Allumer mes feux de brouillard avant"],"answer":0,"explain":"Sur autoroute et route pour automobiles, le conducteur d'un véhicule en panne rangé là où l'arrêt est interdit doit porter une veste de sécurité rétroréfléchissante dès qu'il sort du véhicule.","ref":"Art. 51.4 AR 01/12/1975"},{"id":"AUT-031","theme":"autoroute","q":"En panne sur la bande d'arrêt d'urgence de l'autoroute, j'allume mes feux de détresse. Est-ce suffisant pour signaler mon véhicule ?","choices":["Oui","Non, je dois aussi placer le triangle de danger"],"answer":1,"explain":"Le triangle de danger est obligatoire lorsque le véhicule est immobilisé à un endroit où l'arrêt est interdit. Les feux de détresse peuvent s'y ajouter, mais ne le remplacent pas.","ref":"Art. 51.1 AR 01/12/1975"},{"id":"AUT-032","theme":"autoroute","q":"Au-dessus de ma bande de circulation sur l'autoroute s'allume une croix rouge. Que dois-je faire ?","choices":["Continuer : ce n'est qu'un avertissement","Quitter cette bande, car la circulation y est interdite","M'arrêter immédiatement sur ma bande"],"answer":1,"explain":"Une croix rouge au-dessus d'une bande signifie que la circulation y est interdite : il faut la quitter en changeant de bande prudemment.","grave":true,"ref":"Art. 62bis.1° AR 01/12/1975"},{"id":"AUT-033","theme":"autoroute","q":"Au-dessus de ma bande s'allume une flèche orange oblique pointant vers le bas et vers la droite. Que signifie-t-elle ?","choices":["Je dois quitter cette bande vers la droite","La bande est ouverte, je peux continuer","Je dois serrer à gauche pour former un couloir de secours"],"answer":0,"explain":"La flèche orange oblique (éventuellement clignotante) signifie que la bande est interdite, sauf pour la quitter dans la direction indiquée par la flèche.","ref":"Art. 62bis.3° AR 01/12/1975"},{"id":"AUT-034","theme":"autoroute","q":"Au-dessus d'une bande de circulation, une flèche verte pointe vers le bas. Que signifie-t-elle ?","choices":["Bande réservée aux services de secours","Je peux circuler sur cette bande","Bande fermée plus loin"],"answer":1,"explain":"La flèche verte dirigée vers le bas signifie que la circulation est autorisée sur cette bande.","ref":"Art. 62bis.2° AR 01/12/1975"},{"id":"DEP-001","theme":"depassement","q":"Je circule sur une chaussée à deux sens, sans marquage au sol. Où dois-je me placer ?","choices":["Le plus près possible du bord droit de la chaussée","Au milieu de ma moitié de chaussée","Où je veux, s'il n'y a personne en face"],"answer":0,"explain":"Sur la chaussée, tout conducteur doit se tenir le plus près possible du bord droit, sauf sur les places ou pour suivre les signaux F13/F15.","ref":"Art. 9.3.1 AR 01/12/1975"},{"id":"DEP-002","theme":"depassement","q":"Dans l'anneau d'un rond-point, suis-je obligé de rouler le plus près possible du bord droit ?","choices":["Oui, comme partout ailleurs","Non, mais je dois respecter les marques délimitant les bandes s'il y en a"],"answer":1,"explain":"Dans l'anneau d'un rond-point, on n'est pas tenu de serrer le bord droit (sauf partie réservée). S'il y a des bandes marquées, on les respecte et on prend celle qui convient le mieux à sa destination.","sign":"D5","ref":"Art. 9.3.1 AR 01/12/1975"},{"id":"DEP-003","theme":"depassement","q":"La voie publique comporte deux chaussées nettement séparées par un terre-plein central. Puis-je emprunter la chaussée de gauche par rapport à mon sens de marche ?","choices":["Oui, pour dépasser","Non, sauf réglementation locale","Oui, si elle est libre"],"answer":1,"explain":"Quand la voie publique comporte deux ou trois chaussées nettement séparées, il est interdit d'emprunter la chaussée de gauche (sauf réglementation locale) : on roulerait à contresens.","grave":true,"ref":"Art. 9.2 AR 01/12/1975"},{"id":"DEP-004","theme":"depassement","q":"Bouchon sur une autoroute à trois bandes. Je suis sur la bande du milieu. Pour former le couloir de secours, je dois :","choices":["Passer sur la bande d'arrêt d'urgence","Serrer à gauche","Serrer à droite"],"answer":2,"explain":"Avec plus de deux bandes, seule la bande de gauche serre à gauche ; toutes les autres serrent à droite. Le couloir de secours se forme à côté de la bande de gauche.","sign":"F5","ref":"Art. 9.8 AR 01/12/1975"},{"id":"DEP-005","theme":"depassement","q":"Sur l'autoroute, la circulation est presque à l'arrêt. Puis-je rouler sur la bande d'arrêt d'urgence pour avancer jusqu'à la prochaine sortie ?","choices":["Non","Oui, à vitesse réduite","Oui, si je mets mes feux de détresse"],"answer":0,"explain":"Il est interdit de circuler sur la bande d'arrêt d'urgence, sauf pour les véhicules prioritaires en mission urgente, les services requis par la police et les dépanneuses dans certaines conditions.","sign":"F5","ref":"Art. 9.7 AR 01/12/1975"},{"id":"DEP-006","theme":"depassement","q":"Sur une route étroite, un camion arrive en sens inverse. Que dois-je faire pour le croiser ?","choices":["Croiser par la gauche","Laisser une distance latérale suffisante et, au besoin, serrer à droite","Me placer au milieu pour qu'il me voie"],"answer":1,"explain":"Le croisement s'effectue à droite. Il faut laisser une distance latérale suffisante et serrer à droite si nécessaire ; si la chaussée est trop étroite, on peut utiliser l'accotement de plain-pied sans mettre en danger ceux qui s'y trouvent.","ref":"Art. 15.1, 15.2 et 15.3 AR 01/12/1975"},{"id":"DEP-007","theme":"depassement","q":"Une camionnette est en stationnement sur ma moitié de chaussée. Une voiture arrive en face. Qui doit laisser passer l'autre ?","choices":["Celui qui arrive le premier à hauteur de l'obstacle","La voiture qui arrive en face, car elle a de la place","Moi : je dois ralentir et, au besoin, m'arrêter"],"answer":2,"explain":"Le conducteur dont la progression est entravée par un obstacle doit ralentir et au besoin s'arrêter pour laisser passer les usagers venant en sens inverse.","ref":"Art. 15.2 AR 01/12/1975"},{"id":"DEP-008","theme":"depassement","q":"La voiture devant moi a enclenché son clignoteur gauche et s'est portée vers la gauche pour tourner à gauche. Comment puis-je la dépasser ?","choices":["Par la droite","Je ne peux pas la dépasser","Par la gauche"],"answer":0,"explain":"Le dépassement se fait en principe à gauche, mais il se fait à droite lorsque le conducteur à dépasser a annoncé son intention de tourner à gauche et s'est porté à gauche.","ref":"Art. 16.3 AR 01/12/1975"},{"id":"DEP-009","theme":"depassement","q":"Sur une route à deux sens, la voiture devant moi roule lentement au milieu de sa bande, sans clignoteur. Puis-je la dépasser par la droite en utilisant l'accotement ?","choices":["Oui, si je roule lentement","Non, le dépassement s'effectue à gauche","Oui, si l'accotement est de plain-pied"],"answer":1,"explain":"Le dépassement s'effectue à gauche. Le dépassement par la droite n'est permis que si le conducteur à dépasser a annoncé qu'il tournait (ou se rangeait) à gauche et s'est porté à gauche.","ref":"Art. 16.3 AR 01/12/1975"},{"id":"DEP-010","theme":"depassement","q":"Je veux dépasser un camion. Dans mon rétroviseur, je vois que la voiture qui me suit a déjà commencé à me dépasser. Que dois-je faire ?","choices":["Mettre mon clignoteur gauche pour qu'elle me laisse passer","Déboîter rapidement avant elle","Attendre qu'elle ait terminé son dépassement"],"answer":2,"explain":"Avant de dépasser, il faut s'assurer notamment qu'aucun conducteur qui suit n'a commencé un dépassement, que la voie est libre sur une distance suffisante et qu'on pourra reprendre sa place à droite sans gêner.","grave":true,"ref":"Art. 16.4 AR 01/12/1975"},{"id":"DEP-011","theme":"depassement","q":"Je viens de dépasser une voiture sur une route à deux sens. Quand dois-je reprendre ma place à droite ?","choices":["Dès que je peux le faire sans inconvénient, en mettant mon clignoteur droit","Seulement quand une voiture arrive en face","Quand je veux, la bande de gauche est libre"],"answer":0,"explain":"Après un dépassement par la gauche, il faut reprendre sa place à droite aussitôt qu'on peut le faire sans inconvénient, après l'avoir annoncé avec les feux indicateurs de direction.","ref":"Art. 16.6 AR 01/12/1975"},{"id":"DEP-012","theme":"depassement","q":"Sur l'autoroute, je viens de dépasser un camion et je veux aussitôt en dépasser un second, juste devant lui. Suis-je obligé de revenir d'abord sur la bande de droite ?","choices":["Oui, toujours","Non, je peux rester à gauche pour effectuer aussitôt ce nouveau dépassement"],"answer":1,"explain":"Sur les chaussées à sens unique (c'est le cas d'une chaussée d'autoroute), on n'est pas tenu de reprendre sa place à droite si on veut effectuer aussitôt un nouveau dépassement.","sign":"F5","ref":"Art. 16.6 AR 01/12/1975"},{"id":"DEP-013","theme":"depassement","q":"Une voiture me dépasse par la gauche. Que dois-je faire ?","choices":["Accélérer pour qu'elle termine plus vite","Serrer à droite le plus possible et ne pas accélérer","Freiner brusquement"],"answer":1,"explain":"Le conducteur qui va être dépassé par la gauche doit serrer à droite le plus possible et ne peut pas accélérer.","grave":true,"ref":"Art. 16.7 AR 01/12/1975"},{"id":"DEP-014","theme":"depassement","q":"J'approche du sommet d'une côte, la visibilité est insuffisante. Une ligne discontinue sépare les deux sens. Puis-je dépasser la voiture qui me précède ?","choices":["Oui, si je klaxonne","Oui, puisque la ligne est discontinue","Non"],"answer":2,"explain":"Le dépassement par la gauche est interdit à l'approche du sommet d'une côte et dans les virages lorsque la visibilité est insuffisante, sauf s'il peut se faire sans franchir la ligne continue séparant les deux sens.","grave":true,"ref":"Art. 17.2.3° AR 01/12/1975"},{"id":"DEP-015","theme":"depassement","q":"J'approche d'un carrefour où la priorité de droite s'applique. Puis-je y dépasser la voiture qui me précède ?","choices":["Oui, si personne ne vient de droite","Non"],"answer":1,"explain":"Le dépassement par la gauche d'un véhicule à plus de deux roues, d'un deux-roues motorisé ou d'un véhicule attelé est interdit dans les carrefours où la priorité de droite est applicable.","grave":true,"sign":"B17","ref":"Art. 17.2.2° AR 01/12/1975"},{"id":"DEP-016","theme":"depassement","q":"Je circule sur une route prioritaire (signal B9). À l'approche d'un carrefour, la visibilité est bonne, la ligne est discontinue et aucun signal n'interdit le dépassement. Le carrefour, à lui seul, m'interdit-il de dépasser une voiture ?","choices":["Oui, on ne dépasse jamais dans un carrefour","Non, l'interdiction vise les conducteurs qui doivent céder le passage"],"answer":1,"explain":"Dans les carrefours, le dépassement est interdit là où la priorité de droite s'applique et, dans les autres carrefours, pour les conducteurs qui doivent céder le passage. Sur la route prioritaire, le carrefour n'interdit pas à lui seul le dépassement, qui doit toutefois se faire sans danger.","sign":"B9","ref":"Art. 17.2.2° AR 01/12/1975"},{"id":"DEP-017","theme":"depassement","q":"Je vais déboucher d'une route munie d'un signal « cédez le passage » sur une autre route. Puis-je dépasser la voiture devant moi dans le carrefour ?","choices":["Non","Oui, si je la dépasse rapidement"],"answer":0,"explain":"Dans les carrefours autres que ceux à priorité de droite, le dépassement est interdit aux conducteurs qui doivent céder le passage (signal B1 ou B5, chemin de terre).","sign":"B1","ref":"Art. 17.2.2° AR 01/12/1975"},{"id":"DEP-018","theme":"depassement","q":"Dans un carrefour à priorité de droite, un cycliste roule devant moi. L'interdiction de dépasser dans ce carrefour s'applique-t-elle à ce cycliste ?","choices":["Non, elle ne vise pas les bicyclettes ; je dois cependant dépasser sans danger et à au moins 1 m","Oui, comme pour une voiture"],"answer":0,"explain":"L'interdiction de l'art. 17.2 vise les véhicules attelés, les véhicules à moteur à deux roues et les véhicules à plus de deux roues. Elle ne vise donc pas la bicyclette, mais le dépassement doit rester sans danger et respecter la distance latérale.","sign":"B17","ref":"Art. 17.2 et 40ter AR 01/12/1975"},{"id":"DEP-019","theme":"depassement","q":"La voiture devant moi ralentit à l'approche d'un passage pour piétons (sans feux ni agent). Puis-je la dépasser ?","choices":["Non","Oui, si je ne vois pas de piéton","Oui, en klaxonnant"],"answer":0,"explain":"Il est interdit de dépasser un véhicule qui s'approche ou s'arrête devant un passage pour piétons (ou pour cyclistes) là où la circulation n'est pas réglée par un agent ou des feux : il peut cacher un piéton.","grave":true,"ref":"Art. 17.2.5° AR 01/12/1975"},{"id":"DEP-020","theme":"depassement","q":"J'approche d'un passage à niveau sans barrières ni feux, annoncé par une croix de Saint-André (A45). Puis-je dépasser la voiture qui me précède ?","choices":["Non","Oui, si aucun train n'est visible"],"answer":0,"explain":"Le dépassement est interdit sur un passage à niveau signalé par A45 ou A47, sauf s'il est muni de barrières ou réglé par des signaux lumineux.","grave":true,"ref":"Art. 17.2.1° AR 01/12/1975"},{"id":"DEP-021","theme":"depassement","q":"Sur une route à une bande par sens, la voiture devant moi est elle-même en train de dépasser une camionnette. Puis-je la dépasser en même temps ?","choices":["Non","Oui, si la voie est libre"],"answer":0,"explain":"Il est interdit de dépasser un conducteur qui dépasse lui-même un véhicule autre qu'un vélo, un cyclomoteur à deux roues ou une moto à deux roues, sauf s'il y a au moins trois bandes dans le sens suivi.","ref":"Art. 17.2.4° AR 01/12/1975"},{"id":"DEP-023","theme":"depassement","q":"Après ce signal, un cycliste roule devant moi. Le signal m'interdit-il de le dépasser ?","choices":["Non, le C35 ne vise que les véhicules attelés et les véhicules à plus de deux roues","Oui, il interdit tout dépassement"],"answer":0,"explain":"Le C35 interdit seulement le dépassement par la gauche d'un véhicule attelé ou d'un véhicule à plus de deux roues. Un vélo peut être dépassé, à condition de le faire sans danger et en laissant la distance latérale minimale.","sign":"C35","ref":"Art. 68 (signal C35) AR 01/12/1975"},{"id":"DEP-024","theme":"depassement","q":"Jusqu'où vaut l'interdiction imposée par ce signal (sauf signal de fin C37 placé avant) ?","choices":["Sur 1 km","Jusqu'au prochain carrefour inclus","Jusqu'à la sortie de l'agglomération"],"answer":1,"explain":"L'interdiction du C35 vaut à partir du signal jusqu'au prochain carrefour inclus. Le signal C37 indique la fin de l'interdiction.","sign":"C35","ref":"Art. 68 (signaux C35 et C37) AR 01/12/1975"},{"id":"DEP-025","theme":"depassement","q":"En agglomération, je dépasse un cycliste. Quelle distance latérale minimale dois-je laisser ?","choices":["2 mètres","50 cm","1 mètre"],"answer":2,"explain":"Le conducteur d'un véhicule automobile doit laisser une distance latérale d'au moins un mètre entre son véhicule et le cycliste ou le cyclomotoriste à deux roues ; hors agglomération, au moins 1,5 m.","ref":"Art. 40ter AR 01/12/1975"},{"id":"DEP-026","theme":"depassement","q":"Hors agglomération, je dépasse un cycliste. Quelle distance latérale minimale dois-je laisser ?","choices":["1,5 mètre","2 mètres","1 mètre"],"answer":0,"explain":"En dehors des agglomérations, la distance latérale entre le véhicule et le cycliste doit être d'au moins un mètre et demi.","ref":"Art. 40ter AR 01/12/1975"},{"id":"DEP-027","theme":"depassement","q":"Hors agglomération, sur une route étroite avec une ligne continue au milieu, je suis derrière un cycliste. Je ne peux pas laisser 1,5 m sans franchir la ligne. Que dois-je faire ?","choices":["Franchir la ligne continue, puisqu'il s'agit d'un vélo","Rester derrière lui jusqu'à ce que je puisse le dépasser correctement","Le dépasser en le frôlant pour ne pas toucher la ligne"],"answer":1,"explain":"Il est interdit de franchir une ligne continue, et hors agglomération il faut laisser au moins 1,5 m en dépassant un cycliste. Si les deux ne sont pas possibles en même temps, on reste derrière.","grave":true,"ref":"Art. 72.2 et 40ter AR 01/12/1975"},{"id":"DEP-029","theme":"depassement","q":"Je veux tourner à droite pour quitter la chaussée. Que dois-je faire ?","choices":["Tourner sans clignoteur s'il n'y a personne derrière moi","Mettre mon clignoteur droit à temps et serrer le plus possible le bord droit","Me déporter d'abord vers la gauche pour prendre de l'élan"],"answer":1,"explain":"Pour tourner à droite : annoncer à temps avec le clignoteur droit, serrer le plus possible le bord droit, tourner à allure modérée et faire le mouvement aussi court que possible.","ref":"Art. 19.2 AR 01/12/1975"},{"id":"DEP-032","theme":"depassement","q":"Sur une chaussée à deux sens, je veux tourner à gauche. Que dois-je faire ?","choices":["Me porter vers la gauche sans gêner ceux d'en face et leur céder le passage","Tourner directement depuis le bord droit","Passer avant ceux d'en face si j'ai mis mon clignoteur à temps"],"answer":0,"explain":"Pour tourner à gauche sur une chaussée à deux sens : clignoteur gauche à temps, se porter vers la gauche sans gêner le sens inverse, céder le passage aux conducteurs venant en sens inverse, allure modérée.","grave":true,"ref":"Art. 19.3 AR 01/12/1975"},{"id":"DEP-033","theme":"depassement","q":"Je circule sur une chaussée à sens unique et je veux tourner à gauche. Où dois-je me placer ?","choices":["Le plus possible contre le bord droit","Le plus possible contre le bord gauche","Au milieu de la chaussée"],"answer":1,"explain":"Sur une chaussée à sens unique, le conducteur qui tourne à gauche doit serrer le plus possible le bord gauche de celle-ci.","sign":"F19","ref":"Art. 19.3.2°b AR 01/12/1975"},{"id":"DEP-035","theme":"depassement","q":"La circulation s'effectue en plusieurs files. Je suis dans la file de gauche et je veux tourner à droite au prochain carrefour. Puis-je tourner à droite depuis cette file ?","choices":["Oui, avec mon clignoteur","Non, je ne peux tourner à droite que depuis la file de droite"],"answer":1,"explain":"Quand la circulation se fait en bandes ou en files (art. 9.4 et 9.5), on ne peut tourner à droite que depuis la bande ou la file de droite, et à gauche que depuis celle de gauche.","ref":"Art. 19.6 AR 01/12/1975"},{"id":"DEP-036","theme":"depassement","q":"Je fais marche arrière pour sortir d'une allée. Un cycliste arrive sur la chaussée. Qui a la priorité ?","choices":["Le cycliste : je fais une manœuvre et je dois céder le passage","Moi, car j'ai commencé ma manœuvre","Celui qui vient de droite"],"answer":0,"explain":"Effectuer une marche arrière, un demi-tour ou sortir d'une propriété riveraine sont des manœuvres. Le conducteur qui manœuvre doit céder le passage aux autres usagers.","ref":"Art. 12.4 AR 01/12/1975"},{"id":"DEP-037","theme":"depassement","q":"Sur l'autoroute, j'ai manqué ma sortie. Puis-je faire marche arrière sur la bande d'arrêt d'urgence ?","choices":["Oui, si je mets mes feux de détresse","Non, c'est interdit","Oui, si la circulation est fluide"],"answer":1,"explain":"Sur l'autoroute, il est interdit de faire demi-tour, de faire marche arrière ou de rouler en sens contraire. Il faut continuer jusqu'à la sortie suivante.","grave":true,"sign":"F5","ref":"Art. 21.4 et 9.7 AR 01/12/1975"},{"id":"DEP-039","theme":"depassement","q":"La circulation est fortement ralentie et ma bande se termine plus loin. Où dois-je m'intercaler sur la bande voisine ?","choices":["Juste devant le rétrécissement","N'importe où, dès qu'il y a un trou","Dès que je vois le panneau annonçant le rétrécissement"],"answer":0,"explain":"Principe de la tirette : quand la circulation est fortement ralentie, les conducteurs dont la bande prend fin s'intercalent sur la bande libre seulement juste devant le rétrécissement.","sign":"A7a","ref":"Art. 12bis AR 01/12/1975"},{"id":"DEP-040","theme":"depassement","q":"Bouchon : je roule sur la bande qui continue, une bande voisine se termine juste devant. Que dois-je faire au rétrécissement ?","choices":["Laisser passer tous les véhicules de l'autre bande","Laisser passer un conducteur de l'autre bande, tour à tour","Ne laisser passer personne : je suis sur la bande qui continue"],"answer":1,"explain":"Les conducteurs qui circulent sur la bande libre doivent céder tour à tour, juste devant le rétrécissement, la priorité à un conducteur qui s'intercale (fermeture éclair).","sign":"A7a","ref":"Art. 12bis AR 01/12/1975"},{"id":"DEP-041","theme":"depassement","q":"La circulation est fluide (pas de ralentissement) et ma bande se termine. Je veux me placer sur la bande voisine. Qui doit céder le passage ?","choices":["Les conducteurs de la bande voisine, selon la tirette","Moi, car changer de bande est une manœuvre"],"answer":1,"explain":"La tirette ne s'applique que lorsque la circulation est fortement ralentie. Sinon, changer de bande est une manœuvre et le conducteur qui manœuvre doit céder le passage aux autres usagers.","ref":"Art. 12bis et 12.4 AR 01/12/1975"},{"id":"PHA-001","theme":"signalisation","q":"Je conduis une voiture particulière. À droite se trouve un panneau rond à bord rouge avec un camion, complété par « +10t » et « excepté circulation locale ». Puis-je emprunter la voie où ce panneau est placé ?","choices":["Non, l'accès est interdit à tous les véhicules à moteur","Oui, l'interdiction ne vise que les véhicules de transport de marchandises de plus de 10 tonnes","Oui, mais uniquement si j'habite dans le quartier"],"answer":1,"explain":"Le signal C23 interdit l'accès aux véhicules conçus pour le transport de marchandises ; le panneau additionnel « +10t » limite l'interdiction à ceux dont la masse maximale autorisée dépasse 10 tonnes. Une voiture particulière n'est pas concernée.","photo":"0fd37312-d591-4b8a-902d-929db8078e00","focus":"panneau rond à droite et panneaux additionnels bleus","ref":"Art. 68.3 (C23) AR 01/12/1975"},{"id":"PHA-002","theme":"vitesse","q":"Je viens de dépasser le panneau visible à droite. À quelle vitesse maximale puis-je rouler ?","choices":["30 km/h","50 km/h","70 km/h"],"answer":0,"explain":"Le signal C43 indique la vitesse maximale autorisée à partir du panneau : ici 30 km/h.","photo":"1923ca0a-504c-4ae7-868c-ade51ca5b70a","focus":"panneau rond à droite","ref":"Art. 68.3 (C43) AR 01/12/1975"},{"id":"PHA-003","theme":"signalisation","q":"Sous ce feu, un panneau triangulaire montre une bicyclette jaune et une flèche vers la droite. Lorsque ce feu est rouge, puis-je tourner à droite avec ma voiture ?","choices":["Oui, à condition de céder le passage","Non, ce panneau ne concerne que les cyclistes et les speed pedelecs","Oui, si aucun piéton ne traverse"],"answer":1,"explain":"Le panneau B22 autorise uniquement les cyclistes et les conducteurs de speed pedelecs à franchir le feu rouge ou jaune-orange pour tourner à droite, en cédant le passage. Pour un automobiliste, le feu rouge reste une interdiction de franchir la ligne d'arrêt.","grave":true,"photo":"31f298a6-e9cb-41a2-a533-76790779a29d","focus":"panneau triangulaire jaune sous le feu","ref":"Art. 67.3 (B22) et 61.1 AR 01/12/1975"},{"id":"PHA-004","theme":"vitesse","q":"Je quitte la localité par cette route, en Wallonie. Je viens de passer le panneau blanc visible à droite (silhouette de bâtiments barrée de rouge). Sauf autre signalisation, quelle est ma vitesse maximale ?","choices":["50 km/h","70 km/h","90 km/h"],"answer":2,"explain":"Le panneau F3b marque la fin de l'agglomération. En Wallonie, hors agglomération, la vitesse est limitée à 90 km/h sur ce type de route (hors autoroute et route à 2x2 bandes dont les sens sont séparés autrement que par des marques routières).","photo":"5650e541-8ec7-4a2d-ba1a-e8ae9ff5aa12","focus":"panneau blanc barré à droite, au fond","ref":"Art. 2.12 (F3b) et 11.2 (Région wallonne) AR 01/12/1975"},{"id":"PHA-005","theme":"vitesse","q":"Je roule dans la rue commerçante de cette ville wallonne, en pleine agglomération. Aucun panneau de vitesse n'est visible. À quelle vitesse maximale puis-je rouler ?","choices":["30 km/h","50 km/h","70 km/h"],"answer":1,"explain":"En Région wallonne, la vitesse est limitée à 50 km/h dans les agglomérations, sauf autre limitation imposée par un signal C43 ou une zone.","photo":"7158a66f-d956-4b80-94f7-6a9d4033b383","focus":"rue commerçante bordée de magasins","ref":"Art. 11.1 (Région wallonne) AR 01/12/1975"},{"id":"PHA-006","theme":"vitesse","q":"Je roule en voiture en Wallonie, hors agglomération, sur cette route à deux bandes par sens, séparées par une berme centrale en béton. Aucun panneau de limitation n'est visible. Quelle est ma vitesse maximale ?","choices":["120 km/h","90 km/h","70 km/h"],"answer":0,"explain":"Sur les autoroutes et sur les routes à quatre bandes ou plus dont les sens de circulation sont séparés autrement que par des marques routières (berme, glissière), la vitesse est limitée à 120 km/h pour une voiture.","photo":"87bef780-4ba3-4de4-a54c-e2c843f15486","focus":"berme centrale à gauche","ref":"Art. 11.2.1° (Région wallonne) AR 01/12/1975"},{"id":"PHA-007","theme":"signalisation","q":"À droite de ma bande se trouve une zone marquée de lignes blanches obliques. Puis-je y rouler ou m'y arrêter un instant ?","choices":["Oui, pour un arrêt bref","Oui, pour dépasser un véhicule lent","Non, ni circuler, ni s'arrêter, ni stationner"],"answer":2,"explain":"Les lignes parallèles obliques blanches marquent une zone d'évitement : il est interdit d'y circuler, de s'y arrêter et d'y stationner.","photo":"96ac2f7b-fbb3-43cd-8595-09297b0e8de0","focus":"zone hachurée à droite de ma bande","ref":"Art. 77.4 AR 01/12/1975"},{"id":"PHA-008","theme":"vitesse","q":"Je roule dans cette rue en agglomération, en Région de Bruxelles-Capitale. Aucun panneau de vitesse n'est visible. Quelle est ma vitesse maximale ?","choices":["50 km/h","30 km/h","40 km/h"],"answer":1,"explain":"En Région de Bruxelles-Capitale, la vitesse est limitée à 30 km/h dans les agglomérations, sauf si un signal C43 indique une autre limite.","photo":"12a6364e-00c7-4b92-ab21-702e40dfd95f","focus":"rue bruxelloise avec voies de tram","ref":"Art. 11.1 (Région de Bruxelles-Capitale) AR 01/12/1975"},{"id":"PHA-009","theme":"stationnement","q":"Je veux déposer quelqu'un. Puis-je m'arrêter sur la chaussée juste avant ce passage pour piétons, à 3 mètres de celui-ci ?","choices":["Non, l'arrêt est interdit sur le passage et à moins de 5 mètres en deçà","Oui, un arrêt bref est toujours permis","Oui, si je reste au volant avec les feux de détresse"],"answer":0,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 mètres en deçà de ceux-ci, pour garder la visibilité sur les piétons.","photo":"1a1e2e69-037b-4640-bcaf-344ac5b81998","focus":"passage pour piétons au premier plan","ref":"Art. 24, 4° AR 01/12/1975"},{"id":"PHA-010","theme":"signalisation","q":"À l'entrée de cette rue, le panneau rond rouge à barre blanche est complété par un petit panneau montrant une bicyclette. Que signifie ce panneau additionnel ?","choices":["Que les cyclistes doivent mettre pied à terre","Que les cyclistes sont autorisés à entrer malgré le sens interdit","Que la rue est réservée aux cyclistes"],"answer":1,"explain":"Le panneau additionnel M2 sous le signal C1 indique que l'interdiction d'accès ne s'applique pas aux cyclistes : ils peuvent circuler à contresens. Les automobilistes, eux, ne peuvent pas entrer.","photo":"202e1b01-cfbf-4e3c-9713-ce6eef77814b","focus":"panneau à droite","ref":"Art. 68.4 et 65.2 AR 01/12/1975"},{"id":"PHA-011","theme":"signalisation","q":"Je voudrais entrer en voiture dans cette rue, à droite de laquelle se trouve le panneau visible. Est-ce permis ?","choices":["Non, c'est un accès interdit pour moi","Oui, si je roule au pas","Oui, car le panneau additionnel autorise tous les véhicules légers"],"answer":0,"explain":"Le signal C1 interdit l'accès dans ce sens à tous les conducteurs. Le panneau additionnel avec une bicyclette n'exempte que les cyclistes. Entrer en voiture serait circuler à contresens.","grave":true,"photo":"68458974-2354-49d1-be0a-76840f04cb99","focus":"panneau sens interdit à droite","ref":"Art. 68.3 (C1) et 68.4 AR 01/12/1975"},{"id":"PHA-012","theme":"signalisation","q":"Le feu à droite est rouge. Aucune voiture ni aucun piéton n'est en vue. Que dois-je faire ?","choices":["Passer prudemment, puisque la voie est libre","M'arrêter et attendre le vert","Passer en klaxonnant"],"answer":1,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt ou, à défaut, le signal lui-même, même si le carrefour semble libre.","grave":true,"photo":"1c483bce-a15a-44da-aa01-fe46a15e7b3a","focus":"feu sur le poteau à droite","ref":"Art. 61.1, 1° AR 01/12/1975"},{"id":"PHA-013","theme":"priorite","q":"J'arrive à ce carrefour : un panneau triangulaire pointe en bas est placé à droite et une ligne de triangles blancs traverse ma bande. Un bus circule sur la voie que j'aborde. Que dois-je faire ?","choices":["Céder le passage au bus","Passer avant lui, car il vient de ma gauche","Passer, car les bus doivent toujours céder le passage"],"answer":0,"explain":"Le signal B1 m'oblige à céder le passage à tous les usagers de la voie que j'aborde, quel que soit leur côté. La ligne de triangles blancs indique où m'arrêter si nécessaire.","grave":true,"photo":"1f2cad38-1822-422a-9af3-44b05a9033e0","focus":"panneau triangulaire et triangles au sol","ref":"Art. 12.3.1 a) et 76.2 AR 01/12/1975"},{"id":"PHA-014","theme":"signalisation","q":"Le feu est rouge pour moi. Où dois-je arrêter ma voiture ?","choices":["Sur le passage pour piétons, pour mieux voir","Juste avant le feu, même au-delà de la ligne blanche","Avant la ligne d'arrêt, donc avant le passage pour piétons"],"answer":2,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt. Aux carrefours réglés par feux, il faut de toute façon s'arrêter en deçà du passage pour piétons quand la circulation est fermée.","photo":"348b6a7c-80f0-4566-aba2-2ba2e2287195","focus":"feu rouge à droite et ligne blanche au sol","ref":"Art. 61.1, 1° et 40.4.1 AR 01/12/1975"},{"id":"PHA-015","theme":"priorite","q":"À droite, avant le carrefour, se trouve un panneau triangulaire montrant une grosse flèche noire verticale traversée par un trait fin. Que signifie-t-il ?","choices":["J'ai la priorité au prochain carrefour","Je dois céder le passage aux véhicules venant de droite","Carrefour à sens giratoire"],"answer":0,"explain":"Le signal B15 m'indique que j'ai la priorité de passage au carrefour suivant. Je reste toutefois prudent en abordant le carrefour.","photo":"51892c78-31cb-4588-a58f-b9f74605655d","focus":"panneau triangulaire au centre","ref":"Art. 67.3 (B15) et 12.2 AR 01/12/1975"},{"id":"PHA-016","theme":"priorite","q":"J'arrive à l'entrée de ce rond-point, signalé par un panneau bleu à flèches circulaires sous un triangle pointe en bas. Un véhicule circule déjà sur l'anneau. Que dois-je faire ?","choices":["Entrer, car il vient de ma gauche","Lui céder le passage","Entrer en klaxonnant"],"answer":1,"explain":"Les accès d'un rond-point sont pourvus du signal B1 : le conducteur qui y entre doit céder le passage à ceux qui circulent sur l'anneau.","grave":true,"photo":"54a76fe8-3d4c-48f8-aa10-c672e92a1b75","focus":"panneaux au centre","ref":"Art. 2.39 et 12.3.1 a) AR 01/12/1975"},{"id":"PHA-017","theme":"priorite","q":"Pour entrer dans ce rond-point, dois-je enclencher mon clignotant ?","choices":["Oui, à gauche","Oui, à droite","Non, ce n'est pas obligatoire pour entrer"],"answer":2,"explain":"Entrer dans un rond-point est un changement de direction qui n'implique pas l'usage des indicateurs de direction. En revanche, il faut mettre le clignotant pour en sortir.","photo":"54a76fe8-3d4c-48f8-aa10-c672e92a1b75","focus":"panneaux au centre","ref":"Art. 19.2, 1° AR 01/12/1975"},{"id":"PHA-018","theme":"usagers","q":"Je roule en voiture. Puis-je emprunter ce couloir coloré marqué d'un vélo, à droite des voitures garées, pour circuler plus facilement ?","choices":["Oui, si aucun cycliste n'arrive","Oui, au pas","Non, je dois rester sur la chaussée"],"answer":2,"explain":"Les conducteurs doivent emprunter la chaussée. La piste cyclable ne fait pas partie de la chaussée et est réservée aux cyclistes et cyclomotoristes classe A.","photo":"7880a546-9e7d-4f52-a6c1-f6b67d8c7f5e","focus":"couloir marqué d'un vélo","ref":"Art. 9.1.1 et 2.7 AR 01/12/1975"},{"id":"PHA-019","theme":"signalisation","q":"Qu'indique le panneau carré bleu avec une flèche blanche vers le haut, visible à droite au fond de la rue ?","choices":["Une voie publique à sens unique","L'obligation de tourner à droite","Une route prioritaire"],"answer":0,"explain":"Le signal F19 indique une voie publique à sens unique : je peux y entrer dans le sens de la flèche.","photo":"decdf67c-2757-4289-9f45-15ff8eb89143","focus":"panneau carré bleu à droite","ref":"Art. 71 (F19) AR 01/12/1975"},{"id":"PHA-020","theme":"usagers","q":"Je veux tourner à droite au carrefour. Une piétonne est engagée sur le passage pour piétons de la rue où je veux m'engager. Que dois-je faire ?","choices":["La laisser traverser avant de passer","Passer devant elle si j'ai le temps","Klaxonner pour l'avertir"],"answer":0,"explain":"Le conducteur qui change de direction doit céder le passage aux piétons qui traversent la chaussée sur laquelle il va s'engager ; il doit aussi céder le passage aux piétons engagés sur un passage pour piétons (et, aux carrefours à feux, les laisser achever leur traversée même si le feu est vert pour lui).","grave":true,"photo":"1b36356f-e1cc-4684-8859-02d71abebebf","focus":"piétonne à droite","ref":"Art. 19.5 et 40.4 AR 01/12/1975"},{"id":"PHA-021","theme":"priorite","q":"Sous le feu de droite se trouve un panneau triangulaire pointe en bas. Si les feux de ce carrefour sont éteints (hors service), quelle règle dois-je appliquer ?","choices":["La priorité de droite","Je dois céder le passage aux usagers de la voie que j'aborde","J'ai la priorité, car les feux sont hors service"],"answer":1,"explain":"Les signaux de priorité ne sont sans effet que lorsque les feux fonctionnent. Feux éteints, le signal B1 s'applique : je cède le passage à tous les usagers de la voie que j'aborde.","grave":true,"photo":"44533adc-43d7-4638-9ca5-e2b6ca4e4fd7","focus":"panneau sous le feu à droite","ref":"Art. 6.3 et 12.3.1 a) AR 01/12/1975"},{"id":"PHB-001","theme":"priorite","q":"J'arrive à ce carrefour, où un panneau triangulaire pointe en bas est placé à droite. Une voiture circule sur la rue que je vais aborder. Que dois-je faire ?","choices":["Je passe, car elle vient de ma gauche","Je lui cède le passage","Je klaxonne et je m'engage"],"answer":1,"explain":"Le signal B1 (cédez le passage) m'oblige à céder le passage à tous les conducteurs qui circulent sur la voie que j'aborde, qu'ils viennent de gauche ou de droite.","grave":true,"photo":"144dbb19-8ca6-49f9-be62-9c751cd90c0b","focus":"panneau triangulaire à droite","ref":"Art. 12.3.1 a) et 67.3 AR 01/12/1975"},{"id":"PHB-002","theme":"signalisation","q":"Devant ce panneau triangulaire pointe en bas, dois-je obligatoirement marquer l'arrêt complet, même si personne n'arrive ?","choices":["Non, je dois seulement céder le passage ; je m'arrête si nécessaire","Oui, l'arrêt est toujours obligatoire","Oui, mais seulement la nuit"],"answer":0,"explain":"Le B1 impose de céder le passage, pas de s'arrêter systématiquement. L'arrêt obligatoire est imposé par le signal B5 (STOP). Je ne poursuis ma route que si je peux le faire sans risque d'accident.","photo":"144dbb19-8ca6-49f9-be62-9c751cd90c0b","focus":"panneau triangulaire à droite","ref":"Art. 12.3.1, 12.5 et 67.3 AR 01/12/1975"},{"id":"PHB-003","theme":"vitesse","q":"Je circule dans cette rue de Charleroi. À quelle vitesse maximale puis-je rouler après le panneau rond visible à droite ?","choices":["50 km/h","70 km/h","30 km/h"],"answer":2,"explain":"Le signal C43 indique la vitesse maximale autorisée : ici 30 km/h. Il remplace la limite générale de 50 km/h applicable en agglomération en Wallonie.","photo":"65ca4a7f-3cec-4426-8313-e46aed8b1f36","focus":"panneau rond à droite","ref":"Art. 11.1 (Région wallonne) et 68 (C43) AR 01/12/1975"},{"id":"PHB-004","theme":"depassement","q":"La voiture qui me précède ralentit à l'approche du passage pour piétons (sans feux ni agent). Puis-je la dépasser ?","choices":["Oui, si aucun piéton n'est visible","Non, c'est interdit","Oui, à condition de klaxonner"],"answer":1,"explain":"Il est interdit de dépasser un véhicule qui s'approche d'un passage pour piétons ou s'arrête devant celui-ci lorsque la circulation n'y est pas réglée par des feux ou un agent : il peut masquer un piéton.","grave":true,"photo":"65ca4a7f-3cec-4426-8313-e46aed8b1f36","focus":"passage pour piétons devant la voiture noire","ref":"Art. 17.2.5° AR 01/12/1975"},{"id":"PHB-005","theme":"priorite","q":"Le panneau triangulaire à droite contient une croix noire. Au prochain carrefour, un véhicule arrive de ma droite. Qui a la priorité ?","choices":["Le véhicule venant de ma droite","Moi, car je roule tout droit","Celui qui arrive le premier"],"answer":0,"explain":"Le signal B17 annonce un carrefour où la priorité de droite est applicable : je dois céder le passage à celui qui vient de ma droite.","grave":true,"photo":"9ae2dd24-c6c0-4ad0-9505-3fd836501880","focus":"panneau triangulaire à droite","ref":"Art. 12.3.1 et 67.3 (B17) AR 01/12/1975"},{"id":"PHB-006","theme":"depassement","q":"Dans le carrefour annoncé par ce panneau (croix noire dans un triangle), puis-je dépasser la voiture qui me précède ?","choices":["Oui, si la voie est libre en face","Oui, mais uniquement par la droite","Non"],"answer":2,"explain":"Dans les carrefours où la priorité de droite est applicable, il est interdit de dépasser par la gauche un véhicule à plus de deux roues (ou un véhicule à moteur à deux roues). Seul le dépassement d'une bicyclette y reste possible.","grave":true,"photo":"9ae2dd24-c6c0-4ad0-9505-3fd836501880","focus":"panneau triangulaire à droite","ref":"Art. 17.2.2° a) AR 01/12/1975"},{"id":"PHB-007","theme":"stationnement","q":"Un panneau bleu « P » est placé sur le trottoir de droite. De quel côté de la rue autorise-t-il le stationnement ?","choices":["Du côté droit, où il est placé, jusqu'au prochain carrefour","Des deux côtés de la rue","Uniquement du côté gauche"],"answer":0,"explain":"Les signaux E1, E3, E5, E7 et E9a à E9j ont effet du côté de la voie publique où ils sont placés, à partir du signal jusqu'au prochain carrefour.","photo":"0d3e8898-0086-4e1b-89c8-03b7ea3bae9a","focus":"panneau P à droite","ref":"Art. 70.2.2 AR 01/12/1975"},{"id":"PHB-008","theme":"stationnement","q":"Puis-je laisser ma voiture en stationnement sur la chaussée à 3 mètres avant le passage pour piétons visible au premier plan ?","choices":["Oui, puisque je ne suis pas sur les bandes blanches","Non, il faut être au moins à 5 mètres avant le passage","Oui, si mes feux de détresse sont allumés"],"answer":1,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 mètres en deçà de ceux-ci, pour préserver la visibilité des piétons.","photo":"0d3e8898-0086-4e1b-89c8-03b7ea3bae9a","focus":"passage pour piétons au premier plan","ref":"Art. 24.4° AR 01/12/1975"},{"id":"PHB-009","theme":"usagers","q":"Le panneau bleu « Fahrrad Zone » (zone cyclable) est visible sur le poteau, à Eupen. Dans la zone qu'il annonce, je roule en voiture derrière un cycliste. Puis-je le dépasser ?","choices":["Oui, si je laisse au moins 1 mètre","Oui, si je ne dépasse pas 30 km/h","Non, je dois rester derrière lui"],"answer":2,"explain":"Le signal F111 indique le début d'une zone cyclable. Les véhicules à moteur y sont admis mais ne peuvent pas dépasser les cyclistes, et la vitesse n'y est jamais supérieure à 30 km/h.","grave":true,"photo":"7b75ec09-4c75-44bc-a53f-6c35364b75d2","focus":"panneau bleu « Fahrrad Zone » sur le poteau","ref":"Art. 2.61, 22novies et 71 (F111) AR 01/12/1975"},{"id":"PHB-010","theme":"stationnement","q":"Le poteau jaune indique un arrêt de bus. Puis-je stationner ma voiture sur la chaussée à 10 mètres de ce panneau ?","choices":["Non, le stationnement est interdit à moins de 15 mètres de part et d'autre","Oui, l'interdiction ne vaut qu'à moins de 5 mètres","Oui, si aucun bus n'est en vue"],"answer":0,"explain":"Il est interdit de stationner à moins de 15 mètres de part et d'autre d'un panneau indiquant un arrêt d'autobus, de trolleybus ou de tram.","photo":"7b75ec09-4c75-44bc-a53f-6c35364b75d2","focus":"poteau jaune « BUS »","ref":"Art. 25.1.2° AR 01/12/1975"},{"id":"PHB-011","theme":"priorite","q":"Je circule sur cette route où est placé un panneau en losange blanc et orange. Au prochain carrefour, une voiture arrive d'une rue à ma droite. Qui doit céder le passage ?","choices":["Moi, car la priorité de droite s'applique toujours","La voiture venant de droite","Personne, le premier arrivé passe"],"answer":1,"explain":"Le signal B9 indique une voie prioritaire : les conducteurs qui débouchent des voies transversales (pourvues d'un B1 ou d'un B5) doivent me céder le passage.","grave":true,"photo":"41dfad6b-4819-4eaf-b298-b9245cf45337","focus":"panneau losange en haut à droite","ref":"Art. 12.3.1 et 67.3 (B9) AR 01/12/1975"},{"id":"PHB-012","theme":"stationnement","q":"Un panneau rond bleu bordé de rouge, barré d'une seule diagonale, est fixé sur le mur à droite. Puis-je laisser ma voiture garée de ce côté pendant une heure ?","choices":["Oui, si je mets le disque de stationnement","Oui, si je reste dans la voiture","Non"],"answer":2,"explain":"Le signal E1 interdit le stationnement du côté où il est placé, jusqu'au prochain carrefour. Rester une heure immobilisé, c'est du stationnement.","photo":"6e3fe9a7-0948-4838-bd3f-d0b9e6fe587a","focus":"panneau rond sur le mur à droite","ref":"Art. 2.23, 70.2.1 et 70.2.2 (E1) AR 01/12/1975"},{"id":"PHB-013","theme":"stationnement","q":"Après le même panneau (rond bleu, bord rouge, une seule diagonale), puis-je m'arrêter à droite juste le temps de faire descendre un passager ?","choices":["Oui, l'arrêt reste permis","Non, l'arrêt est aussi interdit","Oui, mais seulement avec les feux de détresse"],"answer":0,"explain":"Le signal E1 interdit uniquement le stationnement. L'arrêt (le temps d'embarquer ou de débarquer des personnes ou des choses) reste autorisé, sauf s'il crée un danger. C'est le signal E3 (deux diagonales) qui interdit aussi l'arrêt.","photo":"6e3fe9a7-0948-4838-bd3f-d0b9e6fe587a","focus":"panneau rond sur le mur à droite","ref":"Art. 2.22 et 70.2.1 (E1, E3) AR 01/12/1975"},{"id":"PHB-014","theme":"stationnement","q":"La bordure du trottoir de droite est peinte d'une ligne jaune discontinue. Puis-je y stationner ma voiture ?","choices":["Oui, seulement le dimanche","Non, le stationnement y est interdit","Oui, la ligne jaune n'est qu'une décoration"],"answer":1,"explain":"Une ligne discontinue jaune tracée sur la bordure du trottoir signifie que le stationnement est interdit sur la chaussée le long de cette ligne.","photo":"8c5ac9a1-f0a1-4c96-bb82-1c0f2dc31730","focus":"bordure jaune à droite","ref":"Art. 75.1.2° et 25.1.10° AR 01/12/1975"},{"id":"PHB-015","theme":"stationnement","q":"Le long de cette ligne jaune discontinue, puis-je m'arrêter brièvement pour décharger un colis ?","choices":["Non, ni arrêt ni stationnement","Oui, seulement si j'ai une camionnette","Oui, l'arrêt est permis si je ne crée pas de danger"],"answer":2,"explain":"La ligne jaune discontinue n'interdit que le stationnement. L'arrêt, limité au temps de charger ou décharger, reste possible s'il ne gêne ni ne met en danger les autres usagers.","photo":"8c5ac9a1-f0a1-4c96-bb82-1c0f2dc31730","focus":"bordure jaune à droite","ref":"Art. 2.22, 24 et 75.1.2° AR 01/12/1975"},{"id":"PHB-016","theme":"depassement","q":"La ligne au milieu de cette chaussée est discontinue. Un véhicule lent me précède et je vois loin devant que personne n'arrive en face. Puis-je franchir cette ligne pour le dépasser ?","choices":["Oui","Non, une ligne au milieu ne peut jamais être franchie","Non, sauf pour tourner à gauche"],"answer":0,"explain":"Une ligne discontinue peut être franchie pour dépasser, tourner à gauche, faire demi-tour ou changer de bande, à condition de voir suffisamment loin pour dépasser sans risque.","photo":"994ea93e-788f-4643-af3c-7b9e71ebd4bf","focus":"ligne discontinue au milieu","ref":"Art. 72.3 et 17.1 AR 01/12/1975"},{"id":"PHB-017","theme":"usagers","q":"J'approche de ce passage pour piétons, sans feux ni agent. Un piéton se trouve sur le trottoir, sur le point de traverser. Que dois-je faire ?","choices":["Continuer : il doit attendre que la rue soit libre","Lui céder le passage","Klaxonner pour l'avertir que je passe"],"answer":1,"explain":"À un passage pour piétons non réglé, je dois m'approcher à allure modérée et céder le passage aux piétons qui y sont engagés ou sont sur le point de s'y engager.","grave":true,"photo":"bea00f5f-6d81-40a8-ae4c-f5236eb39cd2","focus":"passage pour piétons au fond","ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"PHB-018","theme":"vitesse","q":"Je circule dans cette rue commerçante, en agglomération à Dinant (Wallonie). Je n'ai rencontré aucun panneau de limitation de vitesse. Quelle est la vitesse maximale ?","choices":["50 km/h","30 km/h","70 km/h"],"answer":0,"explain":"En Région wallonne, la vitesse est limitée à 50 km/h dans les agglomérations, sauf autre limitation imposée par un signal C43 ou une zone 30. (À Bruxelles, la règle générale en agglomération est 30 km/h.)","photo":"bea00f5f-6d81-40a8-ae4c-f5236eb39cd2","focus":"rue commerçante bordée de magasins","ref":"Art. 11.1 (Région wallonne) AR 01/12/1975"},{"id":"PHB-019","theme":"stationnement","q":"Puis-je m'arrêter sur ce passage pour piétons, le temps de déposer un passager ?","choices":["Oui, si c'est très rapide","Oui, si aucun piéton n'attend","Non, l'arrêt y est interdit"],"answer":2,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 mètres en deçà de ceux-ci.","photo":"fdc63349-d486-4b70-9e89-2a048a932236","focus":"passage pour piétons au premier plan","ref":"Art. 24.4° AR 01/12/1975"},{"id":"PHC-001","theme":"vitesse","q":"Je roule en ville à Liège (Wallonie), sur cette avenue bordée d'immeubles, en agglomération. Si aucun signal n'impose une autre limite, quelle est ma vitesse maximale ?","choices":["30 km/h","50 km/h","70 km/h"],"answer":1,"explain":"En agglomération en Région wallonne, la vitesse est limitée à 50 km/h, sauf signal C43 contraire. (À Bruxelles, la règle générale est 30 km/h.)","photo":"2044356e-cd70-4ccb-b710-147cd33436c7","focus":"immeubles des deux côtés : agglomération","ref":"Art. 11.1 (Région wallonne) AR 01/12/1975"},{"id":"PHC-002","theme":"signalisation","q":"Le feu au-dessus de la chaussée est rouge. Jusqu'où puis-je avancer ?","choices":["Je peux m'engager lentement si personne ne vient","Je ne peux pas franchir la ligne d'arrêt ou, à défaut, le feu lui-même","Je peux avancer jusqu'au milieu du carrefour"],"answer":1,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt ou, s'il n'y en a pas, le signal lui-même. Brûler un feu rouge est une faute grave.","grave":true,"photo":"3590b816-adb5-497e-8daf-a689249c484c","focus":"feu rouge au-dessus de la chaussée","ref":"Art. 61.1.1° AR 01/12/1975"},{"id":"PHC-003","theme":"priorite","q":"Je circule dans cette rue et je vois le panneau triangulaire fixé au poteau à droite. Que signifie-t-il pour moi ?","choices":["Au prochain carrefour, j'ai la priorité","Au prochain carrefour, je dois céder le passage à droite","Fin de la route prioritaire"],"answer":0,"explain":"Le signal B15 (flèche noire épaisse croisant une barre) annonce que j'ai priorité de passage au prochain carrefour. Je reste prudent à l'approche du carrefour.","grave":true,"photo":"37607a92-1aed-4e57-bfa4-a45c5422ac36","focus":"panneau triangulaire sur le poteau à droite","ref":"Art. 67.3 (B15) et 12.2 AR 01/12/1975"},{"id":"PHC-005","theme":"stationnement","q":"Devant moi, la route entre dans un tunnel. Puis-je m'arrêter sur la chaussée dans ce tunnel pour attendre un passager ?","choices":["Oui, avec les feux de détresse allumés","Oui, pendant moins de 2 minutes","Non, l'arrêt et le stationnement y sont interdits"],"answer":2,"explain":"Il est interdit de s'arrêter ou de stationner sur la chaussée dans les tunnels et les passages inférieurs (sauf panne ou nécessité de la circulation).","photo":"53576ac0-e4be-4854-8fdd-a5700e498d4b","focus":"entrée du tunnel au fond","ref":"Art. 24, 5° AR 01/12/1975"},{"id":"PHC-006","theme":"vitesse","q":"Le panneau rond à droite affiche « 50 » avec un panneau additionnel « RAPPEL ». À quelle vitesse maximale puis-je rouler ?","choices":["50 km/h","70 km/h","90 km/h"],"answer":0,"explain":"Le signal C43 « 50 » impose une vitesse maximale de 50 km/h. Le panneau « RAPPEL » rappelle simplement une limitation déjà en vigueur.","photo":"3f7a2882-d7df-4844-b6d5-dcc5143517b3","focus":"panneau rond « 50 » à droite","ref":"Art. 11.1 et 68.3 (C43) AR 01/12/1975"},{"id":"PHC-007","theme":"stationnement","q":"Le panneau « P » à droite est complété par un panneau additionnel « TAXIS ». Puis-je y stationner ma voiture personnelle ?","choices":["Oui, c'est un parking public","Non, le stationnement y est réservé aux taxis","Oui, mais seulement 15 minutes"],"answer":1,"explain":"Une inscription sous le signal E9a peut indiquer la catégorie de véhicules à laquelle le stationnement est réservé, par exemple les taxis.","photo":"7dbfacc8-e241-4b64-82e1-b06b9c286c00","focus":"panneau « P » + « TAXIS » à droite","ref":"Art. 70.2.1, 3° a) AR 01/12/1975"},{"id":"PHC-008","theme":"stationnement","q":"Je veux déposer un passager juste avant ce passage pour piétons, à environ 3 mètres des bandes blanches. Est-ce permis ?","choices":["Oui, l'arrêt est toujours permis pour déposer quelqu'un","Non, l'arrêt est interdit sur le passage et à moins de 5 m en deçà"],"answer":1,"explain":"Il est interdit de s'arrêter ou de stationner sur un passage pour piétons et sur la chaussée à moins de 5 mètres en deçà de celui-ci.","photo":"847e85bf-6e52-4e1d-ab0b-b5fb01a282f8","focus":"passage pour piétons devant moi","ref":"Art. 24, 4° AR 01/12/1975"},{"id":"PHC-009","theme":"signalisation","q":"Que m'annonce le panneau triangulaire à droite, avec un cycliste ?","choices":["Une piste cyclable obligatoire pour moi","Un passage pour cyclistes ou un endroit où des cyclistes débouchent d'une piste cyclable","Une rue interdite aux voitures"],"answer":1,"explain":"Le signal A25 annonce un passage pour cyclistes et cyclomotoristes, ou un endroit où ils quittent une piste cyclable pour rejoindre la chaussée. Je ralentis et je reste attentif.","photo":"88dd0d72-d6b7-4d64-9cb0-fafbf1ae91d2","focus":"triangle avec vélo à droite","ref":"Art. 66 (A25) AR 01/12/1975"},{"id":"PHC-010","theme":"vitesse","q":"Le panneau « 50 » à gauche est complété par un panneau additionnel « 150 m ». Que signifie cette indication ?","choices":["La limitation de 50 km/h commence environ 150 m plus loin","La limitation ne vaut que sur 150 m","Je dois rouler à 50 km/h dès maintenant"],"answer":0,"explain":"Un signal d'interdiction complété par une distance annonce l'endroit où l'interdiction commence, ici environ 150 m plus loin.","photo":"e5738aeb-7287-43a4-b0d2-cc8618dcb126","focus":"panneau « 50 » + « 150 m »","ref":"Art. 68.2 AR 01/12/1975"},{"id":"PHC-011","theme":"usagers","q":"La bande de droite porte les inscriptions « BUS » et « TAXI ». Puis-je l'emprunter avec ma voiture pour dépasser la file ?","choices":["Non","Oui, si je roule à 50 km/h maximum","Oui, s'il n'y a pas de bus en vue"],"answer":0,"explain":"Une bande réservée aux bus n'est pas destinée aux voitures : on ne peut l'emprunter que pour contourner un obstacle, accéder à une propriété ou un stationnement, ou (bande bus) tourner au carrefour tout proche.","photo":"e5738aeb-7287-43a4-b0d2-cc8618dcb126","focus":"marquage « BUS / TAXI » à droite","ref":"Art. 72.5 AR 01/12/1975"},{"id":"PHC-012","theme":"priorite","q":"Le panneau bleu carré (grande flèche blanche vers le haut, petite flèche rouge vers le bas) est placé au-dessus du triangle. Au passage étroit, qui passe en premier ?","choices":["Moi, j'ai la priorité sur les conducteurs venant en sens inverse","Les conducteurs venant en sens inverse","Celui qui vient de droite"],"answer":0,"explain":"Le signal B21 donne la priorité de passage par rapport aux conducteurs venant en sens opposé. Je dois tout de même éviter un accident si l'autre est déjà engagé.","photo":"74d09b8e-59db-4c6e-a310-2ead17b247cd","focus":"panneau bleu à droite","ref":"Art. 67.3 (B21) AR 01/12/1975"},{"id":"PHC-013","theme":"signalisation","q":"Que m'annonce le panneau triangulaire placé sous le panneau bleu ?","choices":["Une route à deux sens de circulation","Un rétrécissement de la chaussée","Un pont mobile"],"answer":1,"explain":"Le signal A7 (deux lignes qui se rapprochent) annonce un rétrécissement de la chaussée.","photo":"74d09b8e-59db-4c6e-a310-2ead17b247cd","focus":"triangle à droite","ref":"Art. 66 (A7) AR 01/12/1975"},{"id":"PHC-014","theme":"usagers","q":"Un joggeur court sur la chaussée et vient vers moi. Que dois-je faire ?","choices":["Klaxonner pour qu'il dégage la chaussée","Ralentir et le croiser en lui laissant suffisamment d'espace","Garder ma vitesse, il doit se ranger"],"answer":1,"explain":"Le conducteur ne peut pas mettre en danger les piétons qui circulent sur la chaussée. Je ralentis et laisse une distance latérale d'au moins 1 m (1,5 m hors agglomération) ; sinon je roule à l'allure du pas.","grave":true,"photo":"74d09b8e-59db-4c6e-a310-2ead17b247cd","focus":"joggeur au centre","ref":"Art. 40.1 et 40.7 AR 01/12/1975"},{"id":"PHC-016","theme":"stationnement","q":"Je cherche une place près de cet arrêt de bus (poteau jaune à gauche). À quelle distance minimale du panneau d'arrêt puis-je stationner ?","choices":["5 mètres","10 mètres","15 mètres de part et d'autre"],"answer":2,"explain":"Il est interdit de stationner à moins de 15 mètres de part et d'autre d'un panneau indiquant un arrêt d'autobus, de trolleybus ou de tram.","photo":"7c34dd00-03d7-4c3e-955d-2a8aadbbaa20","focus":"poteau jaune de l'arrêt","ref":"Art. 25.1, 2° AR 01/12/1975"},{"id":"PHC-017","theme":"usagers","q":"Ce car est arrêté à l'arrêt de bus. S'il embarque ou débarque des voyageurs et que je dois le longer, que dois-je faire ?","choices":["Modérer ma vitesse","Klaxonner pour signaler ma présence","Accélérer pour le dépasser avant qu'il ne reparte"],"answer":0,"explain":"Le conducteur doit modérer sa vitesse pour longer un autocar ou un autobus arrêté pour l'embarquement ou le débarquement des voyageurs.","photo":"7c34dd00-03d7-4c3e-955d-2a8aadbbaa20","focus":"car à l'arrêt, poteau jaune à gauche","ref":"Art. 40.3.1 AR 01/12/1975"},{"id":"PHC-018","theme":"vitesse","q":"Je suis en ville à Nivelles (Wallonie), dans cette rue bordée de maisons. Aucun panneau de vitesse n'est visible. Vitesse maximale ?","choices":["70 km/h","30 km/h","50 km/h"],"answer":2,"explain":"En agglomération en Région wallonne, la vitesse est limitée à 50 km/h, sauf signal C43 imposant une autre limite.","photo":"a020b120-188b-4b7d-9407-313c18eadf0b","focus":"rue bordée de maisons, passage pour piétons : agglomération","ref":"Art. 11.1 (Région wallonne) AR 01/12/1975"},{"id":"PHC-020","theme":"signalisation","q":"Dans un rond-point comme celui-ci (signal D5 sur l'îlot central), quand dois-je utiliser mes clignotants ?","choices":["En entrant et en sortant","Seulement en entrant","Seulement en sortant"],"answer":2,"explain":"Entrer dans un rond-point n'implique pas l'usage des indicateurs de direction ; en sortir est un changement de direction qui l'impose.","photo":"a49b447f-9b02-48c7-9931-db438907aab2","focus":"rond-point","ref":"Art. 19.2, 1° AR 01/12/1975"},{"id":"PHD-001","theme":"priorite","q":"J'arrive à ce rond-point : un panneau triangulaire rouge et blanc pointe vers le bas à droite et des triangles blancs sont peints au sol. Si une voiture circule déjà sur l'anneau, à ma gauche, que dois-je faire ?","choices":["M'engager : elle vient de ma gauche, j'ai donc la priorité","Lui céder le passage avant de m'engager","M'engager si je roule plus vite qu'elle"],"answer":1,"explain":"Le panneau B1 (cédez le passage) m'oblige à céder le passage à tout conducteur circulant sur la voie que j'aborde, ici l'anneau du rond-point. La priorité de droite ne s'applique pas.","grave":true,"photo":"8c3a0ffb-6fd0-45a3-9bef-cd0fff16e3be","focus":"panneau triangulaire à droite","ref":"Art. 12.3.1, a) et 67.3 (B1) AR 01/12/1975"},{"id":"PHD-002","theme":"signalisation","q":"Que signifie la ligne de triangles blancs peinte en travers de ma bande, juste avant l'anneau ?","choices":["L'endroit où je dois, s'il y a lieu, m'arrêter pour céder le passage","Un ralentisseur qui impose 30 km/h","Une ligne d'arrêt où je dois toujours m'arrêter, même si l'anneau est libre"],"answer":0,"explain":"Les « dents de requin » indiquent où s'arrêter si nécessaire pour céder le passage imposé par le signal B1. Si la voie est libre, je ne dois pas obligatoirement m'arrêter.","photo":"8c3a0ffb-6fd0-45a3-9bef-cd0fff16e3be","focus":"triangles blancs au sol","ref":"Art. 76.2 AR 01/12/1975"},{"id":"PHD-003","theme":"priorite","q":"Si un cycliste circule sur la bande rouge qui longe l'anneau, juste devant l'endroit où je vais m'engager, qui passe en premier ?","choices":["Moi, car le cycliste doit céder le passage aux voitures","Le cycliste, car je dois céder le passage à tout usager circulant sur la voie que j'aborde"],"answer":1,"explain":"Le signal B1 m'impose de céder le passage à tout autre conducteur circulant sur la voie publique que j'aborde, y compris les cyclistes qui circulent dans le rond-point.","grave":true,"photo":"8c3a0ffb-6fd0-45a3-9bef-cd0fff16e3be","focus":"bande rouge autour de l'anneau","ref":"Art. 12.3.1, a) AR 01/12/1975"},{"id":"PHD-004","theme":"signalisation","q":"Que signifie le panneau rond bleu à flèches blanches en cercle, placé sur l'îlot central ?","choices":["Parking circulaire","Priorité aux véhicules qui entrent dans le rond-point","Sens giratoire obligatoire"],"answer":2,"explain":"Le signal D5 impose de tourner autour de l'îlot dans le sens indiqué par les flèches. Ce n'est pas un signal de priorité : celle-ci est réglée ici par le B1.","photo":"8c3a0ffb-6fd0-45a3-9bef-cd0fff16e3be","focus":"panneau bleu sur l'îlot central","ref":"Art. 69 (D5) AR 01/12/1975"},{"id":"PHD-005","theme":"priorite","q":"Le panneau carré jaune bordé de blanc, posé sur la pointe, sur le poteau rouge et blanc à droite, m'indique que…","choices":["je circule sur une voie prioritaire","je dois céder le passage au prochain carrefour","la priorité de droite s'applique au prochain carrefour"],"answer":0,"explain":"Le signal B9 indique une voie prioritaire : aux carrefours, les conducteurs venant des voies transversales doivent me céder le passage.","photo":"264a16a7-76b6-4ae2-8781-0dbd1c38b3b8","focus":"panneau jaune sur le poteau rouge et blanc","ref":"Art. 67.3 (B9) AR 01/12/1975"},{"id":"PHD-006","theme":"stationnement","q":"Puis-je arrêter ma voiture sur le passage pour piétons au premier plan, ou à 3 mètres juste avant ?","choices":["Oui, pour un arrêt de moins de deux minutes","Non, c'est interdit sur le passage et à moins de 5 m en deçà","Oui, si j'allume mes feux de détresse"],"answer":1,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 mètres en deçà de ceux-ci.","photo":"264a16a7-76b6-4ae2-8781-0dbd1c38b3b8","focus":"passage pour piétons au premier plan","ref":"Art. 24, 4° AR 01/12/1975"},{"id":"PHD-007","theme":"usagers","q":"La file avance lentement. Puis-je emprunter la bande marquée « BUS », à droite, pour remonter la file ?","choices":["Oui, si aucun bus n'arrive","Non : je ne peux y circuler que dans des cas précis, par exemple pour contourner un obstacle ou tourner à l'approche immédiate d'un carrefour","Oui, en agglomération uniquement"],"answer":1,"explain":"La bande bus est réservée aux transports en commun réguliers (et aux véhicules autorisés par le signal). Les autres véhicules peuvent seulement l'emprunter pour contourner un obstacle, tourner à l'approche immédiate d'un carrefour ou la traverser.","photo":"2cdf4b43-4ab4-41dd-a92e-2b2eff0cc095","focus":"bande « BUS » à droite","ref":"Art. 72.5 AR 01/12/1975"},{"id":"PHD-008","theme":"signalisation","q":"Je suis dans la bande où est peinte une flèche tout droit. Puis-je tourner à gauche au carrefour ?","choices":["Non, je dois suivre la direction indiquée par la flèche de ma bande","Oui, si personne ne vient en face"],"answer":0,"explain":"Les flèches de sélection marquent la bande à suivre pour chaque direction : au carrefour, je dois suivre la direction indiquée sur ma bande. Pour tourner à gauche, il fallait se placer dans la bande de gauche.","photo":"2cdf4b43-4ab4-41dd-a92e-2b2eff0cc095","focus":"flèche au sol dans ma bande","ref":"Art. 77.1 AR 01/12/1975"},{"id":"PHD-009","theme":"signalisation","q":"Les feux au fond sont rouges. Que dois-je faire ?","choices":["Passer si je tourne à droite et que personne ne vient","M'arrêter avant la ligne d'arrêt ou, à défaut, avant le feu","Ralentir et passer prudemment"],"answer":1,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt ou, à défaut de ligne d'arrêt, le signal lui-même. Le franchir est une faute grave.","grave":true,"photo":"2cdf4b43-4ab4-41dd-a92e-2b2eff0cc095","focus":"feux au fond","ref":"Art. 61.1, 1° AR 01/12/1975"},{"id":"PHD-010","theme":"stationnement","q":"Puis-je stationner sur la chaussée de cette route divisée en bandes de circulation (aucun panneau de stationnement visible) ?","choices":["Oui, le long du bord droit","Oui, si je laisse 3 m de passage","Non, sauf aux endroits pourvus d'un signal E9a ou E9b"],"answer":2,"explain":"Le stationnement est interdit sur la chaussée lorsque celle-ci est divisée en bandes de circulation, sauf aux endroits signalés par un E9a ou E9b.","photo":"2cdf4b43-4ab4-41dd-a92e-2b2eff0cc095","focus":"bandes de circulation","ref":"Art. 25.1, 9° AR 01/12/1975"},{"id":"PHD-011","theme":"vitesse","q":"Je roule dans cette rue commerçante du centre de Verviers (Wallonie), en agglomération. Si aucun signal n'impose une autre limite, quelle est ma vitesse maximale ?","choices":["30 km/h","50 km/h","70 km/h"],"answer":1,"explain":"En Région wallonne, la vitesse est limitée à 50 km/h dans les agglomérations, sauf si un signal C43 ou une zone 30 impose une autre limite. (À Bruxelles, la règle générale est 30 km/h.)","photo":"818b86bc-773f-4c10-a769-550117b44c8d","focus":"bâtiments urbains, agglomération","ref":"Art. 11.1 (Région wallonne) AR 01/12/1975"},{"id":"PHD-012","theme":"usagers","q":"Je veux rejoindre une place de stationnement située le long de la bande « BUS » à droite. Puis-je traverser la bande bus ?","choices":["Non, jamais","Oui, et je peux ensuite rouler dessus jusqu'au bout de la rue","Oui, pour accéder à un emplacement de stationnement situé le long de la bande bus"],"answer":2,"explain":"Les véhicules non autorisés peuvent traverser la bande bus pour accéder à une propriété riveraine ou à un emplacement de stationnement situé le long de celle-ci, mais pas y circuler.","photo":"818b86bc-773f-4c10-a769-550117b44c8d","focus":"inscription « BUS » au sol","ref":"Art. 72.5, 3°, d) AR 01/12/1975"},{"id":"PHD-013","theme":"stationnement","q":"Si cette rue résidentielle est à double sens, de quel côté dois-je ranger ma voiture pour stationner ?","choices":["À droite par rapport à mon sens de marche","Du côté où il y a le plus de place","À gauche, pour repartir plus facilement"],"answer":0,"explain":"Tout véhicule à l'arrêt ou en stationnement doit être rangé à droite par rapport à son sens de marche. Ce n'est que dans une rue à sens unique qu'on peut choisir l'un ou l'autre côté.","photo":"40e28737-d157-4747-8ea7-38f906a45446","focus":"bord droit de la chaussée","ref":"Art. 23.1, 1° AR 01/12/1975"},{"id":"PHD-015","theme":"usagers","q":"À droite, un panneau rond bleu montrant un vélo signale le chemin pavé qui longe la route. Puis-je y rouler avec ma voiture pour éviter un bouchon ?","choices":["Oui, à moins de 20 km/h","Oui, si aucun cycliste n'y circule","Non, ce chemin est réservé aux cyclistes : je dois rester sur la chaussée"],"answer":2,"explain":"Le panneau rond bleu à vélo désigne une piste cyclable, qui ne fait pas partie de la chaussée. Les conducteurs de voitures doivent emprunter la chaussée.","photo":"b9bc0951-d4f3-4e68-9978-a7c6665e5093","focus":"panneau rond bleu à droite","ref":"Art. 2.7, 9.1.1 et 69 (D7) AR 01/12/1975"},{"id":"PHD-016","theme":"stationnement","q":"Puis-je m'arrêter un instant sur ce chemin cyclable pour déposer un passager ?","choices":["Non, l'arrêt et le stationnement sont interdits sur les pistes cyclables","Oui, si je reste au volant","Oui, avec les feux de détresse allumés"],"answer":0,"explain":"Il est interdit de mettre un véhicule à l'arrêt ou en stationnement sur une piste cyclable, même pour un court instant.","photo":"b9bc0951-d4f3-4e68-9978-a7c6665e5093","focus":"chemin pavé à droite","ref":"Art. 24, 2° AR 01/12/1975"},{"id":"PHD-017","theme":"signalisation","q":"Que m'indique le panneau rond rouge barré d'une bande blanche horizontale, devant la haie ?","choices":["Stationnement interdit","Sens interdit pour tout conducteur","Fin de toutes les interdictions"],"answer":1,"explain":"Le signal C1 interdit l'accès dans ce sens à tout conducteur. Il faut suivre le sens de circulation du parking (flèche au sol).","photo":"a3960254-b3d4-4f43-9394-1d69acdc1695","focus":"panneau rond rouge à droite","ref":"Art. 68 (C1) AR 01/12/1975"},{"id":"PHD-018","theme":"stationnement","q":"Je veux stationner sur la chaussée près de cet abribus, signalé par un panneau jaune d'arrêt de bus. Quelle distance dois-je respecter ?","choices":["Au moins 15 m de part et d'autre du panneau","Au moins 5 m avant le panneau seulement","Aucune, si aucun bus n'est en vue"],"answer":0,"explain":"Le stationnement est interdit à moins de 15 mètres de part et d'autre d'un panneau indiquant un arrêt d'autobus, de trolleybus ou de tram.","photo":"a1f04928-7174-48c7-88bc-b790c134179e","focus":"panneau jaune au-dessus de l'abribus","ref":"Art. 25.1, 2° AR 01/12/1975"},{"id":"PHD-019","theme":"usagers","q":"J'approche de ce passage pour piétons, sans feux. Si un piéton attend au bord du trottoir, sur le point de traverser, que dois-je faire ?","choices":["Passer : il n'est pas encore engagé sur le passage","Lui céder le passage","Klaxonner pour qu'il attende"],"answer":1,"explain":"Là où la circulation n'est pas réglée par des feux ou un agent, je dois m'approcher du passage à allure modérée et céder le passage aux piétons qui y sont engagés ou sur le point de s'y engager.","grave":true,"photo":"9f282297-4b76-449a-9bb6-b5f37b4e6aaa","focus":"passage pour piétons","ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"PHD-020","theme":"stationnement","q":"Je veux stationner dans la rue de gauche, juste à l'angle de ce carrefour. Quelle distance minimale dois-je laisser (sauf réglementation locale) ?","choices":["5 m du prolongement du bord le plus proche de la chaussée transversale","1 m suffit","Aucune en agglomération"],"answer":0,"explain":"L'arrêt et le stationnement sont interdits aux abords des carrefours, à moins de 5 mètres du prolongement du bord le plus rapproché de la chaussée transversale, sauf réglementation locale.","photo":"a01e597b-c3e4-4dc6-9625-d876adb88958","focus":"angle du carrefour","ref":"Art. 24, 7° AR 01/12/1975"},{"id":"PHD-021","theme":"usagers","q":"Le feu à droite est vert pour moi. Si, au moment de passer, des piétons se sont engagés régulièrement sur la chaussée que je vais traverser, que dois-je faire ?","choices":["Les laisser achever leur traversée","Passer, car mon feu est vert","Passer en klaxonnant"],"answer":0,"explain":"Même si la circulation est ouverte dans mon sens, je dois permettre aux piétons engagés régulièrement sur la chaussée d'achever leur traversée à allure normale.","grave":true,"photo":"01ac2565-7580-4a47-89c3-9afe5295af91","focus":"feu vert à droite","ref":"Art. 40.4.1 AR 01/12/1975"},{"id":"PHE-001","theme":"vitesse","q":"Je viens de passer le panneau visible à droite (cercle rouge « 30 » sur fond blanc, avec l'inscription « ZONE »). À quelle vitesse maximale puis-je rouler ?","choices":["50 km/h","30 km/h","30 km/h, mais uniquement aux heures d'école"],"answer":1,"explain":"Ce signal F4a marque le début d'une zone 30 : la vitesse y est limitée à 30 km/h sur toutes les voies de la zone, en permanence, jusqu'au signal F4b qui en marque la fin.","photo":"402fb3de-7d09-42e2-87c7-2b7115c07e6b","focus":"panneau carré à droite, sous les fleurs","ref":"Art. 22quater et 71 (F4a) AR 01/12/1975"},{"id":"PHE-002","theme":"signalisation","q":"Ce panneau « ZONE 30 » (F4a) est placé à droite. Jusqu'où la limitation de vitesse s'applique-t-elle ?","choices":["Jusqu'au prochain carrefour seulement","Sur 100 mètres","Jusqu'au signal qui indique la fin de la zone 30 (F4b)"],"answer":2,"explain":"Un signal zonal vaut pour toutes les voies publiques de la zone, carrefours compris, jusqu'au signal F4b qui marque la fin de la zone.","photo":"402fb3de-7d09-42e2-87c7-2b7115c07e6b","focus":"panneau carré à droite","ref":"Art. 22quater AR 01/12/1975"},{"id":"PHE-004","theme":"stationnement","q":"Un signal E1 (stationnement interdit) est placé à droite. Sauf indication contraire sur un panneau additionnel, où l'interdiction s'applique-t-elle ?","choices":["Des deux côtés de la rue, sur 50 mètres","Du côté où le signal est placé, à partir du signal jusqu'au prochain carrefour","Dans toute l'agglomération"],"answer":1,"explain":"Les signaux E1, E3 et E9 s'appliquent du côté de la voie publique où ils sont placés, à partir du signal et jusqu'au prochain carrefour, sauf si un panneau additionnel indique une autre distance ou la fin de la réglementation.","photo":"4d22f628-e3e3-46b5-9be5-ac86de257e77","focus":"panneau rond à droite sur le trottoir","ref":"Art. 70.2.2 AR 01/12/1975"},{"id":"PHE-005","theme":"depassement","q":"Sur ce pont, une ligne blanche continue sépare ma voie de celle des véhicules qui viennent en sens inverse. Puis-je la franchir pour dépasser un véhicule lent ?","choices":["Oui, si personne n'arrive en face","Oui, si le véhicule lent roule à moins de 30 km/h","Non, il est interdit de franchir une ligne continue"],"answer":2,"explain":"Une ligne blanche continue ne peut être franchie par aucun conducteur ; quand elle sépare les deux sens de circulation, il est aussi interdit de circuler à sa gauche.","grave":true,"photo":"87ee6577-34cc-4d82-99d9-48ddcd107389","focus":"ligne continue à gauche de ma voie","ref":"Art. 72.2 AR 01/12/1975"},{"id":"PHE-006","theme":"priorite","q":"J'arrive à l'entrée de ce carrefour giratoire, signalé par le panneau bleu D5 (flèches en cercle) et par le triangle B1 placé dessous. Qui a la priorité ?","choices":["Les conducteurs qui circulent déjà sur l'anneau","Moi, car je viens de droite par rapport à eux","Le plus rapide des deux"],"answer":0,"explain":"Avec les signaux D5 et B1, c'est un rond-point au sens légal. Je dois céder le passage aux conducteurs qui circulent sur l'anneau : la priorité de droite ne joue pas en faveur de celui qui entre.","grave":true,"photo":"75223b02-bf2c-49bb-afb5-07376a9cc71d","focus":"panneaux à droite (D5 et B1) et triangles au sol","ref":"Art. 2.39 et 12.3.1 AR 01/12/1975"},{"id":"PHE-007","theme":"signalisation","q":"J'entre dans ce rond-point (signaux D5 et B1). Quand dois-je mettre mon clignotant ?","choices":["En entrant, à gauche si je vais à gauche","Pas en entrant ; en sortant, je dois mettre mon clignotant à droite","Jamais dans un rond-point"],"answer":1,"explain":"Entrer dans un rond-point est un changement de direction qui n'exige pas le clignotant. En revanche, il faut mettre le clignotant pour en sortir.","photo":"75223b02-bf2c-49bb-afb5-07376a9cc71d","focus":"panneau D5 à droite","ref":"Art. 19.2 AR 01/12/1975"},{"id":"PHE-008","theme":"signalisation","q":"Les feux tricolores devant moi sont au rouge. Où dois-je m'arrêter ?","choices":["Au milieu du carrefour, pour être prêt à repartir","Je peux passer lentement si personne ne vient","Avant la ligne d'arrêt ou, s'il n'y en a pas, avant le feu"],"answer":2,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt ou, s'il n'y a pas de ligne d'arrêt, le signal lui-même.","grave":true,"photo":"3feb490c-a4a9-46ff-8c69-8f6fb8948f14","focus":"feux tricolores à gauche et à droite","ref":"Art. 61.1, 1° AR 01/12/1975"},{"id":"PHE-009","theme":"usagers","q":"À ce carrefour réglé par des feux, si le feu passe au vert alors qu'un piéton est encore en train de traverser régulièrement la chaussée devant moi, que dois-je faire ?","choices":["Le laisser terminer sa traversée à allure normale","Klaxonner pour qu'il se dépêche","Démarrer : le feu vert me donne la priorité"],"answer":0,"explain":"Aux endroits réglés par des feux, même quand la circulation est ouverte dans mon sens, je dois permettre aux piétons engagés régulièrement sur la chaussée d'achever leur traversée à allure normale.","grave":true,"photo":"3feb490c-a4a9-46ff-8c69-8f6fb8948f14","focus":"feux et chaussée devant moi","ref":"Art. 40.4.1 AR 01/12/1975"},{"id":"PHE-011","theme":"usagers","q":"J'approche de ce passage pour piétons, qui n'est réglé ni par des feux ni par un agent. Comment dois-je l'aborder ?","choices":["À allure modérée, prêt à céder le passage aux piétons qui y sont engagés ou sur le point de s'y engager","À la vitesse maximale autorisée s'il n'y a personne dessus","En klaxonnant pour prévenir les piétons"],"answer":0,"explain":"À un passage pour piétons non réglé, le conducteur ne peut s'approcher qu'à allure modérée et doit céder le passage aux piétons qui y sont engagés ou sont sur le point de s'y engager.","photo":"e0f88732-e4b4-47a9-99cf-409fd4f6e137","focus":"passage pour piétons devant moi","ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"PHE-012","theme":"usagers","q":"Je veux continuer tout droit dans la rue en face. Un piéton avec un chien est engagé sur le passage pour piétons (sans feux) qui traverse cette rue, à gauche. Que dois-je faire ?","choices":["Passer derrière lui sans ralentir","Klaxonner et passer","Lui céder le passage et m'arrêter si nécessaire"],"answer":2,"explain":"Le conducteur doit céder le passage aux piétons engagés sur un passage pour piétons non réglé, ou sur le point de s'y engager, et donc s'arrêter si nécessaire.","grave":true,"photo":"e138bb0d-d029-4f58-acdd-90ed4fa41071","focus":"piéton sur le passage, à gauche","ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"PHE-013","theme":"stationnement","q":"Je cherche une place dans cette rue. Puis-je stationner sur la chaussée à 3 mètres avant le passage pour piétons visible devant moi ?","choices":["Oui, si je ne touche pas les bandes blanches","Oui, pour moins de 15 minutes","Non, c'est interdit sur le passage et à moins de 5 mètres avant celui-ci"],"answer":2,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 mètres avant ceux-ci, pour que les piétons restent bien visibles.","photo":"d9933225-9c3c-4d10-9ede-9c5abcb05fc3","focus":"passage pour piétons devant moi","ref":"Art. 24, 4° AR 01/12/1975"},{"id":"PHE-014","theme":"stationnement","q":"Ce poteau signale un arrêt d'autobus le long de la chaussée. Puis-je stationner ma voiture sur la chaussée à 10 mètres de ce poteau ?","choices":["Oui, si aucun bus n'est en vue","Oui, mais uniquement le dimanche","Non, c'est interdit à moins de 15 mètres de part et d'autre du panneau d'arrêt"],"answer":2,"explain":"Le stationnement est interdit à moins de 15 mètres de part et d'autre d'un panneau qui indique un arrêt d'autobus, de trolleybus ou de tram.","photo":"7d034afd-a718-4c62-8f90-07dee480cf98","focus":"poteau d'arrêt de bus au premier plan","ref":"Art. 25.1, 2° AR 01/12/1975"},{"id":"PHE-015","theme":"priorite","q":"Je roule sur cette chaussée où passent des rails de tram. Si un tram arrive derrière moi sur ces rails, que dois-je faire ?","choices":["Lui céder le passage et m'écarter de la voie ferrée dès que possible","Rester sur les rails : il doit attendre derrière moi","Accélérer pour garder mon avance"],"answer":0,"explain":"Tout usager doit céder le passage aux véhicules sur rails et, pour cela, s'écarter de la voie ferrée dès que possible.","grave":true,"photo":"3f20b50b-89a9-4a48-851e-34547e8977a4","focus":"rails de tram au premier plan","ref":"Art. 12.1 AR 01/12/1975"},{"id":"PHE-016","theme":"vitesse","q":"Je roule dans cette rue d'une commune de la Région de Bruxelles-Capitale, en agglomération. Aucun panneau de vitesse n'est visible. Quelle est la vitesse maximale autorisée ?","choices":["30 km/h","50 km/h","20 km/h"],"answer":0,"explain":"En Région de Bruxelles-Capitale, la vitesse est limitée à 30 km/h dans les agglomérations, sauf si un signal C43 impose ou permet une autre limite.","photo":"e8e4fe64-b2d1-440a-ad45-07c2c6165f03","focus":"rue bordée de voitures en stationnement","ref":"Art. 11.1 (Région de Bruxelles-Capitale) AR 01/12/1975"},{"id":"PHE-017","theme":"usagers","q":"Une personne marche sur la chaussée devant moi, dans cette rue en agglomération. Quelle distance latérale minimale dois-je laisser pour la dépasser ?","choices":["50 centimètres","1 mètre ; sinon je ne peux passer qu'à l'allure du pas","2 mètres"],"answer":1,"explain":"Je dois laisser au moins 1 mètre entre mon véhicule et un piéton qui circule sur la chaussée en agglomération (1,5 mètre hors agglomération). Si c'est impossible, je ne peux passer qu'à l'allure du pas, et je m'arrête si nécessaire.","photo":"e8e4fe64-b2d1-440a-ad45-07c2c6165f03","focus":"personne qui marche au milieu de la rue","ref":"Art. 40.7 AR 01/12/1975"},{"id":"PHE-018","theme":"signalisation","q":"Le panneau rond bleu à droite montre une flèche blanche qui tourne vers la droite (signal D1). Que m'impose-t-il, sauf exception indiquée sur un panneau additionnel ?","choices":["Il interdit de tourner à droite","Il indique une simple recommandation de direction","Il m'oblige à suivre la direction de la flèche, donc à tourner à droite"],"answer":2,"explain":"Le signal D1 est un signal d'obligation : il impose de suivre la direction indiquée par la flèche. Un panneau additionnel peut prévoir des exceptions pour certains usagers.","photo":"5ba803ca-3901-4b30-ad57-1a2ba8ee7804","focus":"panneau bleu rond à droite, avant le passage pour piétons","ref":"Art. 69.3 (D1) AR 01/12/1975"},{"id":"PHE-019","theme":"usagers","q":"Devant moi, une partie de la voie publique est délimitée par deux lignes blanches discontinues parallèles, avec un symbole de vélo. Que constitue-t-elle ?","choices":["Une bande de circulation ordinaire, que je peux emprunter en voiture","Une piste cyclable : elle ne fait pas partie de la chaussée et je ne peux pas y circuler en voiture","Une zone de stationnement"],"answer":1,"explain":"La partie de la voie publique délimitée par deux lignes blanches discontinues parallèles, trop étroite pour les véhicules automobiles, constitue une piste cyclable. Elle ne fait pas partie de la chaussée : avec ma voiture, je dois circuler sur la chaussée.","photo":"66c0d31e-7d35-4764-a98c-adb22e292085","focus":"bande entre les deux lignes discontinues, symbole vélo","ref":"Art. 74, 2.7 et 9.1.1 AR 01/12/1975"},{"id":"PHE-020","theme":"stationnement","q":"Puis-je arrêter brièvement ma voiture sur cette piste cyclable (deux lignes discontinues et symbole vélo) pour décharger un colis ?","choices":["Oui, pendant moins de 2 minutes","Oui, avec les feux de détresse","Non, l'arrêt et le stationnement sont interdits sur les pistes cyclables"],"answer":2,"explain":"Il est interdit de mettre un véhicule à l'arrêt ou en stationnement sur une piste cyclable, même brièvement.","photo":"66c0d31e-7d35-4764-a98c-adb22e292085","focus":"piste cyclable marquée devant moi","ref":"Art. 24, 2° AR 01/12/1975"},{"id":"PHE-021","theme":"signalisation","q":"À droite, une zone est marquée au sol par des lignes blanches obliques parallèles. Puis-je rouler ou m'arrêter sur cette zone ?","choices":["Oui, pour m'arrêter brièvement","Non, il est interdit d'y circuler, de s'y arrêter et d'y stationner","Oui, mais seulement pour dépasser"],"answer":1,"explain":"Les lignes obliques parallèles marquent des îlots directionnels ou des zones d'évitement : on ne peut ni y circuler, ni s'y arrêter, ni y stationner.","photo":"98a2a9d1-1cf4-4adb-b845-ce271771bed6","focus":"zone hachurée au sol, à droite","ref":"Art. 77.4 AR 01/12/1975"},{"id":"PHE-022","theme":"stationnement","q":"À droite, les voitures sont rangées au-delà d'une large ligne blanche continue. Que signifie cette large ligne ?","choices":["Elle marque le bord fictif de la chaussée : au-delà, la zone est réservée à l'arrêt et au stationnement","Elle délimite une bande bus","Elle interdit tout arrêt de ce côté"],"answer":0,"explain":"Une large ligne blanche continue tracée sur la chaussée marque son bord fictif. La partie située au-delà est réservée à l'arrêt et au stationnement, sauf sur autoroute et sur route pour automobiles.","photo":"a14f70bb-1879-42f0-a2bc-d34ff76bb5d6","focus":"large ligne continue le long des voitures garées, à droite","ref":"Art. 75.2 AR 01/12/1975"},{"id":"PHF-001","theme":"priorite","q":"J'arrive à ce carrefour. À droite se trouve un panneau triangulaire pointe en bas et une ligne de triangles blancs est tracée devant moi. Que dois-je faire ?","choices":["Je dois toujours marquer l'arrêt complet à la ligne de triangles","Je dois céder le passage aux usagers de la voie que j'aborde et ne m'arrêter que si c'est nécessaire","Je peux passer sans ralentir : la priorité de droite s'applique"],"answer":1,"explain":"Le signal B1 oblige à céder le passage à tous les conducteurs circulant sur la voie abordée. La ligne de triangles indique l'endroit où s'arrêter, s'il y a lieu : l'arrêt n'est obligatoire que si un usager doit passer (contrairement au STOP).","grave":true,"photo":"e9fd00f6-66e9-45db-9293-9e4f29a44e40","focus":"panneau triangulaire à droite et ligne de triangles au sol","ref":"Art. 12.3.1 a) et 76.2 AR 01/12/1975"},{"id":"PHF-002","theme":"signalisation","q":"Que signifie le panneau carré bleu avec une flèche blanche vers le haut, à droite de la rue ?","choices":["Obligation de continuer tout droit au prochain carrefour","Voie publique à sens unique","Route prioritaire"],"answer":1,"explain":"Le signal F19 (carré bleu, flèche blanche) est un signal d'indication : il annonce une voie publique à sens unique. À ne pas confondre avec le D1, rond bleu, qui impose une direction.","photo":"c8beacdd-824b-440a-bb26-82f1800e324b","focus":"panneau carré bleu à droite","ref":"Art. 71 (F19) AR 01/12/1975"},{"id":"PHF-003","theme":"stationnement","q":"D'après le panneau carré bleu à flèche blanche (F19) à droite, la rue où je m'engage est à sens unique. Sauf signalisation contraire, puis-je y stationner du côté gauche de la chaussée ?","choices":["Oui, sur une chaussée à sens unique on peut se ranger de l'un ou de l'autre côté","Non, on doit toujours stationner à droite","Seulement la nuit"],"answer":0,"explain":"En règle générale, un véhicule à l'arrêt ou en stationnement est rangé à droite ; mais si la chaussée est à sens unique, il peut être rangé de l'un ou de l'autre côté (sauf signalisation contraire).","photo":"c8beacdd-824b-440a-bb26-82f1800e324b","focus":"panneau de sens unique à droite","ref":"Art. 23.1, 1° AR 01/12/1975"},{"id":"PHF-004","theme":"stationnement","q":"Puis-je stationner ma voiture sur la chaussée, 3 mètres avant le passage pour piétons devant moi ?","choices":["Oui, si je ne mords pas sur les bandes blanches","Non, le stationnement est interdit à moins de 5 mètres en deçà du passage","Oui, si je laisse mes feux de détresse allumés"],"answer":1,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 mètres en deçà de ces passages, pour garder la visibilité entre conducteurs et piétons.","photo":"ecc5e0f7-30b9-4954-8bc4-a62aa88c66b0","focus":"passage pour piétons devant moi","ref":"Art. 24, 4° AR 01/12/1975"},{"id":"PHF-005","theme":"usagers","q":"Aucun feu ne règle la circulation à ce passage pour piétons. Si un piéton attend au bord du trottoir et est sur le point de traverser, que dois-je faire ?","choices":["Klaxonner pour lui signaler mon passage","Continuer : il doit attendre que la chaussée soit libre","M'approcher à allure modérée et lui céder le passage"],"answer":2,"explain":"Là où la circulation n'est réglée ni par un agent ni par des feux, le conducteur ne peut s'approcher d'un passage pour piétons qu'à allure modérée et doit céder le passage aux piétons qui y sont engagés ou sur le point de s'y engager.","grave":true,"photo":"ecc5e0f7-30b9-4954-8bc4-a62aa88c66b0","focus":"passage pour piétons devant moi","ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"PHF-006","theme":"signalisation","q":"Le feu est vert. S'il passe à l'orange fixe alors que je suis encore assez loin de la ligne d'arrêt pour m'arrêter sans danger, que dois-je faire ?","choices":["M'arrêter avant la ligne d'arrêt","Accélérer pour passer avant le rouge","Continuer : l'orange autorise encore le passage"],"answer":0,"explain":"Le feu jaune-orange fixe interdit de franchir la ligne d'arrêt, sauf si le conducteur en est si près au moment où il s'allume qu'il ne peut plus s'arrêter dans des conditions de sécurité suffisantes.","photo":"4f01e913-3a15-47b0-8771-6988111c8deb","focus":"feux verts au-dessus de la chaussée et à droite","ref":"Art. 61.1.2° AR 01/12/1975"},{"id":"PHF-007","theme":"usagers","q":"Le feu est vert pour moi. Si un piéton s'est régulièrement engagé sur le passage pour piétons devant moi, que dois-je faire ?","choices":["Passer, puisque le feu est vert pour moi","Lui permettre d'achever sa traversée","Klaxonner pour qu'il se dépêche"],"answer":1,"explain":"Même si la circulation est ouverte dans son sens par un feu vert, le conducteur doit permettre aux piétons régulièrement engagés sur la chaussée d'achever leur traversée à allure normale.","grave":true,"photo":"4f01e913-3a15-47b0-8771-6988111c8deb","focus":"passage pour piétons devant moi","ref":"Art. 40.4.1 AR 01/12/1975"},{"id":"PHF-008","theme":"priorite","q":"Le feu face à moi est rouge et un panneau « cédez le passage » (B1) est fixé sous ce feu. Que dois-je faire ?","choices":["M'arrêter : tant que les feux fonctionnent, ils priment sur le panneau B1","Céder le passage puis passer si la voie est libre, malgré le rouge","Le B1 annule le feu rouge, je peux passer"],"answer":0,"explain":"Le fonctionnement des feux rend sans effet les signaux de priorité placés sur la même voie. Le feu rouge interdit de franchir la ligne d'arrêt ou le signal. Le B1 ne s'applique que si les feux sont éteints ou à l'orange clignotant.","grave":true,"photo":"6fac39b6-d031-410a-b933-78f5850f5682","focus":"feu et panneau triangulaire sous le feu","ref":"Art. 6.3 et 61.1.1° AR 01/12/1975"},{"id":"PHF-009","theme":"depassement","q":"Aucun feu ne règle ce passage pour piétons. La voiture qui me précède ralentit et s'arrête juste devant le passage. Puis-je la dépasser par la gauche ?","choices":["Oui, si personne ne vient en face","Oui, à allure réduite","Non, ce dépassement est interdit"],"answer":2,"explain":"Il est interdit de dépasser par la gauche un véhicule qui s'approche d'un passage pour piétons ou s'arrête devant celui-ci, là où la circulation n'est pas réglée par un agent ou des feux : un piéton masqué par ce véhicule pourrait être en train de traverser.","grave":true,"photo":"796e17fb-aa81-4c55-abfe-3dc7e8563f60","focus":"passage pour piétons au premier plan","ref":"Art. 17.2, 5° AR 01/12/1975"},{"id":"PHF-010","theme":"vitesse","q":"Je circule dans cette rue résidentielle de la Région de Bruxelles-Capitale, en agglomération, sans autre signal. Quelle est la vitesse maximale autorisée ?","choices":["30 km/h","50 km/h","70 km/h"],"answer":0,"explain":"Dans la Région de Bruxelles-Capitale, la vitesse est limitée à 30 km/h dans les agglomérations, sauf si un signal C43 impose ou permet une autre limite.","photo":"3204e8ff-39e0-47ad-bfea-090f8287b85e","focus":"rue bordée de voitures en stationnement","ref":"Art. 11.1 (Région de Bruxelles-Capitale) AR 01/12/1975"},{"id":"PHF-011","theme":"stationnement","q":"La bordure du trottoir à droite est marquée de traits jaunes discontinus. Puis-je stationner le long de cette bordure ?","choices":["Oui, si j'utilise mon disque de stationnement","Non, le stationnement y est interdit","Oui, mais seulement pendant 15 minutes"],"answer":1,"explain":"Une ligne discontinue jaune tracée sur la bordure du trottoir ou le bord de la chaussée signifie que le stationnement est interdit sur la chaussée le long de cette ligne.","photo":"8debed6f-c572-41a0-97d3-3a70c9b8f571","focus":"traits jaunes sur la bordure à droite","ref":"Art. 75.1.2° AR 01/12/1975"},{"id":"PHF-012","theme":"priorite","q":"J'arrive à ce carrefour signalé par un panneau B1 (triangle pointe en bas) au-dessus d'un panneau D5 (sens giratoire). Qui a la priorité ?","choices":["Les conducteurs qui circulent déjà sur l'anneau du rond-point","Moi, car les conducteurs sur l'anneau viennent de ma gauche","Celui qui vient de droite, comme à un carrefour ordinaire"],"answer":0,"explain":"Un carrefour à sens giratoire signalé par D5 et dont l'accès porte un B1 est un rond-point au sens légal. Je débouche d'une voie pourvue d'un B1 : je dois céder le passage aux conducteurs circulant sur l'anneau.","grave":true,"photo":"9a5785e3-6efe-4908-aebf-14cf0bfada64","focus":"panneaux B1 et D5 sur le poteau à droite","ref":"Art. 2.39 et 12.3.1 a) AR 01/12/1975"},{"id":"PHF-013","theme":"signalisation","q":"Dans ce rond-point, quand dois-je utiliser mon indicateur de direction ?","choices":["En entrant dans le rond-point","En sortant du rond-point","Jamais dans un rond-point"],"answer":1,"explain":"Entrer dans un rond-point est un changement de direction qui n'implique pas l'usage des indicateurs de direction ; en sortir est un changement de direction qui l'implique : on met le clignoteur à droite pour sortir.","photo":"9a5785e3-6efe-4908-aebf-14cf0bfada64","focus":"panneau D5 à droite","ref":"Art. 19.2.1° AR 01/12/1975"},{"id":"PHF-014","theme":"signalisation","q":"Que signifie le panneau rond rouge à barre horizontale blanche, à droite ?","choices":["Accès interdit dans les deux sens à tout conducteur","Sens interdit pour tout conducteur : je ne peux pas m'engager dans la voie où ce panneau est placé","Arrêt et stationnement interdits"],"answer":1,"explain":"Le signal C1 indique un sens interdit pour tout conducteur. S'y engager reviendrait à circuler à contresens. Le C3 (rond blanc à bord rouge) interdit l'accès dans les deux sens.","grave":true,"photo":"0a6617e1-c705-4da7-9628-8d3da34635e1","focus":"panneau rond rouge à droite","ref":"Art. 68.3 (C1) AR 01/12/1975"},{"id":"PHF-015","theme":"stationnement","q":"Que signifie le panneau carré bleu avec un « P » blanc, à droite ?","choices":["Stationnement interdit","Parking réservé aux véhicules de police","Stationnement autorisé (sous réserve des indications d'un éventuel panneau additionnel)"],"answer":2,"explain":"Le signal E9a indique que le stationnement est autorisé. Un panneau additionnel peut en préciser les modalités (disque, payant, catégories de véhicules, etc.).","photo":"5352e4d3-16d1-4897-a15a-5a753e67b548","focus":"panneau bleu « P » à droite","ref":"Art. 70.2.1, 3° (E9a) AR 01/12/1975"},{"id":"PHF-016","theme":"signalisation","q":"À gauche, devant l'îlot, une zone est marquée au sol par des lignes blanches obliques parallèles. Puis-je rouler ou m'arrêter sur cette zone ?","choices":["Non, il est interdit d'y circuler, de s'y arrêter et d'y stationner","Oui, pour dépasser un cycliste","Oui, pour m'y arrêter brièvement"],"answer":0,"explain":"Les lignes parallèles obliques blanches marquent des îlots directionnels ou des zones d'évitement : les conducteurs ne peuvent ni y circuler, ni s'y arrêter, ni y stationner.","photo":"097c3226-4991-473c-aa4c-aa5996a2458e","focus":"zone hachurée à gauche, devant l'îlot","ref":"Art. 77.4 AR 01/12/1975"},{"id":"PHF-017","theme":"autoroute","q":"Sur cette autoroute en Wallonie, sans signal de vitesse particulier, quelle est la vitesse maximale autorisée pour le camion semi-remorque à droite (masse maximale autorisée supérieure à 3,5 t) ?","choices":["120 km/h","90 km/h","70 km/h"],"answer":1,"explain":"Sur autoroute, la vitesse est limitée à 120 km/h, mais à 90 km/h pour les véhicules dont la masse maximale autorisée dépasse 3,5 tonnes et pour les autobus.","photo":"5056cddc-9cac-4940-9347-2a62acdc56bc","focus":"camion sur la bande de droite","ref":"Art. 11.2, 1° a) (Région wallonne) AR 01/12/1975"},{"id":"PHF-018","theme":"autoroute","q":"Je circule sur cette autoroute, sans signal de vitesse particulier. Sauf si les conditions m'obligent à ralentir, quelle vitesse minimale dois-je respecter ?","choices":["Il n'y a pas de vitesse minimale","50 km/h","70 km/h"],"answer":2,"explain":"Sauf limitation inférieure imposée par un signal C43, aucun conducteur ne peut circuler sur autoroute à moins de 70 km/h ; il doit toutefois adapter sa vitesse aux circonstances (article 10.1).","photo":"5368ceb3-4966-4074-98f2-c0f1fd3daa1f","focus":"autoroute","ref":"Art. 21.2 AR 01/12/1975"},{"id":"PHF-019","theme":"signalisation","q":"Le panneau rond au-dessus du tunnel indique « 3 m 10 ». Mon véhicule, chargement compris, mesure 3,30 m de haut. Puis-je passer ?","choices":["Oui, si je roule très lentement","Non, l'accès est interdit aux véhicules plus hauts que 3,10 m","Oui, la limite ne concerne que les camions"],"answer":1,"explain":"Le signal C29 interdit l'accès aux conducteurs de véhicules dont la hauteur, chargement compris, dépasse celle indiquée : ici 3,10 m.","photo":"962e5e2c-d795-491d-b503-3243ac45cb08","focus":"panneau rond au-dessus de l'arche","ref":"Art. 68.3 (C29) AR 01/12/1975"},{"id":"PHF-020","theme":"stationnement","q":"Sauf réglementation locale, puis-je m'arrêter sur la chaussée sous ce pont (passage inférieur) pour déposer un passager ?","choices":["Non, l'arrêt et le stationnement y sont interdits","Oui, l'arrêt est toujours permis","Oui, si j'allume mes feux de détresse"],"answer":0,"explain":"L'arrêt et le stationnement sont interdits sur la chaussée dans les passages inférieurs, dans les tunnels et, sauf réglementation locale, sous les ponts.","photo":"962e5e2c-d795-491d-b503-3243ac45cb08","focus":"passage sous le pont","ref":"Art. 24, 5° AR 01/12/1975"},{"id":"PHF-021","theme":"autoroute","q":"Sur cette autoroute, les lignes tracées au sol sont de couleur jaune-orange (marquage provisoire de chantier). Si d'anciennes lignes blanches restaient visibles au même endroit, lesquelles devrais-je suivre ?","choices":["Les lignes blanches, qui restent prioritaires","Les lignes orange, qui rendent les lignes blanches sans effet","Je choisis librement"],"answer":1,"explain":"Les marques provisoires de couleur orange, utilisées à l'occasion de travaux, ont la même signification que les lignes blanches et rendent sans effet les autres marques blanches tracées au même endroit.","photo":"5f865595-bb6f-4dd9-b712-c47b3c8aa056","focus":"lignes orange au sol","ref":"Art. 73.1 et 73.4 AR 01/12/1975"},{"id":"PHF-022","theme":"autoroute","q":"Sur cette autoroute, je voudrais faire une pause pour téléphoner. Puis-je m'arrêter sur la bande située à droite de la ligne blanche continue ?","choices":["Oui, si j'allume mes feux de détresse","Oui, pour une durée de moins de 5 minutes","Non, l'arrêt est interdit sur autoroute sauf sur les aires de stationnement signalées (E9a)"],"answer":2,"explain":"Il est interdit sur les autoroutes de mettre un véhicule à l'arrêt ou en stationnement, sauf sur les aires de stationnement indiquées par le signal E9a. La bande de droite ne sert qu'en cas de panne ou de nécessité.","photo":"7f64d6a7-7ee9-469b-b958-70137f8e8819","focus":"bande à droite de la ligne continue","ref":"Art. 21.4, 4° AR 01/12/1975"},{"id":"PHF-023","theme":"securite","q":"Je tombe en panne sur cette autoroute et ne peux pas quitter l'endroit où l'arrêt est interdit. À quelle distance minimale dois-je placer le triangle de danger derrière mon véhicule ?","choices":["30 mètres","50 mètres","100 mètres"],"answer":2,"explain":"Le triangle de danger est placé en deçà du véhicule à au moins 30 m sur les voies ordinaires et à au moins 100 m sur les autoroutes, visible à environ 50 m. Sur autoroute, je dois aussi porter une veste de sécurité rétroréfléchissante dès que je sors du véhicule.","photo":"7f64d6a7-7ee9-469b-b958-70137f8e8819","focus":"autoroute","ref":"Art. 51.2 et 51.4 AR 01/12/1975"},{"id":"PHG-001","theme":"vitesse","q":"Je roule en voiture sur cette autoroute en Wallonie. Aucun panneau de limitation n'est visible. Quelle est ma vitesse maximale ?","choices":["90 km/h","120 km/h","130 km/h"],"answer":1,"explain":"Sur autoroute, en dehors des agglomérations, la vitesse est limitée à 120 km/h pour les voitures, sauf signal C43 imposant une limite inférieure. 130 km/h n'existe pas en Belgique.","photo":"b84ee535-4965-4cc3-98ce-aee314bf2fac","focus":"route et absence de panneau","ref":"Art. 11.2 1° a) (Région wallonne) AR 01/12/1975"},{"id":"PHG-002","theme":"autoroute","q":"Je veux consulter mon GPS. Puis-je m'arrêter quelques instants au bord de cette autoroute ?","choices":["Oui, si j'allume mes feux de détresse","Oui, à condition de ne pas dépasser 5 minutes","Non, l'arrêt n'est permis que sur les aires de stationnement signalées (E9a)"],"answer":2,"explain":"Sur autoroute, l'arrêt et le stationnement sont interdits, sauf sur les aires de stationnement indiquées par le signal E9a (hors cas de panne ou d'urgence).","photo":"b84ee535-4965-4cc3-98ce-aee314bf2fac","focus":"bord droit de l'autoroute","ref":"Art. 21.4.4° AR 01/12/1975"},{"id":"PHG-003","theme":"autoroute","q":"Cette autoroute compte trois bandes dans mon sens. Le camion de plus de 3,5 tonnes à ma droite peut-il utiliser la bande de gauche pour dépasser ?","choices":["Non, il ne peut utiliser que les deux bandes de droite","Oui, s'il roule plus vite que les autres","Oui, mais seulement la nuit"],"answer":0,"explain":"Sur une autoroute à trois bandes ou plus dans le sens suivi, les véhicules de plus de 3,5 t, autobus et autocars ne peuvent emprunter que l'une des deux bandes situées du côté droit (sauf signaux F13/F15).","photo":"d7eeda3e-3055-4b81-8b30-ced86983ec44","focus":"camion à droite, trois bandes","ref":"Art. 21.3 AR 01/12/1975"},{"id":"PHG-004","theme":"autoroute","q":"Si un embouteillage se forme sur cette autoroute à trois bandes et que je roule sur la bande du milieu, où dois-je me placer ?","choices":["Rester au centre de ma bande","Serrer à gauche","Serrer à droite"],"answer":2,"explain":"Pour former le couloir de secours sur une chaussée de plus de deux bandes, ceux de la bande de gauche serrent à gauche et tous les autres serrent à droite : le couloir se crée à côté de la bande de gauche.","photo":"ecab2e56-c29a-42a4-b680-2abb68274e72","focus":"marquage des trois bandes","ref":"Art. 9.8.2° AR 01/12/1975"},{"id":"PHG-005","theme":"vitesse","q":"Sur cette autoroute en Wallonie, sans panneau de limitation, à quelle vitesse maximale le camion de plus de 3,5 tonnes à ma droite peut-il rouler ?","choices":["90 km/h","120 km/h","100 km/h"],"answer":0,"explain":"Sur autoroute, la vitesse des véhicules dont la masse maximale autorisée dépasse 3,5 t est limitée à 90 km/h (contre 120 km/h pour une voiture).","photo":"d7eeda3e-3055-4b81-8b30-ced86983ec44","focus":"camion à droite","ref":"Art. 11.2 (Région wallonne) AR 01/12/1975"},{"id":"PHG-006","theme":"autoroute","q":"La circulation est fluide et aucun panneau n'impose de limite inférieure. Puis-je rouler à 60 km/h sur cette autoroute ?","choices":["Oui, si je reste sur la bande de droite","Non, la vitesse minimale est de 70 km/h","Oui, la vitesse minimale n'existe pas"],"answer":1,"explain":"Sauf limitation inférieure imposée par un signal C43, aucun conducteur ne peut circuler sur autoroute à moins de 70 km/h ; il doit toutefois adapter sa vitesse aux circonstances.","photo":"ecab2e56-c29a-42a4-b680-2abb68274e72","focus":"autoroute","ref":"Art. 21.2 AR 01/12/1975"},{"id":"PHG-007","theme":"depassement","q":"Si le véhicule qui me précède ralentit pour s'arrêter devant ce passage pour piétons (sans feux), puis-je le dépasser par la gauche ?","choices":["Oui, si aucun piéton n'est visible","Non, c'est interdit","Oui, à allure modérée"],"answer":1,"explain":"Il est interdit de dépasser par la gauche un conducteur qui s'approche ou s'arrête devant un passage pour piétons non réglé par un agent ou des feux : il peut masquer un piéton en train de traverser.","grave":true,"photo":"8f32b4c6-c94c-41e3-bb27-e6565603e787","focus":"passage pour piétons devant","ref":"Art. 17.2.5° AR 01/12/1975"},{"id":"PHG-008","theme":"depassement","q":"Une double ligne blanche continue sépare les deux sens de circulation. Puis-je la franchir pour dépasser un véhicule lent ?","choices":["Oui, si la voie d'en face est libre","Non, jamais","Oui, si le véhicule roule à moins de 30 km/h"],"answer":1,"explain":"Une ligne continue ne peut être franchie par aucun conducteur ; il est aussi interdit de circuler à gauche d'une ligne continue qui sépare les deux sens.","grave":true,"photo":"3bb3ea11-a9f0-4da1-9cee-9411a154ae65","focus":"double ligne continue à gauche","ref":"Art. 72.2 AR 01/12/1975"},{"id":"PHG-009","theme":"stationnement","q":"Puis-je m'arrêter un instant juste avant ce passage pour piétons pour déposer un passager ?","choices":["Oui, l'arrêt est permis partout","Non, ni sur le passage ni à moins de 5 m avant","Oui, si je reste au volant"],"answer":1,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 m en deçà de ceux-ci, pour garder la visibilité sur les piétons.","photo":"90079ca1-9ebb-4a93-a07e-112050eff2ff","focus":"passage pour piétons au premier plan","ref":"Art. 24.4° AR 01/12/1975"},{"id":"PHG-010","theme":"usagers","q":"Ce passage pour piétons n'est réglé ni par des feux ni par un agent. Si un piéton est sur le point de s'y engager, que dois-je faire ?","choices":["Lui céder le passage","Passer si j'arrive avant lui","Klaxonner pour l'avertir"],"answer":0,"explain":"À un passage pour piétons non réglé, je dois m'approcher à allure modérée et céder le passage aux piétons qui y sont engagés ou sont sur le point de s'y engager.","grave":true,"photo":"90079ca1-9ebb-4a93-a07e-112050eff2ff","focus":"passage pour piétons","ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"PHG-013","theme":"signalisation","q":"Puis-je rouler sur la zone à lignes obliques blanches à droite pour dépasser la file ?","choices":["Oui, si la circulation est dense","Oui, à faible vitesse","Non, je ne peux ni y rouler, ni m'y arrêter"],"answer":2,"explain":"Les lignes parallèles obliques blanches marquent une zone d'évitement ou un îlot : il est interdit d'y circuler, de s'y arrêter et d'y stationner.","photo":"256c2db2-a84b-4f2a-9b65-dfe593c16d7d","focus":"zone hachurée à droite","ref":"Art. 77.4 AR 01/12/1975"},{"id":"PHG-014","theme":"signalisation","q":"Puis-je entrer dans cette rue avec ma voiture ?","choices":["Non, c'est un sens interdit ; seuls les cyclistes sont exceptés","Oui, le panneau additionnel autorise tous les véhicules","Oui, si je roule au pas"],"answer":0,"explain":"Le signal C1 interdit l'accès à tout conducteur dans ce sens. Le panneau additionnel avec le vélo et « EXCEPTÉ » lève l'interdiction uniquement pour les cyclistes.","grave":true,"photo":"2d5d46e1-4efc-4274-944c-fecdbd47d6b7","focus":"panneau C1 et panneau additionnel","ref":"Art. 68.3 (C1) et 68.4 AR 01/12/1975"},{"id":"PHG-015","theme":"usagers","q":"Je circule dans cette rue dans le sens autorisé (en venant de l'autre extrémité). Que dois-je prévoir à cause de cette signalisation ?","choices":["Rien de particulier, tout le monde roule dans mon sens","Des cyclistes peuvent arriver en face de moi","Des voitures peuvent arriver en face de moi"],"answer":1,"explain":"Avec un C1 complété du panneau « EXCEPTÉ » vélo, les cyclistes peuvent emprunter la rue dans les deux sens : je dois m'attendre à en croiser.","photo":"2d5d46e1-4efc-4274-944c-fecdbd47d6b7","focus":"panneau additionnel vélo","ref":"Art. 68.3 (C1) et 68.4.1° AR 01/12/1975"},{"id":"PHG-016","theme":"signalisation","q":"Ce panneau rond à bord rouge et fond blanc (C3) n'a aucun panneau additionnel. Un cycliste peut-il passer à vélo ?","choices":["Oui, le C3 ne concerne que les véhicules à moteur","Oui, si la barrière est ouverte","Non, l'accès est interdit à tout conducteur, cyclistes compris"],"answer":2,"explain":"Le C3 interdit l'accès, dans les deux sens, à tout conducteur. Les cyclistes ne sont exemptés que si un panneau additionnel M2 (vélo « excepté ») le précise.","photo":"b6ca1e21-6993-46ef-87f2-7b5349a0b381","focus":"panneau rond derrière la barrière","ref":"Art. 68.3 (C3) et 68.4.2° AR 01/12/1975"},{"id":"PHG-017","theme":"stationnement","q":"Que m'indique ce panneau bleu « P » à l'entrée de cet espace ?","choices":["Que le stationnement y est autorisé","Que le stationnement y est interdit","Qu'il s'agit d'une zone de police"],"answer":0,"explain":"Le signal E9a (P blanc sur fond bleu) indique que le stationnement est autorisé.","photo":"28e7c34e-4dbf-4eb0-a851-e3938cc68dd0","focus":"panneau P à gauche","ref":"Art. 70.2.1.3° AR 01/12/1975"},{"id":"PHG-018","theme":"stationnement","q":"Ce panneau « P RÉSERVÉ » montre un camping-car. Puis-je y garer ma voiture ordinaire ?","choices":["Oui, si j'achète un ticket","Non, il est réservé aux véhicules de camping","Oui, pour moins d'une heure"],"answer":1,"explain":"Un signal de stationnement avec le symbole du camping-car réserve les emplacements aux véhicules automobiles de camping (E9h). Les autres véhicules ne peuvent pas y stationner.","photo":"c59ec9b2-3765-484a-b361-9c64501d3b06","focus":"panneau P à gauche","ref":"Art. 70.2.1.3° (E9h) AR 01/12/1975"},{"id":"PHG-019","theme":"stationnement","q":"Ma voiture est électrique. Cet emplacement, équipé d'une borne de recharge, est signalé par un panneau « P » avec le symbole d'une voiture branchée et « Max 45 min ». Puis-je y stationner 30 minutes sans brancher la voiture ?","choices":["Oui, car je reste moins de 45 minutes","Oui, le branchement est facultatif","Non, elle doit être connectée à la borne"],"answer":2,"explain":"Ce panneau réserve le stationnement aux véhicules électriques ou hybrides électriques. Aux emplacements munis d'une infrastructure publique de recharge, comme cette borne, ces véhicules doivent y être connectés. La durée reste limitée à 45 minutes.","photo":"4e46d308-9a29-42bb-a502-b260a6829c83","focus":"panneau P à droite et borne de recharge","ref":"Art. 70.2.1.3° h) AR 01/12/1975"},{"id":"PHG-020","theme":"signalisation","q":"Le panneau à droite montre une flèche tournant à gauche, barrée de rouge, avec un panneau additionnel vélo « EXCEPTÉ ». Puis-je tourner à gauche au prochain carrefour ?","choices":["Oui, si personne n'arrive en face","Non, seuls les cyclistes y sont autorisés","Oui, mais seulement pour faire demi-tour"],"answer":1,"explain":"Le signal C31a interdit de tourner à gauche au prochain carrefour. Le panneau additionnel M2 fait une exception uniquement pour les cyclistes.","photo":"d49c4948-7479-452a-879b-4840d622f253","focus":"panneau à droite","ref":"Art. 68.3 (C31a) et 68.4.2° AR 01/12/1975"},{"id":"PHG-021","theme":"signalisation","q":"Sur l'îlot central se trouve un panneau bleu rond à flèches circulaires (D5). Comment dois-je contourner l'îlot ?","choices":["Par la gauche, en laissant l'îlot à ma droite","Par la droite, en laissant l'îlot à ma gauche","Comme je le souhaite"],"answer":1,"explain":"Le D5 impose le sens giratoire : je contourne l'îlot par la droite, en le laissant à ma gauche (sens contraire des aiguilles d'une montre).","photo":"392ba803-af23-46ef-9778-a45358494267","focus":"panneau sur l'îlot central","ref":"Art. 69.3 (D5) et 9.6 AR 01/12/1975"},{"id":"PHH-002","theme":"priorite","q":"Je vois ce panneau triangulaire (croix noire). Au carrefour suivant, qui a la priorité ?","choices":["Je suis prioritaire sur tous les conducteurs","Je dois céder le passage aux conducteurs venant de ma gauche","Je dois céder le passage aux conducteurs venant de ma droite"],"answer":2,"explain":"Le signal B17 annonce un carrefour où la priorité de droite est applicable : je dois céder le passage à celui qui vient de ma droite.","grave":true,"photo":"74d6ba68-571e-42f4-a609-ac69533dbdee","focus":"panneau triangulaire au-dessus du P","ref":"Art. 67.3 (B17) et art. 12.3.1 AR 01/12/1975"},{"id":"PHH-003","theme":"vitesse","q":"À quelle vitesse maximale puis-je rouler à hauteur de ces panneaux ?","choices":["50 km/h","30 km/h","70 km/h"],"answer":0,"explain":"Le signal C43 « 50 », accompagné ici de la mention « RAPPEL », rappelle que la vitesse est limitée à 50 km/h.","photo":"c2439304-d12c-4a71-ba9e-cf302295b7f3","focus":"panneau rond « 50 »","ref":"Art. 68.3 (C43) AR 01/12/1975"},{"id":"PHH-004","theme":"signalisation","q":"Que m'annonce le panneau triangulaire placé au-dessus de la limitation de vitesse ?","choices":["Une chaussée glissante","Un ou plusieurs dispositifs surélevés (ralentisseurs)","Un passage pour piétons"],"answer":1,"explain":"Le signal A14 annonce un ou plusieurs dispositifs surélevés. Je dois l'aborder prudemment et à allure modérée.","photo":"c2439304-d12c-4a71-ba9e-cf302295b7f3","focus":"triangle en haut du poteau","ref":"Art. 66.4 (A14) et art. 22ter AR 01/12/1975"},{"id":"PHH-005","theme":"signalisation","q":"La voiture devant moi roule lentement. Puis-je circuler sur la zone à lignes obliques blanches, à gauche de ma bande, pour la dépasser ?","choices":["Oui, si personne ne vient en sens inverse","Oui, mais seulement pour tourner à gauche","Non, il est interdit d'y circuler, de s'y arrêter et d'y stationner"],"answer":2,"explain":"Les lignes parallèles obliques blanches délimitent une zone d'évitement ou un îlot directionnel : on ne peut ni y circuler, ni s'y arrêter, ni y stationner.","photo":"22ea78a4-2c32-49f6-b88b-34cdb6169d20","focus":"zone hachurée au milieu de la chaussée","ref":"Art. 77.4 AR 01/12/1975"},{"id":"PHH-006","theme":"depassement","q":"Plus loin se trouve un passage pour piétons (panneau bleu à droite), sans feux ni agent. Si le véhicule devant moi ralentit en s'approchant de ce passage, puis-je le dépasser ?","choices":["Oui, si aucun piéton n'est visible","Non, ce dépassement est interdit","Oui, si la ligne médiane est discontinue"],"answer":1,"explain":"Il est interdit de dépasser un véhicule qui s'approche d'un passage pour piétons ou qui s'arrête devant celui-ci, là où la circulation n'est pas réglée par des feux ou un agent : il peut masquer un piéton.","grave":true,"photo":"50c68f8e-56c0-4545-83c4-64556ef6dc14","focus":"panneau bleu « passage pour piétons » à droite","ref":"Art. 17.2, 5° AR 01/12/1975"},{"id":"PHH-007","theme":"vitesse","q":"J'entre dans la zone signalée par le panneau bleu à droite. Quelle est la vitesse maximale autorisée ?","choices":["50 km/h","30 km/h","20 km/h"],"answer":1,"explain":"Le signal F111 marque le début d'une zone cyclable. La vitesse n'y peut jamais être supérieure à 30 km/h.","photo":"ebfaa109-0e2f-49d9-a913-fbad6a6309ba","focus":"panneau « Zone cyclable » à droite","ref":"Art. 22novies et art. 71 (F111) AR 01/12/1975"},{"id":"PHH-008","theme":"depassement","q":"Dans cette zone cyclable, un cycliste roule devant moi à 20 km/h. Puis-je le dépasser avec ma voiture ?","choices":["Non, les véhicules à moteur ne peuvent pas y dépasser les cyclistes","Oui, en laissant au moins 1 mètre d'écart latéral","Oui, mais seulement si la chaussée est à sens unique"],"answer":0,"explain":"Les véhicules à moteur peuvent circuler dans une zone cyclable, mais ils ne peuvent pas y dépasser les cyclistes.","grave":true,"photo":"ebfaa109-0e2f-49d9-a913-fbad6a6309ba","focus":"panneau « Zone cyclable » à droite","ref":"Art. 22novies AR 01/12/1975"},{"id":"PHH-009","theme":"signalisation","q":"Puis-je m'engager en voiture dans cette rue ?","choices":["Oui, car le panneau ne vise que les cyclistes","Oui, mais seulement pour accéder à une propriété","Non, c'est un sens interdit pour moi"],"answer":2,"explain":"Le signal C1 interdit l'accès à tout conducteur dans ce sens. Le panneau additionnel n'autorise que les cyclistes à y entrer.","grave":true,"photo":"036e5482-7d9e-4972-9fae-bc5f13e0deec","focus":"panneau rond rouge à barre blanche","ref":"Art. 68.3 (C1) AR 01/12/1975"},{"id":"PHH-010","theme":"signalisation","q":"Que signifie le panneau additionnel « EXCEPTÉ » avec une bicyclette, sous le sens interdit ?","choices":["Les cyclistes peuvent entrer dans cette rue malgré le sens interdit","Les cyclistes doivent descendre de leur vélo","La rue est réservée aux seuls cyclistes"],"answer":0,"explain":"Le panneau additionnel M2 complète le signal C1 : l'interdiction ne s'applique pas aux cyclistes, qui peuvent circuler à contresens. Le marquage vélo au sol le rappelle.","photo":"036e5482-7d9e-4972-9fae-bc5f13e0deec","focus":"panneau blanc sous le sens interdit","ref":"Art. 65.2 (M2) et art. 68.3 (C1) AR 01/12/1975"},{"id":"PHH-011","theme":"vitesse","q":"Je passe à hauteur du panneau « ZONE 30 » à droite. À quelle vitesse maximale puis-je rouler ensuite ?","choices":["50 km/h, sauf près des écoles","30 km/h dans toute la zone","30 km/h uniquement sur les ralentisseurs"],"answer":1,"explain":"Le signal F4a marque le début d'une zone 30 : la vitesse y est limitée à 30 km/h jusqu'au signal F4b de fin de zone.","photo":"5a1de192-d922-4327-9b6e-ceb3a7de4274","focus":"panneau « zone 30 » en haut à droite","ref":"Art. 22quater AR 01/12/1975"},{"id":"PHH-012","theme":"priorite","q":"J'arrive à ce panneau STOP. Que dois-je faire ?","choices":["Ralentir fortement et passer si personne n'arrive","Marquer l'arrêt complet, puis céder le passage aux conducteurs de la voie que j'aborde","Céder le passage uniquement aux conducteurs venant de droite"],"answer":1,"explain":"Le signal B5 impose de marquer l'arrêt (à la ligne d'arrêt s'il y en a une) et de céder le passage à tous les conducteurs circulant sur la voie abordée.","grave":true,"photo":"9019b681-3510-4cec-b0b0-27bc98d87291","focus":"panneau STOP à droite","ref":"Art. 67.3 (B5), art. 12.3.1 a) et art. 76.1 AR 01/12/1975"},{"id":"PHH-013","theme":"usagers","q":"Ce passage pour piétons est équipé de feux. Si le feu passe au vert pour moi alors que ces piétons sont encore en train de traverser, que dois-je faire ?","choices":["Les laisser achever leur traversée avant de passer","Passer, car le feu vert me donne la priorité","Klaxonner pour qu'ils se dépêchent"],"answer":0,"explain":"Même lorsque la circulation est ouverte dans mon sens, je dois permettre aux piétons régulièrement engagés sur la chaussée d'achever leur traversée à allure normale.","grave":true,"photo":"9ff28b60-3d19-4c68-9727-cf619fa19f10","focus":"piétons sur le passage à gauche","ref":"Art. 40.4.1 AR 01/12/1975"},{"id":"PHH-014","theme":"usagers","q":"Je veux tourner à droite dans la rue latérale. Si un cycliste arrive derrière moi sur la piste cyclable rouge, qui passe en premier ?","choices":["Moi, car je suis sur la chaussée principale","Le cycliste : je dois lui céder le passage","Celui qui arrive le premier au croisement"],"answer":1,"explain":"Le conducteur qui change de direction doit céder le passage aux conducteurs qui circulent sur les autres parties de la même voie publique, comme la piste cyclable, ainsi qu'aux piétons qui traversent la chaussée où il s'engage.","grave":true,"photo":"9be9722a-d2eb-4a69-be6d-f0f93cdb0ee4","focus":"piste cyclable rouge à droite","ref":"Art. 19.4, 19.5 et 12.4bis AR 01/12/1975"},{"id":"PHH-016","theme":"priorite","q":"Un rétrécissement est annoncé à 100 m. Avec le panneau carré bleu placé au-dessus, qui a la priorité dans le passage étroit ?","choices":["Moi, par rapport aux conducteurs venant en sens inverse","Les conducteurs venant en sens inverse","Le premier arrivé, sans règle particulière"],"answer":0,"explain":"Le signal B21 (flèche blanche vers le haut, flèche rouge vers le bas) donne la priorité de passage par rapport aux conducteurs venant en sens opposé. Je reste toutefois prudent.","photo":"164a04e8-0764-4fae-b3eb-5c993de4d9f3","focus":"panneau carré bleu à droite","ref":"Art. 67.3 (B21) AR 01/12/1975"},{"id":"PHH-017","theme":"signalisation","q":"Que m'annonce le panneau triangulaire avec la mention « 100 m » ?","choices":["Un rétrécissement de la chaussée à environ 100 m","Une route à deux bandes de circulation","La fin d'une route prioritaire"],"answer":0,"explain":"Les signaux A7 annoncent un rétrécissement de la chaussée ; le panneau additionnel indique la distance approximative jusqu'au danger.","photo":"164a04e8-0764-4fae-b3eb-5c993de4d9f3","focus":"triangle sous le panneau bleu","ref":"Art. 66.4 (A7) AR 01/12/1975"},{"id":"PHH-018","theme":"vitesse","q":"Je quitte la localité (Région wallonne). Après ces panneaux, à quelle vitesse maximale puis-je rouler ?","choices":["90 km/h, car je sors de l'agglomération","50 km/h jusqu'au prochain carrefour","70 km/h"],"answer":2,"explain":"Hors agglomération en Wallonie, la limite générale est de 90 km/h, mais le signal C43 « 70 » impose ici une limitation inférieure qui prime.","photo":"cb32abad-e7fe-462b-be31-522c0819c1fd","focus":"panneau « 70 » au-dessus du nom barré","ref":"Art. 11.2 (Région wallonne) et art. 68.3 (C43) AR 01/12/1975"},{"id":"PHH-019","theme":"signalisation","q":"Que signifie le panneau blanc portant le nom « Branchon » barré d'une bande rouge ?","choices":["La fin de l'agglomération","Un sens interdit vers ce village","La fin d'une zone résidentielle"],"answer":0,"explain":"Le signal F3a indique la sortie d'une agglomération. Les règles propres aux agglomérations cessent de s'appliquer.","photo":"cb32abad-e7fe-462b-be31-522c0819c1fd","focus":"panneau blanc au nom barré","ref":"Art. 2.12 et art. 71 (F3a) AR 01/12/1975"},{"id":"PHH-020","theme":"usagers","q":"Le panneau bleu annonce un passage pour piétons. En supposant qu'il n'est réglé ni par des feux ni par un agent, comment dois-je l'aborder ?","choices":["À allure modérée, en cédant le passage aux piétons engagés ou sur le point de s'y engager","À vitesse normale ; je ne m'arrête que si un piéton est déjà au milieu","En klaxonnant pour avertir les piétons"],"answer":0,"explain":"Là où la circulation n'est pas réglée par des feux ou un agent, je ne peux m'approcher d'un passage pour piétons qu'à allure modérée et je dois céder le passage aux piétons qui y sont engagés ou sur le point de s'y engager.","grave":true,"photo":"141cae8a-cd5a-4171-b118-52a4dedd42f6","focus":"panneau bleu à droite","ref":"Art. 40.4.2 et art. 71 (F49) AR 01/12/1975"},{"id":"PHH-021","theme":"signalisation","q":"Puis-je emprunter ce chemin avec ma voiture ?","choices":["Oui, à 30 km/h maximum","Non, l'accès y est interdit à tout conducteur, sauf aux cyclistes","Oui, mais uniquement dans un sens"],"answer":1,"explain":"Le signal C3 interdit l'accès, dans les deux sens, à tout conducteur. Le panneau additionnel « EXCEPTÉ » vélo autorise seulement les cyclistes.","photo":"933a1a6a-dd69-4db7-8b3a-5db1774c8dab","focus":"panneau rond blanc bordé de rouge","ref":"Art. 68.3 (C3) et art. 68.4.2° AR 01/12/1975"},{"id":"PHH-022","theme":"signalisation","q":"Le panneau carré bleu à droite représente les catégories d'usagers admises sur ce chemin (on y distingue notamment un cavalier) ; aucune voiture n'y figure. Puis-je circuler sur ce chemin avec ma voiture ?","choices":["Oui, à 30 km/h maximum","Oui, si je roule au pas","Non, seuls les usagers représentés sur le panneau peuvent y circuler"],"answer":2,"explain":"Les signaux F99 indiquent un chemin réservé aux catégories d'usagers dont le symbole figure sur le panneau. Les voitures ne peuvent pas y circuler (sauf exceptions, comme les véhicules prioritaires en mission ou les véhicules autorisés par le gestionnaire).","photo":"47756446-eff2-48bd-b1b4-23e46bf33ec4","focus":"panneau carré bleu à droite","ref":"Art. 22quinquies.1 et art. 71 (F99) AR 01/12/1975"},{"id":"PHH-023","theme":"stationnement","q":"Je n'ai pas de carte spéciale de stationnement pour personnes handicapées. Puis-je stationner à l'emplacement signalé par ce panneau ?","choices":["Oui, pendant 15 minutes maximum","Non, il est réservé aux véhicules des titulaires de cette carte","Oui, si je reste dans le véhicule"],"answer":1,"explain":"Le signal E9a avec le symbole du fauteuil roulant réserve le stationnement aux véhicules utilisés par des personnes handicapées titulaires de la carte spéciale.","photo":"766635f8-5f1a-49ef-8f83-56bce4d1e783","focus":"panneau P avec fauteuil roulant","ref":"Art. 27bis et art. 70.2.1, 3° c) AR 01/12/1975"},{"id":"PHI-001","theme":"priorite","q":"Je suis entré dans ce rond-point (panneau triangulaire pointe en bas à l'entrée et panneau bleu à flèches circulaires sur l'îlot). Je circule dans l'anneau et une voiture arrive par une autre entrée, située à ma droite. Qui a la priorité ?","choices":["La voiture qui arrive de ma droite, priorité de droite oblige","Moi, car je circule déjà dans le rond-point","Celui qui roule le plus vite"],"answer":1,"explain":"La priorité de droite ne s'applique pas à celui qui circule dans un rond-point. Les conducteurs qui y entrent par une branche munie d'un signal B1 doivent céder le passage à ceux qui circulent dans l'anneau.","grave":true,"photo":"f1830314-1a47-4ab3-94e9-e07d41a50c4f","focus":"triangle à droite et panneau bleu rond sur l'îlot","ref":"Art. 12.3.1 AR 01/12/1975"},{"id":"PHI-002","theme":"signalisation","q":"Dans l'anneau de ce rond-point (signalé par D5 et B1), aucune partie de la chaussée ne m'est réservée. Suis-je obligé de rouler le plus près possible du bord droit ?","choices":["Oui, comme sur toute chaussée","Non, je dois toujours rouler contre l'îlot central","Non, dans l'anneau d'un rond-point je n'y suis pas tenu, mais je dois respecter les éventuelles marques de bandes"],"answer":2,"explain":"Dans l'anneau d'un rond-point, le conducteur n'est pas tenu de serrer le bord droit (sauf partie réservée). S'il y a des bandes marquées, il peut choisir celle qui convient le mieux à sa destination.","photo":"f1830314-1a47-4ab3-94e9-e07d41a50c4f","focus":"anneau du rond-point","ref":"Art. 9.3.1 AR 01/12/1975"},{"id":"PHI-003","theme":"usagers","q":"Un triangle rouge et blanc montrant des enfants est peint sur la chaussée devant moi. Que m'annonce-t-il ?","choices":["Un endroit spécialement fréquenté par des enfants : je redouble de prudence","Une aire de jeux où la circulation automobile est interdite","Un passage pour piétons réglé par des feux"],"answer":0,"explain":"Ce symbole reproduit le signal A23 : endroit spécialement fréquenté par des enfants (par exemple les abords d'une école). Je ralentis et je suis prêt à m'arrêter.","photo":"cdbc8c13-ad09-419b-8578-3bce929dd2d1","focus":"triangle peint sur la chaussée","ref":"Art. 66.3-66.4 (A23) AR 01/12/1975"},{"id":"PHI-004","theme":"signalisation","q":"Que signifie le panneau carré bleu, à droite, montrant un triangle blanc avec une bosse noire ?","choices":["Un passage pour piétons","Un ou plusieurs dispositifs surélevés (ralentisseurs)","Une chaussée en mauvais état"],"answer":1,"explain":"Le signal F87 indique l'emplacement d'un ou plusieurs dispositifs surélevés. Je dois les aborder prudemment, à allure modérée.","photo":"6133cd8e-db24-4ef3-998e-fba6685b8d7a","focus":"panneau carré bleu à droite","ref":"Art. 71 (F87) et art. 22ter AR 01/12/1975"},{"id":"PHI-005","theme":"stationnement","q":"Ce panneau carré bleu (F87) indique un dispositif surélevé. Sauf réglementation locale, puis-je mettre ma voiture à l'arrêt ou en stationnement sur ce dispositif ?","choices":["Oui, s'il n'y a pas de ligne jaune","Oui, mais seulement à l'arrêt, feux de détresse allumés","Non, l'arrêt et le stationnement y sont interdits"],"answer":2,"explain":"Sauf réglementation locale, il est interdit de mettre un véhicule à l'arrêt ou en stationnement sur les dispositifs surélevés.","photo":"6133cd8e-db24-4ef3-998e-fba6685b8d7a","focus":"panneau carré bleu à droite","ref":"Art. 24, 11° AR 01/12/1975"},{"id":"PHI-006","theme":"stationnement","q":"Le panneau de stationnement interdit (rond bleu bordé de rouge, une barre oblique) est complété par un panneau additionnel qui limite l'interdiction à certains jours et heures (jour de marché). En dehors de cette période, puis-je stationner à cet endroit ?","choices":["Oui, l'interdiction ne s'applique que pendant la période indiquée","Non, l'interdiction s'applique en permanence","Oui, mais seulement avec un disque de stationnement"],"answer":0,"explain":"Une inscription sous les signaux E1 ou E3 peut indiquer la période pendant laquelle l'interdiction est applicable. En dehors de cette période, l'interdiction ne joue pas.","photo":"ae015167-a2ba-49cf-930f-f48edd48fd66","focus":"panneau sur le poteau orange à gauche","ref":"Art. 70.2.1, 1° AR 01/12/1975"},{"id":"PHI-007","theme":"stationnement","q":"Le panneau de stationnement interdit visible sur le poteau orange s'applique-t-il des deux côtés de la voie publique ?","choices":["Oui, des deux côtés jusqu'au prochain carrefour","Non, seulement sur les 15 mètres qui suivent le panneau","Non, seulement du côté de la voie publique où il est placé, jusqu'au prochain carrefour"],"answer":2,"explain":"Les signaux E1, E3 et E9a à E9j ont effet du côté de la voie publique où ils sont placés, à partir du signal jusqu'au prochain carrefour (sauf panneau de fin).","photo":"ae015167-a2ba-49cf-930f-f48edd48fd66","focus":"panneau sur le poteau orange","ref":"Art. 70.2.2, 1° AR 01/12/1975"},{"id":"PHI-008","theme":"stationnement","q":"Le panneau bleu « P » à droite autorise le stationnement. Jusqu'où vaut-il, en l'absence de panneau indiquant la fin ?","choices":["Jusqu'au prochain carrefour","Sur 100 mètres seulement","Jusqu'à la sortie de l'agglomération"],"answer":0,"explain":"Le signal E9a a effet du côté de la voie publique où il est placé, à partir du signal jusqu'au prochain carrefour, sauf si un signal de fin le précède.","photo":"115cb0e5-9735-4257-8276-ea1895850b97","focus":"panneau P à droite","ref":"Art. 70.2.2, 1° AR 01/12/1975"},{"id":"PHI-009","theme":"priorite","q":"Un véhicule de police, feux bleus clignotants allumés, se trouve devant moi. S'il fait aussi retentir son avertisseur sonore spécial, que dois-je faire ?","choices":["Continuer normalement : il doit attendre que la voie soit libre","Dégager immédiatement et lui céder le passage, au besoin en m'arrêtant","Le suivre de près pour profiter du passage qu'il ouvre"],"answer":1,"explain":"Dès que l'approche d'un véhicule prioritaire est signalée par l'avertisseur sonore spécial, tout usager doit immédiatement dégager et céder le passage ; au besoin, il doit s'arrêter.","grave":true,"photo":"79cabdbc-c048-426f-a220-1f0e8b87306f","focus":"voiture de police au centre","ref":"Art. 38 AR 01/12/1975"},{"id":"PHI-010","theme":"stationnement","q":"Le panneau bleu montre un « P » et le symbole d'une voiture. Je conduis une camionnette. Puis-je y stationner ?","choices":["Oui, tous les véhicules peuvent y stationner","Oui, mais seulement la nuit","Non, ce stationnement est réservé aux motocyclettes, voitures, voitures mixtes et minibus"],"answer":2,"explain":"Le signal E9b réserve le stationnement aux motocyclettes, voitures, voitures mixtes et minibus. Les camionnettes et camions ont leur propre signal (E9c).","photo":"026a9e9a-7bb2-4bf9-b480-e86b57d07621","focus":"panneau P sur le poteau","ref":"Art. 70.2.1, 3° (E9b) AR 01/12/1975"},{"id":"PHI-011","theme":"stationnement","q":"Sous le panneau « P » se trouve un panneau blanc avec une seule flèche noire pointant vers le haut. Que signifie-t-elle ?","choices":["Le début de la réglementation de stationnement, valable à partir du panneau","La fin de la réglementation de stationnement","Le stationnement est obligatoire sur le trottoir"],"answer":0,"explain":"Les signaux de stationnement peuvent être complétés par des panneaux blancs à flèche noire : une flèche vers le haut indique le début de la réglementation, qui vaut ensuite jusqu'au prochain carrefour (sauf panneau de fin).","photo":"026a9e9a-7bb2-4bf9-b480-e86b57d07621","focus":"flèche sous le panneau P","ref":"Art. 70.2.2, 1° AR 01/12/1975"},{"id":"PHI-012","theme":"signalisation","q":"Je roule sur la bande marquée « BUS » (avec un vélo). Je veux tourner à droite au carrefour qui se trouve juste devant. Puis-je utiliser cette bande à l'approche immédiate du carrefour ?","choices":["Non, jamais","Oui, pour changer de direction à l'approche immédiate du carrefour","Oui, sur toute sa longueur si la circulation est fluide"],"answer":1,"explain":"Les véhicules non autorisés peuvent circuler sur la bande bus pour changer de direction à l'approche immédiate d'un carrefour, pour contourner un obstacle, ou la traverser pour accéder à une propriété ou un emplacement de stationnement.","photo":"9e1f578b-012b-4c65-871f-314989b8fe32","focus":"inscription BUS sur la chaussée","ref":"Art. 72.5, 3° AR 01/12/1975"},{"id":"PHI-013","theme":"stationnement","q":"Que signifie le panneau blanc « ZONE » avec un « P », barré d'une bande noire, à droite ?","choices":["La fin d'une zone où le stationnement est réglementé","Le début d'une zone où le stationnement est interdit","Un parking réservé aux riverains"],"answer":0,"explain":"Un signal de zone barré (validité zonale) indique la fin de la zone où la réglementation de stationnement s'appliquait.","photo":"178b7d07-85ff-46a5-a09b-d0238b2eabd7","focus":"panneau barré à droite","ref":"Art. 65.5 AR 01/12/1975"},{"id":"PHI-014","theme":"stationnement","q":"Le panneau blanc du haut porte la mention « ZONE » et un « P » bleu (début d'une zone de stationnement réglementé). Où s'applique cette réglementation ?","choices":["Seulement jusqu'au prochain carrefour","Uniquement du côté de la rue où le panneau est placé","Dans toute la zone jusqu'au panneau de fin de zone, sauf aux emplacements où une autre réglementation est signalée"],"answer":2,"explain":"Un signal à validité zonale a effet dans toute la zone délimitée, jusqu'au signal de fin de zone, sauf aux emplacements où une autre réglementation de stationnement est prévue par une signalisation.","photo":"b5f92e6c-448f-46a0-b49b-1ec1f38037a7","focus":"panneau du haut sur le poteau à gauche","ref":"Art. 65.5.6 AR 01/12/1975"},{"id":"PHI-015","theme":"priorite","q":"Des rails de tram sont posés dans la chaussée où je roule. Si un tram arrive derrière moi alors que je circule sur les rails, que dois-je faire ?","choices":["Continuer : le tram doit attendre que je tourne","Lui céder le passage et m'écarter de la voie ferrée dès que possible","Accélérer pour garder mon avance"],"answer":1,"explain":"Tout usager doit céder le passage aux véhicules sur rails ; il doit s'écarter de la voie ferrée dès que possible.","grave":true,"photo":"539e8083-1b68-4562-8c33-5a4c19c28f55","focus":"rails au centre de la chaussée","ref":"Art. 12.1 AR 01/12/1975"},{"id":"PHI-016","theme":"usagers","q":"Une piste cyclable (bande grise entre la chaussée et le trottoir) longe cette rue. Si je sors en voiture d'une propriété riveraine et dois traverser le trottoir et cette piste cyclable, qui a la priorité ?","choices":["Les piétons et cyclistes qui circulent sur le trottoir et la piste cyclable","Moi, car je suis déjà engagé","Les cyclistes seulement s'ils roulent à plus de 20 km/h"],"answer":0,"explain":"Le conducteur qui traverse un trottoir ou une piste cyclable doit céder le passage aux usagers qui y circulent régulièrement. Déboucher d'une propriété riveraine est en outre une manœuvre.","grave":true,"photo":"fb859a14-813b-482f-b587-c78abc105246","focus":"piste cyclable au centre","ref":"Art. 12.4 et 12.4bis AR 01/12/1975"},{"id":"PHI-017","theme":"usagers","q":"Un bus arrive en sens inverse. Si des véhicules en stationnement de mon côté m'empêchent de croiser sans gêner le bus, que dois-je faire ?","choices":["Passer en premier : le bus doit s'arrêter","Klaxonner pour qu'il se range","Ralentir et au besoin m'arrêter pour laisser passer le bus"],"answer":2,"explain":"Le conducteur dont la progression est entravée par un obstacle doit ralentir et au besoin s'arrêter pour laisser passer les usagers qui viennent en sens inverse.","photo":"666fc75e-e81a-4065-a44d-2428c517209d","focus":"bus au fond","ref":"Art. 15.2 AR 01/12/1975"},{"id":"PHJ-001","theme":"signalisation","q":"Une grande flèche blanche oblique, pointée vers l'avant gauche, est peinte dans la bande de droite où je roule. Que m'annonce-t-elle ?","choices":["Que je dois tourner à gauche au prochain carrefour","Que le nombre de bandes utilisables va diminuer : je dois me déporter vers la gauche","Que la bande de droite est réservée aux bus"],"answer":1,"explain":"Les flèches de rabattement blanches annoncent la réduction du nombre de bandes de circulation utilisables dans le sens suivi. Il faut changer de bande à temps, en cédant le passage.","photo":"98829ae6-22a3-43a3-a66b-b95b8c40d2f0","focus":"flèche oblique dans la bande de droite","ref":"Art. 77.2 AR 01/12/1975"},{"id":"PHJ-002","theme":"priorite","q":"Une ligne de triangles blancs, pointes vers moi, est peinte en travers de ma bande avant la rue transversale. Que signifie-t-elle ?","choices":["Je dois toujours marquer l'arrêt complet à cette ligne","C'est un ralentisseur : je dois passer à 30 km/h","Je dois céder le passage et, s'il y a lieu, m'arrêter à hauteur de cette ligne"],"answer":2,"explain":"La ligne de triangles blancs indique l'endroit où le conducteur doit s'arrêter, s'il y a lieu, pour céder le passage (comme avec un signal B1). L'arrêt n'est obligatoire que si un usager prioritaire arrive.","photo":"1995a390-be92-4803-86f7-183a44d74e4f","focus":"ligne de triangles en travers de la bande","ref":"Art. 76.2 AR 01/12/1975"},{"id":"PHJ-003","theme":"signalisation","q":"Le feu à droite est rouge. Je veux tourner à droite et aucun véhicule ni piéton n'est en vue. Puis-je franchir la ligne d'arrêt ?","choices":["Non, le feu rouge interdit de franchir la ligne d'arrêt (ou le feu), quelle que soit la direction","Oui, tourner à droite est toujours permis au feu rouge","Oui, si je roule au pas"],"answer":0,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt ou, à défaut, le signal lui-même. Seule une flèche verte supplémentaire allumée permettrait de poursuivre dans la direction indiquée.","grave":true,"photo":"6bf7e072-c721-40b2-832b-2cf4663fbbdb","focus":"feu à droite","ref":"Art. 61.1 AR 01/12/1975"},{"id":"PHJ-004","theme":"stationnement","q":"À droite, un panneau rond bleu bordé de rouge, barré d'une croix rouge (E3), sans panneau additionnel. Puis-je m'arrêter un instant de ce côté pour déposer un passager ?","choices":["Oui, l'arrêt bref est toujours permis","Non, ce signal interdit l'arrêt et le stationnement","Oui, si je reste au volant"],"answer":1,"explain":"Le signal E3 (croix rouge) interdit l'arrêt et le stationnement, du côté où il est placé jusqu'au prochain carrefour. Déposer un passager est un arrêt, donc interdit. Le signal E1 (une seule barre) n'interdit que le stationnement.","photo":"73073d04-b5a6-484d-9026-4f0e085bdac2","focus":"panneau à croix rouge au premier plan","ref":"Art. 70.2.1 et 70.2.2 AR 01/12/1975"},{"id":"PHJ-005","theme":"stationnement","q":"Le panneau rond bleu bordé de rouge, barré d'une seule diagonale (E1), est fixé sur la façade à droite, sans panneau additionnel. Où l'interdiction de stationner s'applique-t-elle ?","choices":["Des deux côtés de la rue, sur toute sa longueur","Uniquement sur 15 m autour du panneau","Du côté droit, à partir du panneau jusqu'au prochain carrefour"],"answer":2,"explain":"Les signaux E1 et E3 ont effet du côté de la voie publique où ils sont placés, à partir du signal et jusqu'au prochain carrefour, sauf panneau additionnel indiquant autre chose.","photo":"514bfffa-6d7c-4bc6-a68d-8bd5aff97454","focus":"panneau sur la façade à droite","ref":"Art. 70.2.2 AR 01/12/1975"},{"id":"PHJ-006","theme":"priorite","q":"Le feu sur l'îlot est vert pour moi. Juste en dessous se trouve un panneau STOP. Dois-je marquer l'arrêt ?","choices":["Non, quand les feux fonctionnent, ils rendent sans effet le panneau STOP placé sur la même voie","Oui, le STOP l'emporte toujours sur le feu","Oui, mais seulement si un véhicule arrive de droite"],"answer":0,"explain":"Quand les signaux lumineux fonctionnent, ils rendent sans effet les signaux de priorité (comme B5) placés sur la même voie. Au vert, je peux franchir le signal, en restant attentif.","photo":"241319f5-6ec0-4a88-b4f7-515776c57573","focus":"feu et panneau STOP sur l'îlot","ref":"Art. 6.3 et 61.1 AR 01/12/1975"},{"id":"PHJ-007","theme":"priorite","q":"Le feu sur l'îlot, au-dessus du panneau STOP, se met à clignoter à l'orange. Que dois-je faire ?","choices":["Passer sans m'arrêter, le feu orange clignotant me donne la priorité","Respecter le STOP : marquer l'arrêt et céder le passage","Attendre que le feu repasse au vert"],"answer":1,"explain":"Le feu jaune-orange clignotant ne modifie pas les règles de priorité et ne rend pas le signal de priorité sans effet : le STOP s'applique, il faut s'arrêter et céder le passage.","grave":true,"photo":"241319f5-6ec0-4a88-b4f7-515776c57573","focus":"feu et panneau STOP sur l'îlot","ref":"Art. 6.3 et 64.1 AR 01/12/1975"},{"id":"PHJ-008","theme":"signalisation","q":"Le feu à droite est rouge et un panneau triangulaire pointe en bas (cédez le passage) est fixé sous ce feu. Si aucun véhicule n'arrive, puis-je passer ?","choices":["Oui, le panneau cédez le passage me permet de passer s'il n'y a personne","Oui, mais seulement au pas","Non, je dois m'arrêter : le feu rouge prévaut"],"answer":2,"explain":"Quand les feux fonctionnent, ils rendent sans effet les signaux de priorité placés sur la même voie. Le feu rouge interdit de franchir la ligne d'arrêt ou le feu.","grave":true,"photo":"affa70e1-c19b-4a2c-a646-f2243dd85b9e","focus":"feu et panneau sur le poteau à droite","ref":"Art. 6.3 et 61.1 AR 01/12/1975"},{"id":"PHJ-009","theme":"vitesse","q":"Je roule en voiture sur cette autoroute. Un panneau rond « 90 » est placé à gauche et un autre à droite. Quelle est ma vitesse maximale ?","choices":["90 km/h","120 km/h","70 km/h"],"answer":0,"explain":"Le signal C43 impose une vitesse maximale, ici 90 km/h, même sur autoroute. Il prévaut sur la limite générale de 120 km/h.","photo":"0efbc9e5-637f-45ae-a2a2-0b193091dd12","focus":"panneaux « 90 » au fond, à gauche et à droite","ref":"Art. 6.2 et 68.3 (C43) AR 01/12/1975"},{"id":"PHJ-010","theme":"autoroute","q":"Sur cette autoroute, une sortie se sépare sur la droite (zone hachurée). Si je la manque, que dois-je faire ?","choices":["Reculer prudemment sur la bande d'arrêt d'urgence","Continuer jusqu'à la sortie suivante","M'arrêter et attendre une occasion de traverser la zone hachurée"],"answer":1,"explain":"Sur autoroute, il est interdit de faire marche arrière, de faire demi-tour et de s'arrêter en dehors des aires prévues. On ne peut pas non plus circuler sur les zones hachurées. Il faut continuer jusqu'à la sortie suivante.","grave":true,"photo":"0efbc9e5-637f-45ae-a2a2-0b193091dd12","focus":"zone hachurée à droite","ref":"Art. 21.4 et 77.4 AR 01/12/1975"},{"id":"PHJ-011","theme":"autoroute","q":"Je roule sur la bande du milieu de cette autoroute. Une fois que j'aurai dépassé le camion à ma droite, que dois-je faire ?","choices":["Reprendre ma place à droite dès que je peux le faire sans inconvénient, en mettant mon clignotant","Rester au milieu, c'est la bande la plus sûre","Passer sur la bande de gauche"],"answer":0,"explain":"Après un dépassement par la gauche, le conducteur doit reprendre sa place à droite aussitôt qu'il peut le faire sans inconvénient, en l'annonçant avec ses indicateurs de direction. Sur la chaussée, on se tient le plus près possible du bord droit.","photo":"a81e11c4-7d5c-4ebc-aff9-6d98fe6f99f8","focus":"camion à droite","ref":"Art. 16.6 et 9.3.1 AR 01/12/1975"},{"id":"PHJ-012","theme":"autoroute","q":"Ma voiture tombe en panne sur cette autoroute et je ne peux l'arrêter que sur la bande d'arrêt d'urgence. À quelle distance minimale derrière la voiture dois-je placer le triangle de danger ?","choices":["30 mètres","50 mètres","100 mètres"],"answer":2,"explain":"Le triangle de danger se place en deçà du véhicule, à au moins 100 m sur autoroute (30 m sur les voies ordinaires), visible à environ 50 m.","photo":"b94899c4-b958-4726-9380-c0f27fb94746","focus":"bande d'arrêt d'urgence à droite","ref":"Art. 51.1 et 51.2 AR 01/12/1975"},{"id":"PHJ-013","theme":"autoroute","q":"En panne sur la bande d'arrêt d'urgence de cette autoroute (panneau SOS à droite), je dois sortir de ma voiture. Qu'est-ce qui est obligatoire ?","choices":["Rien de particulier si je reste près de la voiture","Porter une veste de sécurité rétroréfléchissante dès que je sors","Allumer seulement mes feux de croisement"],"answer":1,"explain":"Sur autoroute et route pour automobiles, le conducteur d'un véhicule en panne rangé là où l'arrêt et le stationnement sont interdits doit porter une veste de sécurité rétroréfléchissante dès qu'il sort.","photo":"b94899c4-b958-4726-9380-c0f27fb94746","focus":"panneau « SOS » à droite","ref":"Art. 51.4 AR 01/12/1975"},{"id":"PHJ-014","theme":"autoroute","q":"Si la circulation ralentit sur cette autoroute, puis-je rouler sur la bande d'arrêt d'urgence, à droite de la ligne blanche continue, pour remonter la file ?","choices":["Oui, si je roule lentement","Oui, mais seulement pour rejoindre la sortie suivante","Non, c'est interdit"],"answer":2,"explain":"Les conducteurs doivent emprunter la chaussée, dont le bord est marqué par la ligne continue. Remonter une file par la bande d'arrêt d'urgence revient à dépasser par la droite, ce qui est interdit.","grave":true,"photo":"f2a6cdb6-07ec-4f36-994a-774a86ae36ab","focus":"ligne continue à droite","ref":"Art. 9.1.1 et 16.3 AR 01/12/1975"},{"id":"PHJ-015","theme":"signalisation","q":"Le panneau rond blanc bordé de rouge (C3), à droite, est complété par un panneau additionnel « 50 m ». Que signifie-t-il ?","choices":["L'accès interdit à tout conducteur commence à environ 50 m","La vitesse est limitée à 50 km/h","L'accès est interdit aux véhicules de plus de 50 m de long"],"answer":0,"explain":"Un signal d'interdiction peut être annoncé par un signal identique complété d'un panneau additionnel indiquant la distance approximative à laquelle l'interdiction commence. Le C3 interdit l'accès dans les deux sens à tout conducteur.","photo":"1d55496c-039e-4652-aaf3-8e07bd126614","focus":"panneau rond à droite avec « 50 m »","ref":"Art. 68.2 et 68.3 AR 01/12/1975"},{"id":"PHJ-016","theme":"autoroute","q":"Sur cette autoroute, la voiture rouge roule sur la bande de gauche. Si la bande à sa droite est libre devant elle et qu'elle ne dépasse personne, que doit faire son conducteur ?","choices":["Rester à gauche, c'est permis sur autoroute","Se rabattre sur la droite, car on doit se tenir le plus près possible du bord droit","Accélérer pour libérer la bande"],"answer":1,"explain":"Tout conducteur doit se tenir le plus près possible du bord droit de la chaussée. Sur autoroute, la bande de gauche sert au dépassement.","photo":"1c2e5ed2-5280-4528-9470-41fdba8a2c64","focus":"voiture rouge à gauche","ref":"Art. 9.3.1 et 16.6 AR 01/12/1975"},{"id":"PHJ-017","theme":"autoroute","q":"Plus loin, des balises de chantier ferment une bande de cette autoroute. Si la circulation devient fortement ralentie et que je suis sur la bande qui se termine, quand dois-je passer sur la bande libre ?","choices":["Le plus tôt possible, dès que je vois les balises","Juste devant le rétrécissement, chacun à son tour (tirette)","Jamais : je dois attendre que la bande soit rouverte"],"answer":1,"explain":"Quand la circulation est fortement ralentie, les conducteurs de la bande qui prend fin s'intercalent sur la bande libre seulement juste devant le rétrécissement. Ceux de la bande libre doivent les laisser passer tour à tour : c'est la tirette.","photo":"6b7dc621-8063-4563-93b5-3c0a0ce9f1ff","focus":"balises sur la droite","ref":"Art. 12bis AR 01/12/1975"},{"id":"PHJ-018","theme":"autoroute","q":"Plus loin, des balises de chantier ferment une bande de cette autoroute. La circulation est fluide et je suis sur la bande qui se termine. Pour passer sur la bande voisine, ai-je la priorité ?","choices":["Oui, la bande voisine doit me laisser passer","Non, changer de bande est une manœuvre : je dois céder le passage","Oui, si j'ai mis mon clignotant"],"answer":1,"explain":"Changer de bande est une manœuvre : le conducteur doit céder le passage aux autres usagers. La règle de la tirette ne s'applique que lorsque la circulation est fortement ralentie.","photo":"6b7dc621-8063-4563-93b5-3c0a0ce9f1ff","focus":"balises sur la droite","ref":"Art. 12.4 et 12bis AR 01/12/1975"},{"id":"PHJ-019","theme":"autoroute","q":"Je roule sur la bande de gauche de cette autoroute, le long du terre-plein central. Je me rends compte que je vais dans la mauvaise direction. Puis-je faire demi-tour par un passage dans le terre-plein central ?","choices":["Non, il est interdit de faire demi-tour et d'emprunter les raccordements transversaux sur autoroute","Oui, si aucune voiture n'arrive","Oui, avec mes feux de détresse allumés"],"answer":0,"explain":"Sur autoroute, il est interdit de faire demi-tour, de faire marche arrière et d'emprunter les raccordements transversaux. Il faut sortir à la prochaine sortie.","grave":true,"photo":"dbb3f112-bab7-4f43-8694-6e38d3c060af","focus":"terre-plein central à gauche","ref":"Art. 21.4 AR 01/12/1975"},{"id":"PHJ-020","theme":"usagers","q":"Sur cette route de campagne étroite, sans marquage au sol, où dois-je circuler avec ma voiture ?","choices":["Au milieu, pour mieux voir dans le virage","Le plus près possible du bord droit de la chaussée","Où je veux, puisqu'il n'y a pas de marquage"],"answer":1,"explain":"Tout conducteur circulant sur la chaussée doit se tenir le plus près possible du bord droit, surtout dans un virage où la visibilité est réduite.","photo":"262b110d-77f4-4774-9a7e-9c8574622d27","focus":"route étroite dans le virage","ref":"Art. 9.3.1 AR 01/12/1975"},{"id":"PHK-001","theme":"signalisation","q":"Sur l'îlot devant moi, un panneau rond bleu montre une flèche blanche droite, oblique, pointant vers le bas et la gauche. Que dois-je faire ?","choices":["Passer à droite de l'îlot","Passer à gauche de l'îlot","Tourner à gauche au prochain carrefour"],"answer":1,"explain":"C'est un signal D1 : placé sur un obstacle avec une flèche non coudée, il oblige à passer du côté indiqué par la flèche, ici à gauche de l'îlot.","photo":"b669ca8c-a150-4634-a812-f1465480454a","focus":"panneau bleu sur l'îlot, à droite","ref":"Art. 69.3 (D1) AR 01/12/1975"},{"id":"PHK-002","theme":"signalisation","q":"À droite du chantier, un panneau triangulaire à bord rouge montre un ouvrier qui pellette. Que m'annonce-t-il ?","choices":["Une sortie de camions","Un passage pour piétons","Des travaux"],"answer":2,"explain":"Le signal de danger A31 annonce des travaux. J'adapte ma vitesse et je reste attentif aux ouvriers, aux engins et aux changements de tracé.","photo":"bf87f03d-747f-4052-8e06-66c5edc56ae7","focus":"panneau triangulaire au-dessus du « 30 », à droite","ref":"Art. 66.4 (A31) AR 01/12/1975"},{"id":"PHK-003","theme":"vitesse","q":"Le panneau rond à bord rouge portant « 30 » est fixé sur la barrière du chantier. Si aucun autre signal ne la fait cesser avant, jusqu'où vaut cette limitation ?","choices":["Jusqu'au prochain carrefour inclus","Sur 150 mètres seulement","Jusqu'à la fin de l'agglomération, quoi qu'il arrive"],"answer":0,"explain":"Le signal C43 vaut à partir du signal jusqu'au prochain carrefour inclus. Il cesse aussi plus tôt si un autre signal C43 ou un signal de début ou de fin d'agglomération (ou de zone) est placé avant.","photo":"bf87f03d-747f-4052-8e06-66c5edc56ae7","focus":"panneau « 30 » sur la barrière à droite","ref":"Art. 68.3 (C43) AR 01/12/1975"},{"id":"PHK-004","theme":"stationnement","q":"De chaque côté de la rue, une large ligne blanche continue est tracée sur la chaussée et les voitures sont garées au-delà. Que signifie ce marquage ?","choices":["Il délimite des pistes cyclables","Il marque le bord de la chaussée : la partie située au-delà est réservée à l'arrêt et au stationnement","Il interdit le stationnement le long de la ligne"],"answer":1,"explain":"Une large ligne blanche continue tracée sur la chaussée en marque le bord fictif. La partie de la voie publique située au-delà est réservée à l'arrêt et au stationnement (sauf sur autoroute et route pour automobiles).","photo":"65fd35a7-9865-4125-bbff-269c91cd025a","focus":"lignes blanches le long des voitures garées","ref":"Art. 75.2 AR 01/12/1975"},{"id":"PHK-005","theme":"stationnement","q":"Je veux me garer dans la bande de stationnement de droite, entre deux voitures. Quelle distance minimale dois-je laisser devant et derrière les autres véhicules ?","choices":["50 centimètres","2 mètres","1 mètre"],"answer":2,"explain":"Il est interdit de stationner à moins de 1 mètre devant ou derrière un autre véhicule à l'arrêt ou en stationnement, ou à un endroit où l'on empêcherait un autre véhicule d'accéder ou de se dégager.","photo":"65fd35a7-9865-4125-bbff-269c91cd025a","focus":"voitures garées à droite","ref":"Art. 25.1.1° AR 01/12/1975"},{"id":"PHK-006","theme":"usagers","q":"Je roule en agglomération derrière ces deux cyclistes. Une fois le carrefour franchi, je veux les dépasser. Quelle distance latérale minimale dois-je laisser entre ma voiture et un cycliste ?","choices":["1 mètre","50 centimètres","2 mètres"],"answer":0,"explain":"Le conducteur doit laisser au moins 1 mètre de distance latérale en dépassant un cycliste en agglomération, et au moins 1,5 mètre hors agglomération. Si ce n'est pas possible, il attend pour dépasser.","photo":"b812cc72-22e1-4831-b3c8-d2c954858c84","focus":"cyclistes devant","ref":"Art. 40ter AR 01/12/1975"},{"id":"PHK-007","theme":"depassement","q":"Une ligne blanche continue sépare les deux sens de circulation dans ce virage. Si un véhicule lent me précédait, pourrais-je franchir cette ligne pour le dépasser ?","choices":["Oui, si je vois que personne n'arrive en face","Non, il est interdit de franchir une ligne continue","Oui, à condition de ne pas dépasser 50 km/h"],"answer":1,"explain":"Une ligne blanche continue ne peut pas être franchie, et il est interdit de circuler à sa gauche lorsqu'elle sépare les deux sens. Dans un virage, la visibilité réduite rend en plus ce dépassement dangereux.","grave":true,"photo":"e848acf1-87d0-45d0-90fb-37237b9790da","focus":"ligne continue au milieu de la chaussée","ref":"Art. 72.2 AR 01/12/1975"},{"id":"PHK-008","theme":"priorite","q":"Le feu à droite, au bout du passage pour piétons, est vert pour moi. Si la file de voitures était arrêtée juste après le carrefour, de sorte que je risque d'y rester bloqué, pourrais-je m'y engager ?","choices":["Oui, le feu vert m'autorise à passer","Oui, à condition d'allumer mes feux de détresse","Non, je ne peux pas m'engager si je risque d'y être immobilisé et de gêner la circulation transversale"],"answer":2,"explain":"Même si le feu l'y autorise, un conducteur ne peut pas s'engager dans un carrefour si les embouteillages risquent de l'y immobiliser et de gêner ou bloquer la circulation venant des autres directions.","photo":"f200da77-578b-4f54-94b6-7c392eeebab6","focus":"feu vert à droite","ref":"Art. 14.2 AR 01/12/1975"},{"id":"PHK-009","theme":"signalisation","q":"Il n'y a pas de ligne d'arrêt devant ce passage pour piétons, situé avant le feu. Si le feu passe au rouge à mon approche, où dois-je arrêter ma voiture ?","choices":["Sur le passage pour piétons, à hauteur du feu","Avant le passage pour piétons","Juste après le feu"],"answer":1,"explain":"Quand la circulation est fermée dans mon sens et qu'il existe un passage pour piétons à cet endroit, je dois de toute manière m'arrêter avant ce passage, pour le laisser libre.","grave":true,"photo":"f200da77-578b-4f54-94b6-7c392eeebab6","focus":"passage pour piétons et feu à droite","ref":"Art. 40.4.1 AR 01/12/1975"},{"id":"PHK-010","theme":"stationnement","q":"Un panneau rond bleu bordé de rouge et barré (interdiction de stationnement) est placé sur le trottoir de gauche. Où s'applique cette interdiction ?","choices":["Des deux côtés de la rue, sur toute sa longueur","Uniquement sur le trottoir","Du côté de la voie publique où il est placé, du panneau jusqu'au prochain carrefour"],"answer":2,"explain":"Les signaux E1 et E3 n'ont effet que du côté de la voie publique où ils sont placés, à partir du signal jusqu'au prochain carrefour. Ils valent sur la chaussée et sur l'accotement.","photo":"094d3ec0-163f-4099-8fdb-0cce82f6ac55","focus":"panneau rond à gauche","ref":"Art. 70.2.2 AR 01/12/1975"},{"id":"PHK-011","theme":"stationnement","q":"Le panneau carré bleu à flèche blanche vers le haut, à droite, indique que je suis dans une rue à sens unique. Sauf signal contraire, de quel côté de la chaussée puis-je garer ma voiture ?","choices":["À droite ou à gauche","Uniquement à droite","Uniquement à gauche"],"answer":0,"explain":"En principe, on range son véhicule à droite par rapport au sens de marche. Sur une chaussée à sens unique, on peut toutefois le ranger d'un côté ou de l'autre.","photo":"2723c985-09c7-464e-b4e1-0e637e773926","focus":"panneau bleu à droite","ref":"Art. 23.1.1° AR 01/12/1975"},{"id":"PHK-012","theme":"usagers","q":"Devant moi se trouve un passage pour piétons. Si la circulation était si dense que je risquais de rester arrêté dessus, pourrais-je m'y engager ?","choices":["Oui, si aucun piéton n'attend","Non, j'attends de pouvoir le franchir entièrement","Oui, si j'allume mes feux de détresse"],"answer":1,"explain":"Le conducteur ne peut pas s'engager sur un passage pour piétons si les embouteillages risquent de l'y immobiliser : il bloquerait la traversée des piétons.","photo":"2723c985-09c7-464e-b4e1-0e637e773926","focus":"passage pour piétons au premier plan","ref":"Art. 40.5 AR 01/12/1975"},{"id":"PHK-013","theme":"usagers","q":"Un piéton est engagé sur ce passage pour piétons, qui n'est réglé ni par des feux ni par un agent. Que dois-je faire en arrivant ?","choices":["Klaxonner et passer derrière lui","Continuer : il doit attendre que la voie soit libre","Lui céder le passage et m'arrêter au besoin"],"answer":2,"explain":"À un passage pour piétons qui n'est pas réglé par des feux ou un agent, je m'approche à allure modérée et je dois céder le passage aux piétons engagés ou sur le point de s'engager.","grave":true,"photo":"aef5f971-abbd-4b2d-92a2-e46c58d3d49d","focus":"piéton sur le passage","ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"PHK-014","theme":"priorite","q":"Le panneau triangulaire montre une croix noire. Au carrefour qu'il annonce, si un cycliste arrive de la rue à ma droite, qui passe en premier ?","choices":["Le cycliste, car la priorité de droite vaut pour tous les conducteurs","Moi, car un cycliste doit céder le passage aux voitures","Moi, car je circule sur la rue la plus large"],"answer":0,"explain":"Le signal B17 annonce un carrefour où la priorité de droite s'applique. Je dois céder le passage à tout conducteur venant de ma droite, cycliste compris.","grave":true,"photo":"c6c530cf-fbc5-4d81-86b8-dfe62bfa4169","focus":"panneau triangulaire à droite","ref":"Art. 67.3 (B17) et 12.3.1 AR 01/12/1975"},{"id":"PHK-015","theme":"usagers","q":"Un triangle avec deux enfants est peint sur la chaussée : il reprend le symbole d'un signal de danger. Que m'annonce-t-il ?","choices":["Une aire de jeux interdite aux voitures","Un endroit spécialement fréquenté par des enfants : je redouble de prudence","Un passage pour piétons réglé par un surveillant"],"answer":1,"explain":"Le symbole est celui du signal A23 : endroit spécialement fréquenté par des enfants. En présence d'enfants, je dois redoubler de prudence, ralentir et au besoin m'arrêter.","photo":"04775d20-bbf2-4402-8e0d-df8eddce59ff","focus":"marquage triangulaire au sol","ref":"Art. 66.4 (A23) et 40.2 AR 01/12/1975"},{"id":"PHK-016","theme":"priorite","q":"Le panneau triangulaire à droite (croix noire) annonce un carrefour. Si une voiture arrive de ma gauche dans ce carrefour, qui doit céder le passage ?","choices":["Moi","La voiture venant de ma gauche","Personne : le premier arrivé passe"],"answer":1,"explain":"Le signal B17 annonce un carrefour où la priorité de droite s'applique. La voiture venant de ma gauche m'a à sa droite : c'est elle qui doit me céder le passage. Je reste prudent en abordant le carrefour.","photo":"3efa01de-9559-453a-ab59-e96a8c8454da","focus":"panneau triangulaire à droite","ref":"Art. 67.3 (B17) et 12.3.1 AR 01/12/1975"},{"id":"PHK-017","theme":"securite","q":"J'entre dans ce rond-point, signalé par le triangle pointe en bas et le panneau bleu à flèches circulaires. Dans l'anneau, dois-je me tenir le plus près possible du bord droit ?","choices":["Oui, comme partout sur la chaussée","Non, je dois rouler au centre de l'anneau","Non, je n'y suis pas tenu, mais je respecte les bandes marquées éventuelles"],"answer":2,"explain":"Sauf partie réservée, le conducteur n'est pas tenu de serrer le bord droit dans l'anneau d'un rond-point. S'il y a des bandes marquées, il les respecte et prend celle qui convient le mieux à sa destination.","photo":"427947e3-01ac-4972-aa37-cba9a2a57bfa","focus":"panneaux B1 et D5 à droite","ref":"Art. 9.3.1 AR 01/12/1975"},{"id":"PHK-018","theme":"signalisation","q":"La ligne blanche continue sépare ma bande de celle des véhicules venant en sens inverse. Puis-je la franchir pour faire demi-tour ?","choices":["Non, il est interdit de franchir une ligne continue","Oui, si la voie est libre dans les deux sens","Oui, mais seulement en agglomération"],"answer":0,"explain":"Il est interdit à tout conducteur de franchir une ligne blanche continue, quelle que soit la manœuvre (dépassement, demi-tour, virage à gauche).","photo":"81626dcd-9308-4287-8ecc-972395de954c","focus":"ligne continue à gauche de ma bande","ref":"Art. 72.2 AR 01/12/1975"},{"id":"PHK-019","theme":"usagers","q":"Je roule en agglomération dans le même sens que ce bus arrêté à droite. S'il actionne ses clignotants pour quitter son arrêt, que dois-je faire ?","choices":["Accélérer pour passer avant lui","Le laisser quitter son arrêt en ralentissant et, au besoin, en m'arrêtant","Klaxonner pour lui signaler ma présence"],"answer":1,"explain":"En agglomération, je dois permettre à l'autobus de quitter son point d'arrêt lorsqu'il l'indique avec ses clignotants : je ralentis et, au besoin, je m'arrête.","photo":"d0fd80e9-9862-445d-8769-246ce58986cd","focus":"bus jaune à droite","ref":"Art. 39 AR 01/12/1975"},{"id":"PHK-020","theme":"usagers","q":"Ces piétons marchent sur la chaussée devant moi, dans cette rue de Liège (en agglomération). Je veux les dépasser. Quelle règle dois-je respecter ?","choices":["Laisser au moins 50 cm et klaxonner","Laisser au moins 1 mètre ; si c'est impossible, rouler à l'allure du pas et au besoin m'arrêter","Laisser au moins 3 mètres, sinon il m'est interdit d'avancer"],"answer":1,"explain":"Je dois laisser au moins 1 mètre entre ma voiture et un piéton qui circule sur la chaussée (1,5 mètre hors agglomération). Si cette distance ne peut pas être respectée, je roule à l'allure du pas et je m'arrête au besoin.","grave":true,"photo":"ddfdd8d6-c515-4c90-8d92-9990a8bd3535","focus":"piétons sur la chaussée","ref":"Art. 40.7 AR 01/12/1975"},{"id":"PHL-001","theme":"signalisation","q":"Je circule dans cette rue de Tubize (Wallonie). Que m'annonce le panneau triangulaire montrant un ouvrier avec une pelle, placé au-dessus du « 30 » ?","choices":["Un endroit fréquenté par des enfants","Des travaux sur la voie publique","La fin d'un chantier"],"answer":1,"explain":"Le signal de danger A31 (silhouette d'un ouvrier au travail) annonce des travaux. Je dois redoubler de prudence et adapter ma vitesse.","photo":"84289201-1a23-49fb-b71b-6075aae743c8","focus":"panneau triangulaire à droite","ref":"Art. 66.4 (A31) AR 01/12/1975"},{"id":"PHL-002","theme":"vitesse","q":"Je dépasse le panneau rond « 30 » placé à droite, sans mention « ZONE ». Jusqu'où cette limitation s'applique-t-elle (sauf autre signal de vitesse, d'agglomération ou de zone) ?","choices":["Jusqu'au prochain carrefour inclus","Sur une distance de 1 km","Jusqu'à la sortie de la commune"],"answer":0,"explain":"Le signal C43 interdit de dépasser la vitesse indiquée à partir du signal jusqu'au prochain carrefour inclus, ou jusqu'à un autre signal C43 ou un signal de début ou de fin d'agglomération ou de zone.","photo":"84289201-1a23-49fb-b71b-6075aae743c8","focus":"panneau rond « 30 » à droite","ref":"Art. 68.3 (C43) AR 01/12/1975"},{"id":"PHL-003","theme":"vitesse","q":"À droite, le panneau rectangulaire blanc porte la mention « ZONE » au-dessus d'un panneau rond « 30 ». Jusqu'où dois-je respecter cette limite de 30 km/h ?","choices":["Jusqu'au prochain carrefour seulement","Jusqu'au panneau qui indique la fin de cette zone","Uniquement aux heures d'entrée et de sortie des écoles"],"answer":1,"explain":"Un signal C43 à validité zonale (mention « ZONE ») s'applique dans toute la zone : de ce signal jusqu'au signal de fin de zone, et non seulement jusqu'au prochain carrefour.","photo":"4d68d95a-6dea-472a-9533-6befd70395ce","focus":"panneau « ZONE 30 » à droite","ref":"Art. 65.5.10 (Région wallonne) AR 01/12/1975"},{"id":"PHL-004","theme":"priorite","q":"Après le passage pour piétons, un panneau triangulaire blanc bordé de rouge, pointe vers le bas, est placé à droite avant le carrefour. À qui dois-je céder le passage ?","choices":["Seulement aux conducteurs venant de ma droite","À tous les conducteurs circulant sur la voie que j'aborde, quelle que soit leur direction","À personne : j'ai la priorité car je roule tout droit"],"answer":1,"explain":"Le signal B1 m'oblige à céder le passage à tout conducteur circulant sur la voie publique ou la chaussée que j'aborde, qu'il vienne de gauche ou de droite.","grave":true,"photo":"cdd9a2ac-45b4-40be-8661-ca0a54dffc73","focus":"triangle pointe en bas à droite","ref":"Art. 12.3.1 a) AR 01/12/1975"},{"id":"PHL-005","theme":"signalisation","q":"Que signifie le panneau carré bleu, à droite, montrant un piéton sur des bandes dans un triangle blanc ?","choices":["Il indique l'emplacement d'un passage pour piétons","Il annonce un danger : passage pour piétons à environ 150 m","Il interdit l'accès aux piétons"],"answer":0,"explain":"Le signal F49 (carré bleu) indique l'endroit même d'un passage pour piétons. Le signal de danger A21, triangulaire, l'annonce à l'avance.","photo":"cdd9a2ac-45b4-40be-8661-ca0a54dffc73","focus":"panneau carré bleu à droite","ref":"Art. 71 (F49) et Art. 66.4 (A21) AR 01/12/1975"},{"id":"PHL-006","theme":"signalisation","q":"La rue est fermée par des barrières pour un marché. Sur l'une d'elles est fixé un panneau rond blanc bordé de rouge, sans symbole. Puis-je entrer avec ma voiture dans la partie fermée ?","choices":["Oui, au pas, en faisant attention aux piétons","Oui, si je suis riverain","Non, l'accès y est interdit à tout conducteur, dans les deux sens"],"answer":2,"explain":"Le signal C3 signifie accès interdit, dans les deux sens, à tout conducteur. Sans panneau additionnel prévoyant une exception, personne ne peut y entrer avec un véhicule.","photo":"2996d606-76df-465d-a904-eb4dd9281763","focus":"panneau rond blanc sur la barrière","ref":"Art. 68.3 (C3) AR 01/12/1975"},{"id":"PHL-007","theme":"signalisation","q":"Le feu au-dessus de ma bande est rouge. Je veux tourner à droite et personne ne semble venir. Aucune flèche verte n'est allumée. Puis-je tourner ?","choices":["Non, je dois rester à l'arrêt avant la ligne d'arrêt tant que le feu est rouge","Oui, après un arrêt complet, si la voie est libre","Oui, car le feu rouge ne concerne que ceux qui vont tout droit"],"answer":0,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt (ou, à défaut, le signal), quelle que soit la direction. Seule une flèche verte supplémentaire allumée autorise un mouvement dans la direction indiquée.","grave":true,"photo":"c485a029-cddd-4ccc-98cc-a0119a86177d","focus":"feu sur la potence","ref":"Art. 61.1, 1° et 5° AR 01/12/1975"},{"id":"PHL-008","theme":"signalisation","q":"Que m'annonce le panneau triangulaire montrant deux enfants, fixé sur le poteau à droite ?","choices":["Un passage pour piétons","Une aire de jeux interdite aux véhicules","Un endroit spécialement fréquenté par des enfants"],"answer":2,"explain":"Le signal A23 annonce un endroit spécialement fréquenté par des enfants (école, plaine de jeux…). En présence d'enfants, je dois redoubler de prudence, ralentir et au besoin m'arrêter.","photo":"ce2b792c-eb31-4140-92f5-951162e80f5f","focus":"panneau triangulaire à droite","ref":"Art. 66.4 (A23) et Art. 40.2 AR 01/12/1975"},{"id":"PHL-009","theme":"signalisation","q":"Le panneau triangulaire à droite, avec un point d'exclamation, est complété par un panneau additionnel « RALENTISSEUR ». Que signifie cet ensemble ?","choices":["Un danger signalé : un ralentisseur sur la chaussée, je dois adapter ma vitesse","La fin d'une zone 30","Une interdiction de dépasser les cyclistes"],"answer":0,"explain":"Le signal A51 annonce un danger non défini par un symbole spécial ; un panneau additionnel en indique la nature, ici un ralentisseur.","photo":"dbe7719e-a4c7-448f-b7da-074f5b629f1f","focus":"panneau triangulaire à droite","ref":"Art. 66.4 (A51) AR 01/12/1975"},{"id":"PHL-010","theme":"usagers","q":"Ces deux cyclistes roulent côte à côte sur la chaussée devant moi. Je suis en agglomération et le croisement avec les véhicules venant en sens inverse reste possible. Est-ce permis ?","choices":["Non, les cyclistes doivent toujours rouler l'un derrière l'autre","Oui, les cyclistes peuvent rouler à deux de front sauf lorsque le croisement n'est pas possible","Oui, mais seulement s'ils sont plus de quinze"],"answer":1,"explain":"Les cyclistes circulant sur la chaussée peuvent rouler à deux de front, sauf lorsque le croisement n'est pas possible. Hors agglomération, ils doivent en outre se mettre en file à l'approche d'un véhicule venant de l'arrière.","photo":"f25e0806-9669-4417-87b3-c38c24d37e6e","focus":"cyclistes devant moi","ref":"Art. 43.2 AR 01/12/1975"},{"id":"PHL-011","theme":"depassement","q":"Je veux dépasser ces cyclistes, en agglomération. Quelle distance latérale minimale dois-je laisser entre ma voiture et eux ?","choices":["50 centimètres","1 mètre","2 mètres"],"answer":1,"explain":"En dépassant un cycliste, le conducteur doit laisser une distance latérale d'au moins 1 mètre ; hors agglomération, au moins 1,5 mètre. Il doit redoubler de prudence en présence d'enfants cyclistes.","grave":true,"photo":"f25e0806-9669-4417-87b3-c38c24d37e6e","focus":"cyclistes devant moi","ref":"Art. 40ter AR 01/12/1975"},{"id":"PHL-012","theme":"stationnement","q":"À droite, un panneau blanc « ZONE » montre un « P » bleu et le symbole d'un disque de stationnement. J'y stationne un jour ouvrable à 10 h, sans autre indication. Combien de temps puis-je rester ?","choices":["Sans limite, le stationnement est gratuit","Au maximum 2 heures, avec le disque de stationnement apposé derrière le pare-brise","Au maximum 15 minutes, feux de détresse allumés"],"answer":1,"explain":"J'entre dans une zone bleue (stationnement à durée limitée). Sauf modalités particulières indiquées, le disque est obligatoire de 9 h à 18 h les jours ouvrables, pour une durée maximale de deux heures.","photo":"09583fdd-4ca5-42ef-a8cb-b8939de760a8","focus":"panneau « ZONE P » à droite","ref":"Art. 27.1.1 et 27.1.2 AR 01/12/1975"},{"id":"PHL-013","theme":"stationnement","q":"Dans cette zone bleue, j'arrive à 10 h 10. Sur quelle position dois-je placer la flèche de mon disque de stationnement ?","choices":["Sur le trait qui suit l'heure de mon arrivée (10 h 30)","Sur l'heure à laquelle je compte repartir","Sur 10 h 00, l'heure pleine précédant mon arrivée"],"answer":0,"explain":"Le conducteur doit positionner la flèche du disque sur le trait qui suit celui du moment de son arrivée. Il est interdit d'y faire apparaître des indications inexactes.","photo":"09583fdd-4ca5-42ef-a8cb-b8939de760a8","focus":"panneau « ZONE P » à droite","ref":"Art. 27.1.2 et 27.1.3 AR 01/12/1975"},{"id":"PHL-014","theme":"priorite","q":"Je vais entrer dans ce carrefour giratoire : un panneau bleu rond à flèches circulaires est placé sur l'îlot central et un triangle pointe en bas à droite. Si un véhicule circule déjà sur l'anneau, qui a la priorité ?","choices":["Moi, car il vient de ma gauche","Le véhicule qui circule sur l'anneau","Celui qui roule le plus vite"],"answer":1,"explain":"Avec le signal D5 sur l'îlot et un signal B1 sur la voie d'accès, il s'agit d'un rond-point. Celui qui y entre doit céder le passage aux conducteurs qui circulent sur l'anneau ; la priorité de droite ne s'applique pas à ceux qui circulent dans le rond-point.","grave":true,"photo":"75aa5c2e-13c0-4b88-8860-e4b18458b7ea","focus":"îlot central et triangle à droite","ref":"Art. 2.39 et Art. 12.3.1 AR 01/12/1975"},{"id":"PHL-015","theme":"priorite","q":"Une fois dans l'anneau de ce rond-point (sans bandes marquées), suis-je obligé de me tenir le plus près possible du bord droit de la chaussée ?","choices":["Oui, comme partout ailleurs","Oui, sauf si je sors à la première sortie","Non, je n'y suis pas tenu dans l'anneau d'un rond-point"],"answer":2,"explain":"Le conducteur n'est pas tenu de se tenir le plus près possible du bord droit de la chaussée dans l'anneau d'un rond-point, sauf si une partie lui est réservée. S'il y a des bandes marquées, il peut emprunter celle qui convient le mieux à sa destination.","photo":"75aa5c2e-13c0-4b88-8860-e4b18458b7ea","focus":"carrefour giratoire au fond","ref":"Art. 9.3.1 AR 01/12/1975"},{"id":"PHL-016","theme":"signalisation","q":"Que m'annonce le panneau triangulaire montrant deux flèches verticales de sens opposé, placé à droite ?","choices":["Une circulation dans les deux sens après une section à sens unique","Une route prioritaire","Une obligation de rouler sur deux files"],"answer":0,"explain":"Le signal A39 annonce que la circulation est admise dans les deux sens après une section de chaussée à sens unique : je dois m'attendre à croiser des véhicules venant en face.","photo":"e3cadd8d-ad4a-4b04-af53-6b9759d90732","focus":"panneau triangulaire à droite","ref":"Art. 66.4 (A39) AR 01/12/1975"},{"id":"PHL-017","theme":"stationnement","q":"Le panneau carré bleu à droite (flèche blanche vers le haut) indique que la rue dans laquelle je m'engage est à sens unique. De quel côté puis-je y stationner (sans autre signal) ?","choices":["Uniquement à droite","D'un côté ou de l'autre","Uniquement à gauche"],"answer":1,"explain":"Un véhicule à l'arrêt ou en stationnement doit en principe être rangé à droite, mais si la chaussée est à sens unique, il peut être rangé de l'un ou de l'autre côté.","photo":"b135ed9c-3ced-44f7-ac92-6170bd0eb455","focus":"panneau carré bleu à droite","ref":"Art. 23.1, 1° AR 01/12/1975"},{"id":"PHL-018","theme":"priorite","q":"Dans cette rue à sens unique (panneau carré bleu à flèche blanche à droite), je veux tourner à gauche au prochain carrefour. Comment dois-je me placer ?","choices":["Serrer le plus possible le bord droit de la chaussée","Rester au milieu de la chaussée","Serrer le plus possible le bord gauche de la chaussée"],"answer":2,"explain":"Le conducteur qui tourne à gauche doit, sur une chaussée à sens unique, serrer le plus possible le bord gauche de celle-ci, après avoir mis son clignotant gauche suffisamment à temps.","photo":"b135ed9c-3ced-44f7-ac92-6170bd0eb455","focus":"panneau carré bleu à droite","ref":"Art. 19.3, 1° et 2° b) AR 01/12/1975"},{"id":"PHL-019","theme":"usagers","q":"Un passage pour piétons se trouve juste devant moi. Si la file qui me précède s'arrête et que je risque de rester immobilisé sur le passage, puis-je m'y engager ?","choices":["Oui, si aucun piéton n'est en vue","Non, je dois attendre en deçà du passage","Oui, à condition d'allumer mes feux de détresse"],"answer":1,"explain":"Le conducteur ne peut s'engager sur un passage pour piétons si l'encombrement de la circulation est tel qu'il serait vraisemblablement immobilisé sur ce passage.","photo":"84e3a01a-58d3-4dc4-87a5-c53b3477dade","focus":"passage pour piétons devant moi","ref":"Art. 40.5 AR 01/12/1975"},{"id":"PHL-020","theme":"stationnement","q":"Le panneau rond bleu bordé de rouge, barré d'une seule diagonale, est placé sur le trottoir de droite, sans panneau additionnel. Où le stationnement est-il interdit ?","choices":["Des deux côtés de la rue, sur 100 mètres","Uniquement juste à hauteur du panneau","Du côté où le panneau est placé, à partir du panneau jusqu'au prochain carrefour"],"answer":2,"explain":"Le signal E1 interdit le stationnement. Il a effet du côté de la voie publique où il est placé, à partir du signal jusqu'au prochain carrefour.","photo":"de658213-976f-4720-9ca8-e7a3ad6421f6","focus":"panneau rond à droite","ref":"Art. 70.2.1 (E1) et 70.2.2 AR 01/12/1975"},{"id":"PRI-001","theme":"priorite","q":"J'arrive à un carrefour sans aucune signalisation. Une voiture arrive par ma droite. Que dois-je faire ?","choices":["Je passe, car je circule sur la route la plus large","Je lui cède le passage","Je passe si je roule plus vite qu'elle"],"answer":1,"explain":"En l'absence de signalisation, la règle générale est la priorité de droite : je dois céder le passage au conducteur qui vient de ma droite, quelle que soit la largeur de la route.","grave":true,"ref":"Art. 12.3.1 AR 01/12/1975"},{"id":"PRI-002","theme":"priorite","q":"À un carrefour sans signalisation, une voiture arrive par ma gauche et je continue tout droit. Qui a la priorité ?","choices":["Moi, car elle vient de ma gauche","Elle, car elle est arrivée la première"],"answer":0,"explain":"La priorité de droite joue en ma faveur : c'est le conducteur venant de gauche qui doit me céder le passage. Je reste toutefois prudent en abordant le carrefour.","ref":"Art. 12.2 et 12.3.1 AR 01/12/1975"},{"id":"PRI-003","theme":"priorite","q":"Je circule dans une rue à double sens. À un carrefour sans signalisation, une voiture débouche de ma droite… en sortant d'une rue à sens unique qu'elle a empruntée à contresens. Dois-je lui céder le passage ?","choices":["Non, celui qui vient d'un sens interdit ne bénéficie pas de la priorité de droite","Oui, la priorité de droite s'applique toujours"],"answer":0,"explain":"La priorité de droite ne s'applique pas au conducteur qui vient d'un sens interdit. Je reste néanmoins prudent pour éviter l'accident.","ref":"Art. 12.3.1 AR 01/12/1975"},{"id":"PRI-004","theme":"priorite","q":"Je sors d'un chemin de terre pour m'engager sur une route asphaltée. Une voiture arrive par ma gauche sur cette route. Que dois-je faire ?","choices":["Passer, car elle vient de ma gauche","Klaxonner pour signaler ma présence et passer","Lui céder le passage"],"answer":2,"explain":"Le conducteur qui débouche d'un chemin de terre ou d'un sentier sur une voie publique pourvue d'une chaussée doit céder le passage à tous les conducteurs, qu'ils viennent de droite ou de gauche.","grave":true,"ref":"Art. 12.3.1, al. 2, b) AR 01/12/1975"},{"id":"PRI-005","theme":"priorite","q":"Je quitte une place de stationnement le long du trottoir. Un cycliste arrive derrière moi sur la chaussée. Qui doit céder le passage ?","choices":["Moi, car quitter un emplacement de stationnement est une manœuvre","Le cycliste, car je suis déjà sur la chaussée"],"answer":0,"explain":"Quitter un emplacement de stationnement est une manœuvre. Le conducteur qui effectue une manœuvre doit céder le passage à tous les autres usagers.","ref":"Art. 12.4 AR 01/12/1975"},{"id":"PRI-006","theme":"priorite","q":"Je sors du parking privé d'un supermarché (propriété riveraine) pour m'engager dans la rue. Une voiture arrive par ma gauche dans cette rue. Que dois-je faire ?","choices":["Lui céder le passage","Passer, car la priorité de droite joue en ma faveur"],"answer":0,"explain":"Déboucher d'une propriété riveraine est une manœuvre : je dois céder le passage à tous les usagers circulant sur la voie publique, même ceux venant de gauche.","ref":"Art. 12.4 AR 01/12/1975"},{"id":"PRI-007","theme":"priorite","q":"Je sors de mon garage en marche arrière et je dois traverser le trottoir. Un piéton y circule. Que dois-je faire ?","choices":["Avertir le piéton au klaxon et continuer","Lui céder le passage","Continuer lentement, il doit s'écarter"],"answer":1,"explain":"Le conducteur qui traverse un trottoir doit céder le passage aux usagers qui y circulent régulièrement. La marche arrière est en plus une manœuvre qui oblige à céder le passage à tous.","grave":true,"ref":"Art. 12.4 et 12.4bis AR 01/12/1975"},{"id":"PRI-008","theme":"priorite","q":"Le conducteur d'une voiture qui fait un demi-tour sur la chaussée…","choices":["a la priorité, car il a annoncé sa manœuvre au clignotant","a la priorité sur les véhicules venant de sa gauche","doit céder le passage aux autres usagers"],"answer":2,"explain":"Le demi-tour est une manœuvre. Le clignotant annonce la manœuvre mais ne donne aucune priorité : il faut céder le passage aux autres usagers.","ref":"Art. 12.4 et 13 AR 01/12/1975"},{"id":"PRI-009","theme":"priorite","q":"J'aborde un carrefour où mon chemin est pourvu de ce signal. Une voiture arrive par ma gauche sur la route transversale. Que dois-je faire ?","choices":["Lui céder le passage","Passer, car elle vient de ma gauche"],"answer":0,"explain":"Le signal B1 (cédez le passage) m'oblige à céder le passage à tous les conducteurs circulant sur la voie que j'aborde, qu'ils viennent de droite ou de gauche.","grave":true,"sign":"B1","ref":"Art. 12.3.1, al. 2, a) et 67.3 AR 01/12/1975"},{"id":"PRI-010","theme":"priorite","q":"Je m'approche de ce signal. Aucun véhicule n'est en vue sur la route transversale et la visibilité est parfaite. Dois-je m'arrêter ?","choices":["Non, je peux passer à allure réduite","Seulement s'il fait nuit","Oui, je dois marquer l'arrêt complet"],"answer":2,"explain":"Le signal B5 (stop) signifie « marquer l'arrêt et céder le passage ». L'arrêt est obligatoire, même si aucun véhicule n'arrive.","grave":true,"sign":"B5","ref":"Art. 67.3 (B5) AR 01/12/1975"},{"id":"PRI-011","theme":"priorite","q":"Au signal stop, où dois-je marquer l'arrêt lorsqu'une ligne blanche continue est tracée en travers de ma bande ?","choices":["Au-delà de la ligne, là où je vois le mieux","À hauteur de cette ligne d'arrêt"],"answer":1,"explain":"La ligne d'arrêt (ligne blanche continue perpendiculaire au bord de la chaussée) indique l'endroit où le conducteur doit marquer l'arrêt imposé par un signal B5.","sign":"B5","ref":"Art. 76.1 AR 01/12/1975"},{"id":"PRI-012","theme":"priorite","q":"Que signifie une ligne transversale formée de triangles blancs peints sur la chaussée ?","choices":["L'endroit où je dois, s'il y a lieu, m'arrêter pour céder le passage (signal B1)","Un passage pour cyclistes","Un ralentisseur de vitesse"],"answer":0,"explain":"La ligne de triangles blancs indique l'endroit où les conducteurs doivent s'arrêter, si nécessaire, pour céder le passage en vertu d'un signal B1.","ref":"Art. 76.2 AR 01/12/1975"},{"id":"PRI-013","theme":"priorite","q":"Après avoir marqué l'arrêt au stop, je vois une voiture qui arrive assez vite de la gauche, à une distance que j'estime juste suffisante. Puis-je m'engager ?","choices":["Oui, j'ai fait mon arrêt, la priorité est rétablie","Seulement si je peux le faire sans risque d'accident, compte tenu de sa vitesse et de sa distance"],"answer":1,"explain":"Le conducteur qui doit céder le passage ne peut poursuivre sa marche que s'il peut le faire sans risque d'accident, compte tenu de la position, de la vitesse et de la distance des autres usagers.","sign":"B5","ref":"Art. 12.5 AR 01/12/1975"},{"id":"PRI-014","theme":"priorite","q":"Je circule sur une route pourvue de ce signal. À un carrefour, une voiture arrive par ma droite d'une rue pourvue d'un signal « cédez le passage ». Qui a la priorité ?","choices":["Moi","La voiture de droite"],"answer":0,"explain":"Le signal B9 indique une voie prioritaire. Le conducteur qui débouche d'une voie pourvue d'un signal B1 ou B5 doit céder le passage à ceux qui circulent sur la voie qu'il aborde.","sign":"B9","ref":"Art. 12.3.1 et 67.3 (B9) AR 01/12/1975"},{"id":"PRI-015","theme":"priorite","q":"Que signifie ce signal ?","choices":["Voie prioritaire","Priorité au prochain carrefour uniquement","Fin de voie prioritaire"],"answer":0,"explain":"Le signal B9 (losange jaune bordé de blanc) signale une voie prioritaire.","sign":"B9","ref":"Art. 67.3 AR 01/12/1975"},{"id":"PRI-016","theme":"priorite","q":"Je viens de passer ce signal. À un carrefour sans autre signalisation un peu plus loin, une voiture arrive par ma droite. Que dois-je faire ?","choices":["Lui céder le passage","Passer : je viens d'une voie prioritaire","Passer si je suis arrivé le premier"],"answer":0,"explain":"Le signal B11 marque la fin de la voie prioritaire. Sans autre signalisation, la règle générale de la priorité de droite s'applique à nouveau.","sign":"B11","ref":"Art. 12.3.1 et 67.3 (B11) AR 01/12/1975"},{"id":"PRI-017","theme":"priorite","q":"Que m'indique ce signal ?","choices":["J'ai la priorité au prochain carrefour","Je dois céder le passage au prochain carrefour","Je circule sur une voie prioritaire jusqu'au prochain signal B11"],"answer":0,"explain":"Le signal B15 (priorité de passage) indique que j'ai priorité au carrefour qui suit ; la barre horizontale peut représenter la disposition des lieux.","sign":"B15","ref":"Art. 67.3 (B15) AR 01/12/1975"},{"id":"PRI-018","theme":"priorite","q":"Ce signal annonce un carrefour. Une camionnette y arrive par ma droite. Que dois-je faire ?","choices":["Passer, car le signal m'annonce un danger","Céder le passage à la camionnette"],"answer":1,"explain":"Le signal B17 annonce un carrefour où la priorité de droite est applicable : je dois céder le passage à la camionnette qui vient de ma droite.","sign":"B17","ref":"Art. 12.3.1 et 67.3 (B17) AR 01/12/1975"},{"id":"PRI-019","theme":"priorite","q":"J'arrive à un passage étroit pourvu de ce signal. Une voiture s'y présente en sens inverse. Que dois-je faire ?","choices":["Lui céder le passage","M'engager le premier, car je suis plus proche"],"answer":0,"explain":"Le signal B19 impose de céder le passage aux conducteurs venant en sens opposé dans le passage étroit.","sign":"B19","ref":"Art. 67.3 (B19) AR 01/12/1975"},{"id":"PRI-020","theme":"priorite","q":"J'arrive à un passage étroit pourvu de ce signal. Une voiture se présente en sens inverse, à l'autre extrémité. Qui a la priorité ?","choices":["La voiture venant en sens inverse","Celui qui roule le plus vite","Moi"],"answer":2,"explain":"Le signal B21 donne la priorité de passage par rapport aux conducteurs venant en sens opposé. Je reste toutefois prudent si l'autre conducteur s'est déjà engagé.","sign":"B21","ref":"Art. 67.3 (B21) AR 01/12/1975"},{"id":"PRI-021","theme":"priorite","q":"Je circule dans l'anneau d'un rond-point signalé par le signal D5. Une voiture arrive par ma droite pour entrer dans le rond-point. Qui a la priorité ?","choices":["La voiture qui veut entrer, car elle vient de droite","Moi, car je circule dans le rond-point"],"answer":1,"explain":"La priorité de droite ne s'applique pas au conducteur qui circule dans un rond-point. Les voies d'accès d'un rond-point sont d'ailleurs pourvues d'un signal B1 ou B5.","sign":"D5","ref":"Art. 2.39 et 12.3.1 AR 01/12/1975"},{"id":"PRI-022","theme":"priorite","q":"J'entre dans un rond-point. Dois-je actionner mon clignotant ?","choices":["Oui, le clignotant droit","Oui, le clignotant gauche","Non, ce n'est pas exigé pour entrer"],"answer":2,"explain":"Entrer dans un rond-point est un changement de direction qui n'implique pas l'usage des indicateurs de direction.","ref":"Art. 19.2, 1° AR 01/12/1975"},{"id":"PRI-023","theme":"priorite","q":"Je vais quitter le rond-point à la prochaine sortie. Que dois-je faire ?","choices":["Mettre mon clignotant droit","Ne rien signaler, la sortie est évidente"],"answer":0,"explain":"Sortir d'un rond-point est un changement de direction qui implique l'usage des indicateurs de direction (ici, à droite).","ref":"Art. 19.2, 1° AR 01/12/1975"},{"id":"PRI-024","theme":"priorite","q":"Je veux entrer dans un rond-point. Une voiture y circule déjà et arrive par ma gauche. Que dois-je faire ?","choices":["Entrer, car elle vient de ma gauche","Lui céder le passage"],"answer":1,"explain":"Les voies d'accès d'un rond-point sont pourvues d'un signal B1 ou B5 : je dois céder le passage aux conducteurs qui circulent déjà dans l'anneau.","sign":"B1","ref":"Art. 2.39 et 12.3.1 AR 01/12/1975"},{"id":"PRI-025","theme":"priorite","q":"À un carrefour sans signalisation, un tram arrive par ma gauche alors que je veux continuer tout droit. Que dois-je faire ?","choices":["Passer, car j'ai la priorité de droite","Céder le passage au tram"],"answer":1,"explain":"Tout usager doit céder le passage aux véhicules sur rails, quel que soit le côté d'où ils viennent, et s'écarter de la voie ferrée dès que possible.","grave":true,"ref":"Art. 12.1 AR 01/12/1975"},{"id":"PRI-026","theme":"priorite","q":"Je roule sur des rails de tram intégrés à la chaussée et un tram s'approche derrière moi. Que dois-je faire ?","choices":["Rester sur les rails, le tram attendra","Accélérer pour garder de l'avance","M'écarter de la voie ferrée dès que possible"],"answer":2,"explain":"Tout usager doit céder le passage aux véhicules sur rails et, à cette fin, s'écarter de la voie ferrée dès que possible.","ref":"Art. 12.1 AR 01/12/1975"},{"id":"PRI-027","theme":"priorite","q":"J'entends la sirène (avertisseur sonore spécial) d'une ambulance qui approche derrière moi. Que dois-je faire ?","choices":["Dégager immédiatement et lui céder le passage, au besoin m'arrêter","Continuer normalement, elle me dépassera","Accélérer pour rester devant elle"],"answer":0,"explain":"Dès que l'approche d'un véhicule prioritaire est signalée par l'avertisseur sonore spécial, tout usager doit immédiatement dégager et céder le passage ; au besoin, il doit s'arrêter.","grave":true,"ref":"Art. 38 AR 01/12/1975"},{"id":"PRI-028","theme":"priorite","q":"Un véhicule de pompiers utilisant son avertisseur sonore spécial arrive à un feu rouge. Peut-il le franchir ?","choices":["Non, jamais","Oui, à vitesse modérée et sans mettre en danger les autres usagers"],"answer":1,"explain":"Lorsque la circulation est réglée par des feux, le véhicule prioritaire utilisant l'avertisseur sonore spécial peut franchir le feu rouge à vitesse modérée, à condition qu'il n'en résulte pas de danger.","sign":"FEU-rouge","ref":"Art. 37.4 AR 01/12/1975"},{"id":"PRI-029","theme":"priorite","q":"Selon l'article 38 du code de la route, l'obligation de dégager immédiatement et de céder le passage à un véhicule prioritaire naît…","choices":["dès que son approche est signalée par l'avertisseur sonore spécial","dès que je vois un véhicule de police, même sans signaux"],"answer":0,"explain":"L'article 38 vise l'approche signalée par l'avertisseur sonore spécial (sirène). Un véhicule prioritaire avec feux bleus seuls mérite cependant une prudence accrue.","ref":"Art. 37 et 38 AR 01/12/1975"},{"id":"PRI-030","theme":"priorite","q":"Le feu est vert pour moi, mais la file de voitures devant moi est bloquée au milieu du carrefour. Puis-je m'engager ?","choices":["Oui, le feu est vert","Non, si je risque d'être immobilisé dans le carrefour","Oui, à condition d'actionner mes feux de détresse"],"answer":1,"explain":"Même si les feux l'y autorisent, un conducteur ne peut s'engager dans un carrefour si l'encombrement est tel qu'il y serait vraisemblablement immobilisé, gênant la circulation transversale.","sign":"FEU-vert","ref":"Art. 14.2 AR 01/12/1975"},{"id":"PRI-031","theme":"priorite","q":"Je tourne à gauche à un carrefour. Une voiture arrive en sens inverse et va tout droit. Que dois-je faire ?","choices":["Lui céder le passage","Tourner, car j'ai mis mon clignotant à temps"],"answer":0,"explain":"Le conducteur qui tourne à gauche doit céder le passage aux conducteurs venant en sens inverse sur la chaussée qu'il s'apprête à quitter.","grave":true,"ref":"Art. 19.3, 3° AR 01/12/1975"},{"id":"PRI-032","theme":"priorite","q":"Je tourne à droite. Un cycliste circule tout droit sur la piste cyclable longeant ma chaussée, à ma droite. Que dois-je faire ?","choices":["Tourner, car il est sur une piste séparée","Lui céder le passage"],"answer":1,"explain":"Le conducteur qui change de direction doit céder le passage aux conducteurs et piétons circulant sur les autres parties de la même voie publique, comme la piste cyclable.","grave":true,"ref":"Art. 19.4 AR 01/12/1975"},{"id":"PRI-033","theme":"priorite","q":"Je tourne dans une rue où des piétons sont en train de traverser la chaussée. Que dois-je faire ?","choices":["Céder le passage aux piétons","Passer devant eux, ils doivent attendre","Les avertir au klaxon puis passer"],"answer":0,"explain":"Le conducteur qui change de direction doit céder le passage aux piétons qui traversent la chaussée sur laquelle il va s'engager.","grave":true,"ref":"Art. 19.5 AR 01/12/1975"},{"id":"PRI-034","theme":"priorite","q":"Un agent qualifié se tient au milieu du carrefour, le bras levé verticalement. Je suis déjà à l'intérieur du carrefour. Que dois-je faire ?","choices":["M'arrêter immédiatement là où je suis","Évacuer le carrefour"],"answer":1,"explain":"Le bras levé verticalement signifie arrêt pour tous les usagers, sauf pour ceux qui se trouvent déjà à l'intérieur du carrefour : ceux-ci doivent l'évacuer.","ref":"Art. 4.2, 1° AR 01/12/1975"},{"id":"PRI-035","theme":"priorite","q":"Un agent qualifié a les deux bras tendus horizontalement. J'arrive face à lui (ma direction coupe celle de ses bras). Que dois-je faire ?","choices":["Passer, ses bras m'indiquent la voie","Tourner à droite uniquement","M'arrêter"],"answer":2,"explain":"Le ou les bras tendus horizontalement signifient arrêt pour les usagers qui viennent de directions coupant celles indiquées par les bras.","ref":"Art. 4.2, 2° AR 01/12/1975"},{"id":"PRI-037","theme":"priorite","q":"À un carrefour, des feux tricolores fonctionnent normalement et un signal « cédez le passage » est placé sur ma route. Le feu est vert pour moi. Dois-je céder le passage aux véhicules de la route transversale ?","choices":["Oui, le signal B1 reste prioritaire","Non, quand les feux fonctionnent, le signal de priorité placé sur la même voie est sans effet"],"answer":1,"explain":"Le fonctionnement des feux rend sans effet les signaux de priorité placés sur la même voie (sauf feu orange clignotant). Je reste attentif aux piétons et aux véhicules qui dégagent le carrefour.","sign":"B1","ref":"Art. 6.3 AR 01/12/1975"},{"id":"PRI-038","theme":"priorite","q":"Le feu orange clignote à un carrefour où mon chemin est pourvu d'un signal « cédez le passage ». Que dois-je faire ?","choices":["Redoubler de prudence et respecter le signal B1 : céder le passage","Passer, le feu orange clignotant me donne la priorité"],"answer":0,"explain":"Le feu jaune-orange clignotant autorise à franchir le signal en redoublant de prudence, mais il ne modifie pas les règles de priorité : le signal B1 reste d'application.","grave":true,"sign":"FEU-orange-cligno","ref":"Art. 6.3 et 64.1 AR 01/12/1975"},{"id":"PRI-039","theme":"priorite","q":"Un signaleur habilité, lors d'une course cycliste, me présente un disque reproduisant le signal C3. Que dois-je faire ?","choices":["M'arrêter","Contourner prudemment le signaleur","Ralentir seulement"],"answer":0,"explain":"Les signaleurs habilités font usage d'un disque représentant le signal C3 pour arrêter la circulation ; les usagers doivent obéir à leurs indications.","sign":"C3","ref":"Art. 41.3.1 et 41.3.2 AR 01/12/1975"},{"id":"SEC-001","theme":"securite","q":"De nuit, hors agglomération, je roule avec mes feux de route. Une voiture arrive en sens inverse. Que dois-je faire ?","choices":["Garder mes feux de route jusqu'à ce qu'elle soit à ma hauteur","Éteindre tous mes feux un court instant","Passer en feux de croisement à une distance suffisante pour que l'autre conducteur puisse continuer sans danger"],"answer":2,"explain":"À l'approche d'un usager venant en sens inverse, les feux de route doivent être remplacés par les feux de croisement, à une distance suffisante pour qu'il puisse poursuivre sa route aisément et sans danger.","grave":true,"ref":"Art. 30.1.1° a) AR 01/12/1975"},{"id":"SEC-002","theme":"securite","q":"De nuit, je suis une autre voiture à environ 40 mètres sur une route non éclairée. Je n'ai pas l'intention de la dépasser. Puis-je utiliser mes feux de route ?","choices":["Non, je dois utiliser mes feux de croisement","Oui, la route n'est pas éclairée"],"answer":0,"explain":"Lorsqu'on suit un autre véhicule à moins de 50 mètres, les feux de route doivent être remplacés par les feux de croisement, sauf pendant un dépassement.","ref":"Art. 30.1.1° c) AR 01/12/1975"},{"id":"SEC-003","theme":"securite","q":"Dans quelles circonstances puis-je allumer mes feux de brouillard avant ?","choices":["En cas de brouillard, de chute de neige ou de forte pluie","Dès la tombée du jour","Chaque fois que la route est sinueuse"],"answer":0,"explain":"Les feux de brouillard avant ne peuvent être utilisés qu'en cas de brouillard, de chute de neige ou de forte pluie. Ils peuvent alors remplacer les feux de croisement ou de route, ou être allumés en même temps.","ref":"Art. 30.1.1° AR 01/12/1975"},{"id":"SEC-004","theme":"securite","q":"Il y a un épais brouillard : je ne vois qu'à 60 mètres environ. Ma voiture est équipée d'un feu de brouillard arrière. Que dit le code ?","choices":["Je peux l'allumer si je le souhaite","Je ne peux l'allumer que sur autoroute","Je dois l'allumer"],"answer":2,"explain":"Le feu de brouillard arrière doit être utilisé en cas de brouillard ou de chute de neige réduisant la visibilité à moins de 100 m environ, ainsi qu'en cas de forte pluie.","ref":"Art. 30.1.2° AR 01/12/1975"},{"id":"SEC-005","theme":"securite","q":"De nuit, par temps sec et clair, je trouve que les autres me voient mal. Puis-je allumer mon feu de brouillard arrière ?","choices":["Oui, pour être plus visible","Non, il ne peut être utilisé que par brouillard, chute de neige (visibilité < 100 m environ) ou forte pluie"],"answer":1,"explain":"En dehors du brouillard ou de la neige réduisant la visibilité à moins de 100 m environ et de la forte pluie, le feu de brouillard arrière est interdit : il éblouit les conducteurs qui suivent.","ref":"Art. 30.1.2° AR 01/12/1975"},{"id":"SEC-006","theme":"securite","q":"En plein jour, une averse réduit fortement la visibilité. À partir de quand dois-je allumer mes feux ?","choices":["Lorsque je ne vois plus distinctement jusqu'à environ 100 mètres","Lorsque je ne vois plus distinctement jusqu'à environ 200 mètres","Uniquement après la tombée du jour"],"answer":1,"explain":"Les feux doivent être allumés entre la tombée et le lever du jour, et en toute circonstance où l'on ne voit plus distinctement jusqu'à environ 200 mètres.","ref":"Art. 30 AR 01/12/1975"},{"id":"SEC-007","theme":"securite","q":"De nuit, je roule sur une route bien éclairée de façon continue : je vois distinctement à plus de 100 mètres. Quels feux avant dois-je utiliser ?","choices":["Les feux de croisement","Les feux de route","Les feux de brouillard avant"],"answer":0,"explain":"Lorsque l'éclairage de la chaussée est continu et suffisant pour voir distinctement jusqu'à environ 100 mètres, les feux de route doivent être remplacés par les feux de croisement.","ref":"Art. 30.1.1° d) AR 01/12/1975"},{"id":"SEC-008","theme":"securite","q":"De nuit, je roule en feux de route. Le conducteur qui vient en face allume et éteint rapidement ses feux de route plusieurs fois. Que signifie ce geste et que dois-je faire ?","choices":["Il est ébloui : je passe immédiatement en feux de croisement","Il me salue : je ne change rien","Il me signale un contrôle : je réponds par un appel de phares"],"answer":0,"explain":"Le conducteur qui allume et éteint rapidement ses feux de route fait comprendre qu'il est ébloui. Il faut alors passer en feux de croisement sans attendre.","ref":"Art. 30.1.1° a) AR 01/12/1975"},{"id":"SEC-009","theme":"securite","q":"De nuit, je stationne ma voiture hors agglomération, le long d'une route non éclairée. Comment dois-je la signaler ?","choices":["Avec les feux de détresse","Aucun feu n'est nécessaire en stationnement","Avec les feux de position à l'avant et les feux rouges à l'arrière"],"answer":2,"explain":"Un véhicule à moteur à l'arrêt ou en stationnement de nuit doit être signalé par un ou deux feux de position blancs ou jaunes à l'avant et un ou deux feux rouges à l'arrière.","ref":"Art. 31.1.1 AR 01/12/1975"},{"id":"SEC-010","theme":"securite","q":"De nuit, en agglomération, je stationne parallèlement à la chaussée dans une rue mal éclairée, sans remorque. Puis-je n'utiliser qu'un feu de stationnement ?","choices":["Oui, celui situé du côté du trottoir","Non, c'est interdit en agglomération","Oui, celui situé du côté de l'axe de la chaussée"],"answer":2,"explain":"En agglomération, un véhicule rangé parallèlement à l'axe de la chaussée et sans remorque peut être signalé par un feu de stationnement. Seul celui du côté de l'axe de la chaussée peut être utilisé.","ref":"Art. 31.1.1 3° AR 01/12/1975"},{"id":"SEC-011","theme":"securite","q":"De nuit, ma voiture est stationnée sous un réverbère : l'éclairage public permet de la voir distinctement à environ 100 mètres. Dois-je laisser mes feux de position allumés ?","choices":["Non, ce n'est pas obligatoire dans ce cas","Oui, toujours"],"answer":0,"explain":"Les feux prescrits à l'arrêt ou en stationnement (feux de position et feux rouges arrière, ou feu de stationnement) ne sont obligatoires que si l'éclairage public ne permet pas d'apercevoir distinctement le véhicule à environ 100 mètres.","ref":"Art. 31.2 AR 01/12/1975"},{"id":"SEC-012","theme":"securite","q":"En agglomération, je m'apprête à dépasser un cycliste. Puis-je utiliser mon klaxon pour le prévenir ?","choices":["Non, le klaxon n'est autorisé que pour éviter un accident","Oui, c'est même recommandé"],"answer":0,"explain":"L'avertisseur sonore n'est autorisé que pour éviter un accident et, hors agglomération seulement, pour avertir qu'on va dépasser. En agglomération, klaxonner pour annoncer un dépassement est interdit.","ref":"Art. 33.2 AR 01/12/1975"},{"id":"SEC-013","theme":"securite","q":"Hors agglomération, à 23 h, je veux avertir le conducteur qui me précède que je vais le dépasser. Comment dois-je faire ?","choices":["Par un bref coup d'avertisseur sonore","Avec mes feux de détresse","Par l'emploi court et alterné des feux de route et des feux de croisement"],"answer":2,"explain":"Entre la tombée et le lever du jour, sauf danger imminent, l'avertisseur sonore est remplacé par l'emploi court et alterné des feux de route et des feux de croisement.","ref":"Art. 33.3 AR 01/12/1975"},{"id":"SEC-014","theme":"securite","q":"Je croise un ami sur le trottoir. Puis-je donner un petit coup de klaxon pour le saluer ?","choices":["Oui, si le coup de klaxon est bref","Non"],"answer":1,"explain":"Les avertissements sonores ne sont autorisés que pour éviter un accident (et, hors agglomération, pour annoncer un dépassement). Klaxonner pour saluer est interdit.","ref":"Art. 33.2 AR 01/12/1975"},{"id":"SEC-015","theme":"securite","q":"Dans quelle situation puis-je utiliser mes feux de détresse (tous les clignotants en même temps) ?","choices":["Pour m'arrêter brièvement en double file","Pour remercier un conducteur qui m'a laissé passer","Pour signaler aux usagers qui me suivent un risque d'accident imminent, par exemple un bouchon soudain sur autoroute"],"answer":2,"explain":"Les feux de détresse ne peuvent être utilisés qu'en cas de panne ou de chargement tombé, par un bus scolaire qui embarque ou débarque des enfants, ou pour signaler un risque d'accident imminent.","ref":"Art. 32bis AR 01/12/1975"},{"id":"SEC-016","theme":"securite","q":"Je tombe en panne sur l'autoroute et je ne peux pas quitter la bande d'arrêt d'urgence. À quelle distance minimale derrière mon véhicule dois-je placer le triangle de danger ?","choices":["30 mètres","50 mètres","100 mètres"],"answer":2,"explain":"Sur autoroute, le triangle se place à au moins 100 mètres en deçà du véhicule (30 mètres sur les voies ordinaires), de façon à être visible à environ 50 mètres.","ref":"Art. 51.2 AR 01/12/1975"},{"id":"SEC-017","theme":"securite","q":"Hors agglomération, ma voiture tombe en panne à un endroit où le stationnement est interdit et je ne peux pas la déplacer. Où dois-je placer le triangle de danger ?","choices":["À au moins 30 mètres derrière le véhicule, visible à environ 50 mètres","Sur le toit du véhicule","À 5 mètres derrière le véhicule"],"answer":0,"explain":"Sur les voies ordinaires, le triangle est placé en deçà du véhicule, en position presque verticale, à au moins 30 mètres et de manière à être visible à environ 50 mètres. Le placer sur le véhicule n'est admis qu'en agglomération, quand les 30 m sont impossibles.","ref":"Art. 51.2 AR 01/12/1975"},{"id":"SEC-018","theme":"securite","q":"Je suis en panne sur la bande d'arrêt d'urgence d'une autoroute. Je dois sortir de la voiture. Quelle obligation dois-je respecter ?","choices":["Porter une veste de sécurité rétroréfléchissante dès que je sors","Porter la veste uniquement la nuit","Aucune, si mes feux de détresse sont allumés"],"answer":0,"explain":"Sur autoroute et route pour automobiles, le conducteur d'un véhicule en panne rangé là où l'arrêt et le stationnement sont interdits doit porter une veste de sécurité rétroréfléchissante dès qu'il sort du véhicule, de jour comme de nuit.","ref":"Art. 51.4 AR 01/12/1975"},{"id":"SEC-019","theme":"securite","q":"Ma voiture tombe en panne en journée. Je parviens à la pousser sur un emplacement où le stationnement est autorisé, en dehors de la circulation. Dois-je placer le triangle de danger ?","choices":["Non, le véhicule est rangé comme un véhicule en stationnement","Oui, dans tous les cas de panne"],"answer":0,"explain":"Le conducteur en panne doit ranger son véhicule comme un véhicule en stationnement. Le triangle n'est obligatoire que si le véhicule ne peut être déplacé ou ne peut être rangé qu'à un endroit où l'arrêt et le stationnement sont interdits.","ref":"Art. 51.1 AR 01/12/1975"},{"id":"SEC-020","theme":"securite","q":"Lequel de ces accessoires doit obligatoirement se trouver à bord de toute voiture ?","choices":["Une roue de secours","Un extincteur","Un câble de remorquage"],"answer":1,"explain":"Tout véhicule automobile doit avoir à bord un triangle de danger, un ou deux extincteurs et une trousse (ou coffret) de secours, conformes au règlement technique.","ref":"Art. 81.2 AR 01/12/1975"},{"id":"SEC-021","theme":"securite","q":"Quelle est la profondeur minimale des rainures principales des pneus d'une voiture ?","choices":["1 mm","1,6 mm","3 mm"],"answer":1,"explain":"Les rainures principales des pneus doivent avoir une profondeur d'au moins 1,6 mm (1 mm pour les cyclomoteurs). En dessous, l'adhérence sur route mouillée diminue fortement.","ref":"Art. 81.4.1 AR 01/12/1975"},{"id":"SEC-022","theme":"securite","q":"Mon passager adulte, assis à l'arrière sur une place équipée d'une ceinture, ne veut pas la boucler pour un trajet de 2 km. Est-ce permis ?","choices":["Oui, la ceinture n'est obligatoire qu'à l'avant","Oui, pour un court trajet","Non, tous les occupants doivent porter la ceinture aux places qui en sont équipées"],"answer":2,"explain":"Le conducteur et tous les passagers d'une voiture en circulation doivent porter la ceinture de sécurité aux places qui en sont équipées, quelle que soit la longueur du trajet.","ref":"Art. 35.1.1 AR 01/12/1975"},{"id":"SEC-023","theme":"securite","q":"Je transporte dans ma voiture ma nièce de 10 ans, qui mesure 1,30 m. Comment doit-elle être attachée ?","choices":["Dans un dispositif de retenue pour enfants adapté (par ex. rehausseur)","Avec la ceinture seule, puisqu'elle a plus de 8 ans","Avec la ceinture seule, si elle est à l'arrière"],"answer":0,"explain":"Les enfants de moins de 18 ans qui mesurent moins de 135 cm doivent être transportés dans un dispositif de retenue pour enfants adapté à leur taille et leur poids.","ref":"Art. 35.1.1 AR 01/12/1975"},{"id":"SEC-024","theme":"securite","q":"Mon fils de 12 ans mesure 1,45 m. Peut-il s'asseoir à l'avant avec la ceinture de sécurité normale ?","choices":["Non, il doit s'asseoir à l'arrière jusqu'à 18 ans","Oui","Non, il doit utiliser un siège enfant jusqu'à 14 ans"],"answer":1,"explain":"Le critère est la taille : à partir de 135 cm, l'enfant peut utiliser la ceinture de sécurité normale, à l'avant comme à l'arrière.","ref":"Art. 35.1.1 AR 01/12/1975"},{"id":"SEC-025","theme":"securite","q":"Je veux installer le siège bébé dos à la route sur le siège passager avant. Ce siège est protégé par un airbag frontal. Est-ce autorisé ?","choices":["Oui, si le bébé est bien attaché","Non, sauf si l'airbag frontal est désactivé"],"answer":1,"explain":"Un enfant ne peut pas être transporté dos à la route sur un siège passager protégé par un airbag frontal actif : en se déployant, l'airbag frapperait le siège et blesserait gravement l'enfant. L'airbag doit être désactivé.","grave":true,"ref":"Art. 35.1.1 AR 01/12/1975"},{"id":"SEC-026","theme":"securite","q":"Je fais une marche arrière pour me garer. Suis-je obligé de garder ma ceinture de sécurité bouclée ?","choices":["Non, le conducteur qui effectue une marche arrière en est dispensé","Oui, sans exception"],"answer":0,"explain":"Le conducteur qui effectue une marche arrière est dispensé de l'obligation de porter la ceinture, pour pouvoir se retourner facilement.","ref":"Art. 35.2.1 1° AR 01/12/1975"},{"id":"SEC-027","theme":"securite","q":"Ma voiture compte 5 places équipées d'une ceinture. Puis-je transporter 6 personnes (moi compris) en me serrant à l'arrière ?","choices":["Non","Oui, pour un court trajet"],"answer":0,"explain":"Le nombre d'occupants ne peut pas dépasser le nombre de places équipées d'une ceinture ou d'un dispositif de retenue pour enfants homologué (et de celles qui ne doivent pas en être équipées).","ref":"Art. 44.1 AR 01/12/1975"},{"id":"SEC-028","theme":"securite","q":"Je roule en suivant le GPS de mon smartphone. À quelle condition est-ce autorisé ?","choices":["Si je le tiens d'une seule main","Ce n'est jamais autorisé","Si le smartphone est fixé au véhicule dans un support prévu à cet effet"],"answer":2,"explain":"En roulant, le conducteur ne peut utiliser, tenir en main ni manipuler un appareil électronique mobile à écran, sauf s'il est fixé au véhicule dans un support destiné à cet effet.","ref":"Art. 8.4 AR 01/12/1975"},{"id":"SEC-029","theme":"securite","q":"Je roule au pas dans un embouteillage. Puis-je prendre mon téléphone en main pour lire un message ?","choices":["Oui, car je roule très lentement","Non"],"answer":1,"explain":"Tant que le véhicule n'est pas à l'arrêt ou en stationnement, il est interdit de tenir en main ou de manipuler un téléphone, même à faible vitesse. Lire un message détourne le regard de la route.","grave":true,"ref":"Art. 8.4 AR 01/12/1975"},{"id":"SEC-030","theme":"securite","q":"Je conduis une voiture avec un permis B. À partir de quel taux d'alcool dans le sang suis-je en infraction ?","choices":["0,2 g/l","0,5 g/l","0,8 g/l"],"answer":1,"explain":"Pour un conducteur ordinaire, la conduite est punissable à partir de 0,5 gramme d'alcool par litre de sang (soit 0,22 mg par litre d'air alvéolaire expiré).","grave":true,"ref":"Art. 34 §1 Loi du 16/03/1968"},{"id":"SEC-031","theme":"securite","q":"Lors d'un contrôle, la police mesure l'alcool dans mon haleine. À partir de quelle concentration un conducteur de voiture ordinaire est-il en infraction ?","choices":["0,09 mg par litre d'air alvéolaire expiré","0,22 mg par litre d'air alvéolaire expiré","0,35 mg par litre d'air alvéolaire expiré"],"answer":1,"explain":"0,22 mg/l d'air alvéolaire expiré correspond à 0,5 g/l de sang : c'est le seuil général d'infraction.","grave":true,"ref":"Art. 34 §1 Loi du 16/03/1968"},{"id":"SEC-032","theme":"securite","q":"Quel est le taux d'alcool maximal dans le sang pour un chauffeur de camion (permis C) ou d'autobus (permis D) ?","choices":["Moins de 0,2 g/l","Moins de 0,5 g/l","Moins de 0,8 g/l"],"answer":0,"explain":"Pour les conducteurs de véhicules des catégories C et D (et ceux qui transportent des personnes soumis aux mêmes normes médicales), l'infraction commence à 0,2 g/l de sang, soit 0,09 mg/l d'air expiré.","grave":true,"ref":"Art. 34 §3 Loi du 16/03/1968"},{"id":"SEC-033","theme":"securite","q":"Mon analyse d'haleine indique 0,25 mg d'alcool par litre d'air alvéolaire expiré. Que se passe-t-il immédiatement ?","choices":["Rien, je suis sous la limite","Une interdiction de conduire de 12 heures","Une interdiction de conduire de 1 heure"],"answer":1,"explain":"Dès 0,22 mg/l d'air alvéolaire expiré (ou en cas de refus du test), la conduite est interdite pendant 12 heures à compter de la constatation, et le permis doit être remis à la police pour cette durée.","grave":true,"ref":"Art. 60 §3 et 61 Loi du 16/03/1968"},{"id":"SEC-034","theme":"securite","q":"À partir de quelle concentration d'alcool dans l'air expiré l'amende pénale passe-t-elle de 200–4.000 € à 1.600–16.000 € ?","choices":["0,22 mg/l","0,35 mg/l","0,50 mg/l"],"answer":1,"explain":"De 0,22 à moins de 0,35 mg/l (0,5 à 0,8 g/l de sang), l'amende est de 200 à 4.000 €. À partir de 0,35 mg/l (0,8 g/l de sang), elle va de 1.600 à 16.000 €.","grave":true,"ref":"Art. 34 §1 et §2 Loi du 16/03/1968"},{"id":"SEC-035","theme":"securite","q":"J'accompagne comme guide un candidat titulaire d'un permis provisoire. Les limites d'alcool s'appliquent-elles aussi à moi ?","choices":["Oui, comme si je conduisais","Non, seul le conducteur est concerné"],"answer":0,"explain":"La loi punit de la même manière la personne qui conduit et celle qui accompagne un conducteur en vue de l'apprentissage avec un taux d'alcool supérieur aux limites.","grave":true,"ref":"Art. 34 §1 et §2 Loi du 16/03/1968"},{"id":"SEC-036","theme":"securite","q":"Après une soirée, un ami visiblement ivre me demande les clés de ma voiture pour rentrer chez lui. Si je les lui donne…","choices":["Je commets moi-même une infraction","Je ne risque rien, c'est lui qui conduit"],"answer":0,"explain":"Confier délibérément un véhicule à une personne qui montre des signes évidents d'imprégnation alcoolique ou d'ivresse est puni d'une amende de 1.600 à 16.000 €.","grave":true,"ref":"Art. 37 Loi du 16/03/1968"},{"id":"SEC-037","theme":"securite","q":"Lors d'un contrôle, un test salivaire révèle la présence de cannabis (THC) au-delà du seuil légal. Je me sens pourtant en pleine forme. Quelle est la conséquence immédiate ?","choices":["Aucune, puisque je ne me sens pas influencé","Une interdiction de conduire de 12 heures","Un simple avertissement"],"answer":1,"explain":"Un test salivaire positif (THC, amphétamine, MDMA, morphine/héroïne, cocaïne) entraîne une interdiction de conduire de 12 heures, et la conduite avec ces substances est punissable, quel que soit le ressenti du conducteur.","grave":true,"ref":"Art. 37bis et 61ter Loi du 16/03/1968"},{"id":"SEC-038","theme":"securite","q":"Mon médecin me prescrit un médicament dont la notice signale qu'il provoque de la somnolence. Puis-je conduire ?","choices":["Oui, un médicament prescrit ne peut jamais m'être reproché","Seulement si je suis réellement en état de conduire ; sinon, je dois m'abstenir"],"answer":1,"explain":"Tout conducteur doit être en état de conduire et garder constamment le contrôle de son véhicule. Conduire dans un état analogue à l'ivresse résultant de médicaments est punissable.","ref":"Art. 8.3 AR 01/12/1975 ; art. 35 Loi du 16/03/1968"},{"id":"SEC-039","theme":"securite","q":"Sur l'autoroute, après trois heures de route de nuit, je bâille sans arrêt et mes paupières sont lourdes. Que dois-je faire ?","choices":["Ouvrir la fenêtre et monter le volume de la radio","Accélérer pour arriver plus vite","M'arrêter dans un endroit sûr (aire de repos) pour me reposer"],"answer":2,"explain":"Le conducteur doit être en état de conduire et garder constamment le contrôle de son véhicule. Face à la fatigue, seul le repos est efficace : air frais ou musique ne retardent l'endormissement que de quelques minutes.","ref":"Art. 8.3 AR 01/12/1975"},{"id":"SEC-040","theme":"securite","q":"Je viens d'avoir un accrochage sans blessé avec une autre voiture. Que dois-je faire ?","choices":["Rester sur place pour faire les constatations ensemble (par ex. constat amiable) ou, à défaut d'accord, permettre à la police de les faire","Partir si les dégâts sont légers","Partir après avoir pris une photo de sa plaque"],"answer":0,"explain":"En cas d'accident avec dégâts matériels, chaque personne impliquée doit rester sur place pour faire les constatations en commun ou, à défaut d'accord, permettre à un agent de les faire. Elle doit aussi présenter sa carte d'identité si on le lui demande.","grave":true,"ref":"Art. 52.2 AR 01/12/1975"},{"id":"SEC-041","theme":"securite","q":"Je suis impliqué dans un accident où une personne est blessée. Suis-je obligé de déplacer immédiatement mon véhicule pour dégager la route ?","choices":["Non, je dois surtout sécuriser les lieux, porter secours au blessé si nécessaire et rester sur place","Oui, toujours"],"answer":0,"explain":"En cas de dommages corporels, le déplacement du véhicule n'est pas obligatoire. Il faut sécuriser les lieux, porter secours aux blessés si nécessaire et rester sur place pour les constatations de la police.","ref":"Art. 52.1 et 52.3 AR 01/12/1975"},{"id":"SEC-042","theme":"securite","q":"En manœuvrant, j'abîme une voiture en stationnement. Son propriétaire est absent. Que dois-je faire ?","choices":["Rien, puisque personne ne m'a vu","Fournir mes nom et adresse sur place si possible, et en tout cas au plus tôt, directement ou par la police"],"answer":1,"explain":"Si la personne lésée n'est pas présente, les personnes impliquées doivent, autant que possible, laisser sur place leurs nom et adresse et, en tout cas, les communiquer au plus tôt, directement ou par l'intermédiaire de la police.","grave":true,"ref":"Art. 52.2 AR 01/12/1975"},{"id":"SEC-043","theme":"securite","q":"Après un accident avec blessé, aucun policier n'a pu être joint dans un délai raisonnable. Dans quel délai dois-je déclarer l'accident à la police ?","choices":["Dans les 24 heures","Dans les 48 heures","Dans les 8 jours"],"answer":0,"explain":"En cas d'accident avec dommages corporels, si aucun agent n'a pu être touché dans un délai raisonnable, les personnes impliquées doivent déclarer l'accident au plus tard dans les 24 heures, au bureau de police le plus proche ou à celui de leur domicile.","ref":"Art. 52.3 AR 01/12/1975"},{"id":"SEC-044","theme":"securite","q":"Je transporte de longues planches dans ma voiture. Dans le cas général, de combien le chargement peut-il dépasser l'arrière du véhicule ?","choices":["De 0,50 mètre au maximum","De 3 mètres au maximum","De 1 mètre au maximum"],"answer":2,"explain":"Pour une voiture, le chargement ne peut pas dépasser l'extrémité arrière du véhicule de plus d'un mètre (sauf exceptions, par ex. pièces indivisibles de grande longueur).","ref":"Art. 46.2.3 AR 01/12/1975"},{"id":"SEC-045","theme":"securite","q":"Je transporte une échelle sur la galerie de toit de ma voiture. Peut-elle dépasser à l'avant du véhicule ?","choices":["Oui, jusqu'à 1 mètre","Oui, jusqu'à 0,50 mètre","Non, jamais"],"answer":2,"explain":"En aucun cas le chargement ne peut dépasser l'extrémité avant du véhicule (seule exception : les porte-voitures).","ref":"Art. 46.2.1 AR 01/12/1975"},{"id":"SEC-046","theme":"securite","q":"En plein jour, mon chargement dépasse de plus d'un mètre l'arrière de ma camionnette. Comment dois-je le signaler ?","choices":["Avec un panneau carré de 0,50 m à bandes rouges et blanches","Avec un chiffon de couleur vive","Aucune signalisation n'est requise de jour"],"answer":0,"explain":"Un chargement dépassant de plus d'un mètre l'arrière est signalé par un panneau carré de 0,50 m de côté à bandes alternées rouges et blanches rétroréfléchissantes. La nuit, on y ajoute un feu rouge vers l'arrière et des catadioptres orange sur les côtés.","ref":"Art. 47.1 et 47.2 AR 01/12/1975"},{"id":"SEC-047","theme":"securite","q":"Le vélo que je transporte sur un porte-vélos arrière cache partiellement ma plaque d'immatriculation et un feu arrière. Est-ce permis ?","choices":["Non, le chargement ne peut masquer ni les feux ni la plaque d'immatriculation","Oui, si le trajet est court"],"answer":0,"explain":"Le chargement doit être disposé de manière à ne pas masquer les feux, les catadioptres et le numéro d'immatriculation, ni nuire à la visibilité ou à la stabilité du véhicule.","ref":"Art. 45.1 AR 01/12/1975"},{"id":"SEC-048","theme":"securite","q":"J'ai un permis B sans code 96. Ma voiture a une masse maximale autorisée (MMA) de 2.000 kg. Puis-je tracter une remorque dont la MMA est de 1.000 kg ?","choices":["Oui, car la MMA de l'ensemble ne dépasse pas 3.500 kg","Non, une remorque de plus de 750 kg exige toujours le permis BE"],"answer":0,"explain":"Avec le permis B, on peut toujours tracter une remorque de MMA ≤ 750 kg. Une remorque plus lourde est permise si la MMA de l'ensemble ne dépasse pas 3.500 kg (4.250 kg avec le code 96).","ref":"Art. 2 et 20 AR 23/03/1998"},{"id":"SEC-049","theme":"securite","q":"Pour pouvoir être guide d'un candidat au permis B (permis provisoire avec guide), depuis combien de temps au moins faut-il être titulaire d'un permis B ?","choices":["3 ans","6 ans","8 ans"],"answer":2,"explain":"Le guide doit être titulaire depuis au moins 8 ans d'un permis B belge ou européen, ne pas avoir été déchu du droit de conduire au cours des 3 dernières années et être mentionné sur le permis provisoire.","ref":"Art. 3 §2 AR 10/07/2006 (permis cat. B)"},{"id":"SEC-050","theme":"securite","q":"Je roule avec un permis provisoire B avec guide. Mon guide est assis à côté de moi. Puis-je emmener mon petit frère sur la banquette arrière ?","choices":["Oui, s'il porte sa ceinture","Non, seuls le ou les guides mentionnés et/ou un instructeur breveté peuvent m'accompagner"],"answer":1,"explain":"Le titulaire d'un permis provisoire B avec guide ne peut être accompagné que par le ou les guides mentionnés sur son permis provisoire et/ou par un instructeur breveté, à l'exclusion de tout autre passager.","ref":"Art. 3 §4 AR 10/07/2006 (permis cat. B)"},{"id":"SEC-051","theme":"securite","q":"Je suis titulaire d'un permis provisoire B. Un samedi soir, puis-je conduire à 23 h ?","choices":["Non, c'est interdit de 22 h à 6 h les nuits du week-end et des jours fériés","Oui, si mon guide est à côté de moi"],"answer":0,"explain":"Le candidat ne peut pas conduire de 22 h à 6 h le lendemain le vendredi, le samedi, le dimanche, la veille des jours fériés légaux et les jours fériés légaux.","ref":"Art. 6 AR 10/07/2006 (permis cat. B)"},{"id":"SEC-052","theme":"securite","q":"Je m'entraîne à la conduite avec un permis provisoire. Où doit se trouver le signe « L » ?","choices":["À l'arrière du véhicule, à un endroit apparent","Sur le pare-brise, côté passager","Nulle part si un guide m'accompagne"],"answer":0,"explain":"Le véhicule conduit sous le couvert d'un permis de conduire provisoire doit être muni du signe « L » à l'arrière, à un endroit apparent. Le candidat doit aussi être porteur de son permis provisoire en cours de validité.","ref":"Art. 6, 2°, d) AR 23/03/1998 (applicable au permis provisoire B via art. 11 AR 10/07/2006)"},{"id":"SEC-053","theme":"securite","q":"Je patiente cinq minutes, moteur au ralenti, devant l'école en attendant mon enfant. Que dit le code ?","choices":["Je dois éviter de laisser tourner le moteur au point mort sans nécessité","Je dois laisser tourner le moteur pour garder la batterie chargée","Le code ne dit rien à ce sujet"],"answer":0,"explain":"Le conducteur doit veiller à ne pas laisser le moteur en marche au point mort, sauf nécessité. Couper le moteur réduit la pollution, le bruit et la consommation.","ref":"Art. 8.6 AR 01/12/1975"},{"id":"SEC-054","theme":"securite","q":"Il pleut fortement sur une route hors agglomération en Wallonie où la vitesse est limitée à 90 km/h. Quelle est l'attitude correcte ?","choices":["Rouler à 90 km/h puisque c'est autorisé","Réduire ma vitesse et augmenter ma distance de sécurité","Rouler plus près du véhicule qui me précède pour profiter de ses traces"],"answer":1,"explain":"La vitesse doit être adaptée notamment aux conditions climatiques et à l'état de la route, et la distance de sécurité doit tenir compte de la vitesse. Sur route mouillée, la distance de freinage augmente.","ref":"Art. 10.1 AR 01/12/1975"},{"id":"SEC-055","theme":"securite","q":"Je laisse ma voiture quelques minutes devant un magasin. Que dois-je faire ?","choices":["Laisser le moteur tourner pour repartir plus vite","Prendre les précautions pour éviter tout accident et tout usage par un tiers (moteur coupé, frein serré, antivol enclenché)"],"answer":1,"explain":"Le conducteur ne peut quitter son véhicule sans prendre les précautions nécessaires pour éviter tout accident et tout usage abusif par un tiers. Si le véhicule a un dispositif antivol, il doit l'utiliser.","ref":"Art. 8.5 AR 01/12/1975"},{"id":"SEC-056","theme":"securite","q":"Un bus scolaire signalé par le panneau « transport scolaire » est arrêté devant moi avec tous ses clignotants allumés. Que dois-je faire ?","choices":["Le dépasser rapidement avant que les enfants descendent","Klaxonner pour avertir les enfants","Ralentir fortement et, au besoin, m'arrêter : des enfants vont monter ou descendre"],"answer":2,"explain":"Quand un véhicule de transport scolaire fait fonctionner tous ses indicateurs de direction, des enfants embarquent ou débarquent : il faut redoubler de prudence, ralentir fortement et s'arrêter si nécessaire.","grave":true,"ref":"Art. 39bis.2 AR 01/12/1975"},{"id":"SIG-001","theme":"signalisation","q":"À un carrefour, le feu est vert pour moi, mais un agent qualifié me fait signe de m'arrêter en levant le bras verticalement. Que dois-je faire ?","choices":["M'arrêter","Passer, car le feu vert m'y autorise","Passer prudemment en klaxonnant"],"answer":0,"explain":"Les injonctions des agents qualifiés prévalent sur la signalisation routière et sur les règles de circulation. Le bras levé verticalement signifie arrêt pour tous les usagers, sauf pour ceux déjà engagés dans le carrefour, qui doivent l'évacuer.","grave":true,"ref":"Art. 4.2 et 6.1 AR 01/12/1975"},{"id":"SIG-002","theme":"signalisation","q":"Je circule sur une route où ce panneau est placé. Au prochain carrefour, un véhicule arrive de ma droite. Qui a la priorité ?","choices":["Le véhicule venant de droite, car la priorité de droite s'applique toujours","Moi","Celui qui arrive le premier au carrefour"],"answer":1,"explain":"Le signal B9 indique une voie prioritaire. La signalisation routière prévaut sur les règles de circulation : la priorité de droite ne s'applique donc pas aux carrefours de cette voie.","grave":true,"sign":"B9","ref":"Art. 6.2 et 67.3 AR 01/12/1975"},{"id":"SIG-005","theme":"signalisation","q":"Que signifie ce feu ?","choices":["Je peux franchir le signal en redoublant de prudence ; les règles de priorité restent d'application","J'ai la priorité sur tous les autres usagers","Je dois m'arrêter comme à un feu rouge"],"answer":0,"explain":"Un feu jaune-orange clignotant signifie autorisation de franchir le signal en redoublant de prudence. Il ne modifie pas les règles de priorité (panneaux ou priorité de droite).","sign":"FEU-orange-cligno","ref":"Art. 64.1 AR 01/12/1975"},{"id":"SIG-006","theme":"signalisation","q":"Le feu passe à cet état alors que je suis à 60 m de la ligne d'arrêt et que je peux freiner sans danger. Que dois-je faire ?","choices":["Accélérer pour passer avant le rouge","M'arrêter avant la ligne d'arrêt"],"answer":1,"explain":"Le feu jaune-orange fixe interdit de franchir la ligne d'arrêt, sauf si le conducteur en est si près au moment où il s'allume qu'il ne peut plus s'arrêter en sécurité.","grave":true,"sign":"FEU-orange","ref":"Art. 61.1.2° AR 01/12/1975"},{"id":"SIG-007","theme":"signalisation","q":"Le feu devient orange fixe alors que je suis juste devant la ligne d'arrêt et qu'un freinage brusque serait dangereux. Je franchis la ligne. Puis-je traverser le carrefour ?","choices":["Non, je dois m'arrêter au milieu du carrefour","Oui, à condition de ne pas mettre en danger les autres usagers","Oui, et j'ai alors priorité sur tout le monde"],"answer":1,"explain":"Si le conducteur ne pouvait plus s'arrêter dans des conditions de sécurité suffisantes, il peut franchir la ligne, mais il ne traverse le carrefour qu'à condition de ne pas mettre en danger les autres usagers.","ref":"Art. 61.1.2° AR 01/12/1975"},{"id":"SIG-008","theme":"signalisation","q":"Où dois-je m'arrêter face à ce feu, à un carrefour où aucune ligne d'arrêt n'est tracée ?","choices":["Au milieu du carrefour","Juste avant le passage pour piétons situé après le carrefour","Avant le signal lui-même"],"answer":2,"explain":"Le feu rouge interdit de franchir la ligne d'arrêt ou, à défaut de ligne d'arrêt, le signal même.","grave":true,"sign":"FEU-rouge","ref":"Art. 61.1.1° AR 01/12/1975"},{"id":"SIG-009","theme":"signalisation","q":"Le feu rouge est allumé et, en même temps, une flèche verte vers la droite est allumée. Je veux tourner à droite. Que puis-je faire ?","choices":["Tourner à droite en cédant le passage aux conducteurs venant régulièrement d'autres directions et aux piétons","Attendre que le feu rouge s'éteigne","Tourner à droite avec priorité sur les piétons"],"answer":0,"explain":"Une flèche verte allumée avec le feu rouge autorise à poursuivre uniquement dans la direction indiquée, à condition de céder le passage aux conducteurs débouchant régulièrement d'autres directions et aux piétons.","ref":"Art. 61.1.5° AR 01/12/1975"},{"id":"SIG-010","theme":"signalisation","q":"Dans quel ordre les feux tricolores se succèdent-ils ?","choices":["Vert, rouge, orange","Vert, orange, rouge","Rouge, orange, vert"],"answer":1,"explain":"Le feu jaune-orange apparaît après le vert, le rouge après le jaune-orange, et le vert après le rouge. Il n'y a donc pas de phase orange entre le rouge et le vert.","ref":"Art. 61.3.1 AR 01/12/1975"},{"id":"SIG-012","theme":"signalisation","q":"Je tourne à gauche dans un carrefour à feux. Une flèche verte orientée vers la gauche est placée seule à la sortie du carrefour et s'allume. Que signifie-t-elle ?","choices":["Je dois céder le passage aux véhicules venant en sens inverse","Le virage à gauche est interdit","La circulation venant en sens inverse est arrêtée par un feu rouge : je peux évacuer le carrefour"],"answer":2,"explain":"Cette flèche d'évacuation signifie que la circulation venant en sens inverse est arrêtée par un feu rouge afin de faciliter l'évacuation du carrefour.","ref":"Art. 62 AR 01/12/1975"},{"id":"SIG-013","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Je dois marquer l'arrêt et céder le passage","Fin de route prioritaire","Je dois céder le passage, sans être obligé de m'arrêter si la voie est libre"],"answer":0,"explain":"Le signal B5 (stop) impose de marquer l'arrêt et de céder le passage, même si aucun véhicule n'arrive. L'arrêt se fait à la ligne d'arrêt.","grave":true,"sign":"B5","ref":"Art. 67.3 et 76.1 AR 01/12/1975"},{"id":"SIG-014","theme":"signalisation","q":"J'arrive à ce panneau. La route que j'aborde est entièrement dégagée et la visibilité est parfaite. Dois-je m'arrêter ?","choices":["Non, je peux continuer sans m'arrêter","Oui, je dois m'arrêter dans tous les cas"],"answer":0,"explain":"Le signal B1 impose de céder le passage aux usagers de la voie abordée. Si personne n'arrive, l'arrêt n'est pas obligatoire, contrairement au stop (B5).","sign":"B1","ref":"Art. 12.3.1 et 67.3 AR 01/12/1975"},{"id":"SIG-015","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Début d'une voie prioritaire","Fin de la voie prioritaire","Interdiction de dépasser"],"answer":1,"explain":"Le signal B11 indique la fin de la voie prioritaire. Aux carrefours suivants, les règles générales (priorité de droite) s'appliquent sauf autre signalisation.","sign":"B11","ref":"Art. 67.3 AR 01/12/1975"},{"id":"SIG-020","theme":"signalisation","q":"Que m'annonce ce panneau ?","choices":["Un virage dangereux à droite","Une obligation de tourner à gauche","Un virage dangereux à gauche"],"answer":2,"explain":"Le triangle à bord rouge est un signal de danger. A1a annonce un virage dangereux à gauche (A1b : à droite).","sign":"A1a","ref":"Art. 66.4 AR 01/12/1975"},{"id":"SIG-021","theme":"signalisation","q":"Que m'annonce ce panneau ?","choices":["Un virage dangereux à droite","Une obligation de tourner à droite","Un double virage, le premier à gauche"],"answer":0,"explain":"A1b annonce un virage dangereux à droite. Il faut adapter sa vitesse avant d'entrer dans le virage.","sign":"A1b","ref":"Art. 66.4 AR 01/12/1975"},{"id":"SIG-022","theme":"signalisation","q":"Que m'annonce ce panneau ?","choices":["Un pont mobile","Un rétrécissement de la chaussée","Une route à sens unique"],"answer":1,"explain":"Le signal A7a annonce un rétrécissement de la chaussée. Il faut se préparer à croiser plus étroitement ou à laisser passer.","sign":"A7a","ref":"Art. 66.4 AR 01/12/1975"},{"id":"SIG-023","theme":"signalisation","q":"Que m'annonce ce panneau ?","choices":["Un passage à niveau","Un feu en panne","Des signaux lumineux de circulation"],"answer":2,"explain":"Le signal de danger A33 annonce la présence de signaux lumineux de circulation (feux tricolores).","sign":"A33","ref":"Art. 66.4 AR 01/12/1975"},{"id":"SIG-024","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Un danger non défini par un symbole spécial ; un panneau additionnel en indique la nature","Interdiction de circuler","Fin de toutes les interdictions"],"answer":0,"explain":"Le signal A51 (point d'exclamation) annonce un danger qui n'a pas de symbole spécial. Un panneau additionnel indique la nature du danger.","sign":"A51","ref":"Art. 66.4 AR 01/12/1975"},{"id":"SIG-025","theme":"signalisation","q":"Je veux entrer dans une rue dont l'entrée porte ce panneau. Est-ce autorisé ?","choices":["Oui, si je roule lentement","Non, c'est un sens interdit","Oui, si je n'y vais que pour quelques mètres"],"answer":1,"explain":"Le signal C1 signifie sens interdit pour tout conducteur. Un panneau additionnel peut excepter certaines catégories (par exemple les cyclistes).","grave":true,"sign":"C1","ref":"Art. 68.3 et 68.4 AR 01/12/1975"},{"id":"SIG-026","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Stationnement interdit","Sens interdit uniquement pour les camions","Accès interdit, dans les deux sens, à tout conducteur"],"answer":2,"explain":"Le signal C3 interdit l'accès, dans les deux sens, à tout conducteur. À ne pas confondre avec C1 (sens interdit) ni avec les signaux de stationnement.","sign":"C3","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-027","theme":"signalisation","q":"Ce panneau est placé peu avant un carrefour. Où s'applique l'interdiction ?","choices":["Au prochain carrefour","Sur tous les carrefours jusqu'à la fin de l'agglomération","Uniquement aux heures de pointe"],"answer":0,"explain":"Les signaux C31a et C31b interdisent de tourner, au prochain carrefour, dans le sens indiqué par la flèche (ici à gauche).","sign":"C31a","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-028","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Obligation de tourner à droite","Interdiction de tourner à droite au prochain carrefour","Virage dangereux à droite"],"answer":1,"explain":"C31b : au prochain carrefour, interdiction de tourner dans le sens indiqué par la flèche, ici à droite. Le cercle à bord rouge indique une interdiction.","sign":"C31b","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-029","theme":"signalisation","q":"Jusqu'où s'applique l'interdiction indiquée par ce panneau ?","choices":["Sur 100 mètres seulement","Jusqu'à la sortie de la commune","Jusqu'au prochain carrefour inclus"],"answer":2,"explain":"Le signal C33 interdit de faire demi-tour à partir du signal jusqu'au prochain carrefour inclus.","sign":"C33","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-030","theme":"signalisation","q":"Je roule en voiture sur une route où ce panneau est d'application. Devant moi roule lentement une motocyclette sans side-car. Puis-je la dépasser par la gauche (dans le respect des autres règles) ?","choices":["Oui","Non"],"answer":0,"explain":"Le signal C35 interdit de dépasser par la gauche un véhicule attelé ou un véhicule à plus de deux roues. Une motocyclette à deux roues peut donc être dépassée, si les autres conditions du dépassement sont remplies.","sign":"C35","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-031","theme":"signalisation","q":"Ce panneau est d'application. Puis-je dépasser par la gauche une voiture qui roule lentement devant moi ?","choices":["Non","Oui, si la visibilité est bonne","Oui, si elle roule à moins de 50 km/h"],"answer":0,"explain":"Le signal C35 interdit de dépasser par la gauche un véhicule à plus de deux roues ou un véhicule attelé, ce qui inclut une voiture.","grave":true,"sign":"C35","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-032","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Fin de l'autoroute","Fin de toutes les interdictions locales imposées aux véhicules en mouvement","Fin de l'interdiction de stationner"],"answer":1,"explain":"Le signal C46 met fin à toutes les interdictions locales imposées aux véhicules en mouvement (par ex. interdiction de dépasser ou limitation de vitesse locale). Il ne concerne pas le stationnement.","sign":"C46","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-033","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Vitesse minimale de 50 km/h","Fin d'agglomération","Fin de la limitation de vitesse à 50 km/h imposée par un signal C43"],"answer":2,"explain":"Le signal C45 indique la fin de la limitation de vitesse imposée par le signal C43 portant le même chiffre.","sign":"C45-50","ref":"Art. 68.3 AR 01/12/1975"},{"id":"SIG-034","theme":"signalisation","q":"Ce panneau est placé sur un îlot au milieu de la chaussée. Que dois-je faire ?","choices":["Passer à droite de l'îlot","Passer à gauche de l'îlot","Je peux passer d'un côté ou de l'autre"],"answer":0,"explain":"Le signal D1 impose de suivre la direction indiquée par la flèche. Placé sur un obstacle, il oblige à passer du côté indiqué par la flèche, ici à droite.","grave":true,"sign":"D1-downright","ref":"Art. 9.6 et 69.3 AR 01/12/1975"},{"id":"SIG-035","theme":"signalisation","q":"Que signifie ce panneau rond à fond bleu ?","choices":["Route prioritaire tout droit","Obligation de suivre la direction indiquée par la flèche (aller tout droit)","Sens unique"],"answer":1,"explain":"Les panneaux ronds à fond bleu sont des signaux d'obligation. D1 impose de suivre la direction indiquée par la flèche.","sign":"D1-up","ref":"Art. 69.3 AR 01/12/1975"},{"id":"SIG-036","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Interdiction de faire demi-tour","Fin de zone 30","Sens giratoire obligatoire"],"answer":2,"explain":"Le signal D5 impose le sens giratoire. Un rond-point est signalé par des signaux D5 et ses accès sont pourvus de signaux B1 ou B5.","sign":"D5","ref":"Art. 2 et 69.3 AR 01/12/1975"},{"id":"SIG-037","theme":"signalisation","q":"À l'endroit où ce panneau est placé, puis-je m'arrêter un instant pour laisser descendre un passager ?","choices":["Non","Oui"],"answer":0,"explain":"Le signal E3 interdit à la fois l'arrêt et le stationnement. Même un arrêt bref pour déposer quelqu'un n'est pas permis.","sign":"E3","ref":"Art. 70.2.1 AR 01/12/1975"},{"id":"SIG-038","theme":"signalisation","q":"Quelle est la différence entre ce panneau et le panneau E3 (barre en croix) ?","choices":["Celui-ci interdit seulement le stationnement ; E3 interdit l'arrêt et le stationnement","Il n'y en a aucune","Celui-ci interdit l'arrêt ; E3 interdit seulement le stationnement"],"answer":0,"explain":"E1 (une barre oblique) signifie stationnement interdit ; E3 (deux barres en croix) signifie arrêt et stationnement interdits.","sign":"E1","ref":"Art. 70.2.1 AR 01/12/1975"},{"id":"SIG-039","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Parking interdit","Stationnement autorisé","Poste de police"],"answer":1,"explain":"Le signal E9a indique que le stationnement est autorisé. Des inscriptions ou symboles peuvent préciser la catégorie de véhicules ou une réglementation particulière.","sign":"E9a","ref":"Art. 70.2.1 AR 01/12/1975"},{"id":"SIG-040","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Fin d'agglomération","Indication de direction vers une localité","Commencement d'une agglomération"],"answer":2,"explain":"Le signal F1a indique le commencement d'une agglomération. Les règles propres aux agglomérations s'y appliquent (par ex. la vitesse maximale en agglomération).","sign":"F1a","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-041","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Fin d'une agglomération","Fin d'une zone 30","Rue barrée"],"answer":0,"explain":"Le signal F3a (nom de localité barré) indique la fin d'une agglomération.","sign":"F3a","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-042","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Vitesse conseillée de 30 km/h sur la prochaine rue","Commencement d'une zone où la vitesse est limitée à 30 km/h","Fin d'une zone 30"],"answer":1,"explain":"Le signal F4a indique le commencement d'une zone dans laquelle la vitesse est limitée à 30 km/h, jusqu'au signal de fin de zone (F4b).","sign":"F4a","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-043","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Vitesse minimale de 30 km/h","Début d'une zone 30","Fin d'une zone où la vitesse est limitée à 30 km/h"],"answer":2,"explain":"Le signal F4b est placé à chaque sortie d'une zone 30 et en indique la fin.","sign":"F4b","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-044","theme":"signalisation","q":"À partir d'où s'appliquent les règles spéciales de circulation annoncées par ce panneau ?","choices":["À partir de l'endroit où le signal est placé","À partir du premier péage","À 1 km après le signal"],"answer":0,"explain":"Le signal F5 indique le commencement d'une autoroute ou un accès à une autoroute. Les règles spéciales des autoroutes s'appliquent à partir de l'endroit où il est placé.","sign":"F5","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-045","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Autoroute en travaux","Fin d'autoroute","Sortie d'autoroute obligatoire pour les camions"],"answer":1,"explain":"Le signal F7 indique la fin de l'autoroute : les règles spéciales des autoroutes cessent de s'appliquer.","sign":"F7","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-046","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Parking pour voitures","Autoroute","Route pour automobiles"],"answer":2,"explain":"Le signal F9 indique une route pour automobiles ; ses règles spéciales s'appliquent à partir de l'endroit où il est placé. Sa fin est indiquée par le signal F11.","sign":"F9","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-047","theme":"signalisation","q":"Que signifie ce panneau rectangulaire à fond bleu ?","choices":["Voie publique à sens unique","Obligation de tourner dans le sens de la flèche","Direction de l'autoroute"],"answer":0,"explain":"Le signal F19 est un signal d'indication : il informe que la voie publique est à sens unique. Un panneau additionnel peut indiquer que les cyclistes y circulent dans les deux sens.","sign":"F19","ref":"Art. 65.2 et 71 AR 01/12/1975"},{"id":"SIG-048","theme":"signalisation","q":"Que signifie ce panneau ?","choices":["Carrefour en T","Voie sans issue","Fin de route prioritaire"],"answer":1,"explain":"Le signal F45 indique une voie sans issue (impasse). Le F45b précise qu'elle n'est sans issue que pour les véhicules, les piétons et cyclistes pouvant passer.","sign":"F45","ref":"Art. 71 AR 01/12/1975"},{"id":"SIG-049","theme":"signalisation","q":"Sous un panneau de signalisation est fixé un petit panneau rectangulaire à fond bleu avec une inscription blanche. À quoi sert-il ?","choices":["Il n'a qu'une valeur décorative","Il annule le signal","Il complète, précise ou limite la signification du signal"],"answer":2,"explain":"La signification d'un signal routier peut être complétée, précisée ou limitée par une inscription ou un symbole sur un panneau additionnel fixé en dessous (par ex. période de validité, catégorie de véhicules, distance).","ref":"Art. 65.2 AR 01/12/1975"},{"id":"SIG-050","theme":"signalisation","q":"Ce panneau est complété par un panneau additionnel « 200 m ». Que cela signifie-t-il ?","choices":["L'interdiction de dépasser commence à environ 200 m","L'interdiction de dépasser ne vaut que sur 200 m","On peut dépasser pendant encore 200 m maximum à vitesse réduite"],"answer":0,"explain":"Un signal d'interdiction peut être annoncé par un signal identique complété par un panneau additionnel indiquant la distance approximative à laquelle commence l'interdiction.","sign":"C35","ref":"Art. 68.2 AR 01/12/1975"},{"id":"SIG-051","theme":"signalisation","q":"Une ligne blanche continue sépare les deux sens de circulation. Puis-je la franchir pour dépasser un tracteur lent ?","choices":["Oui, si la visibilité est suffisante","Non, il est interdit de la franchir","Oui, si je rentre rapidement à droite"],"answer":1,"explain":"Une ligne continue ne peut être franchie par aucun conducteur. Lorsqu'elle sépare les deux sens de circulation, il est en outre interdit de circuler à sa gauche.","grave":true,"ref":"Art. 72.2 AR 01/12/1975"},{"id":"SIG-052","theme":"signalisation","q":"Pour quelle manœuvre ne puis-je PAS franchir une ligne blanche discontinue ?","choices":["Pour dépasser","Pour tourner à gauche","Pour rouler à cheval sur la ligne afin d'avoir plus de place"],"answer":2,"explain":"Une ligne discontinue ne peut être franchie que pour dépasser, tourner à gauche, faire demi-tour ou changer de bande. Il n'est pas permis d'y circuler à cheval.","ref":"Art. 72.3 AR 01/12/1975"},{"id":"SIG-053","theme":"signalisation","q":"Les traits de la ligne discontinue au milieu de la chaussée deviennent plus courts et plus rapprochés. Que cela annonce-t-il ?","choices":["L'approche d'une ligne continue","La fin de l'agglomération","Une bande réservée aux bus"],"answer":0,"explain":"Des traits plus courts et plus rapprochés annoncent l'approche d'une ligne continue. Il ne faut donc plus entamer de dépassement.","ref":"Art. 72.3 AR 01/12/1975"},{"id":"SIG-054","theme":"signalisation","q":"Au milieu de la chaussée, une ligne continue et une ligne discontinue sont juxtaposées. La ligne discontinue est de mon côté. Puis-je franchir ces lignes pour dépasser ?","choices":["Non, la ligne continue l'interdit dans tous les cas","Oui, je ne dois tenir compte que de la ligne de mon côté"],"answer":1,"explain":"Lorsque deux lignes sont juxtaposées, le conducteur ne tient compte que de celle qui se trouve de son côté. Celui qui les a franchies pour dépasser peut les refranchir pour reprendre sa place.","ref":"Art. 72.4 AR 01/12/1975"},{"id":"SIG-055","theme":"signalisation","q":"Dans une zone de travaux, des lignes orange sont tracées sur la chaussée en plus des anciennes lignes blanches. Lesquelles dois-je suivre ?","choices":["Les lignes blanches","Les lignes orange","Celles que je préfère"],"answer":1,"explain":"Les marques provisoires de couleur orange rendent sans effet les autres marques longitudinales blanches tracées au même endroit. Elles ont la même signification que les lignes blanches correspondantes.","ref":"Art. 73.1 et 73.4 AR 01/12/1975"},{"id":"SIG-058","theme":"signalisation","q":"À l'approche d'un carrefour, je suis sur une bande marquée d'une flèche de sélection vers la droite. Puis-je continuer tout droit au carrefour ?","choices":["Oui, si personne n'arrive","Non, je dois suivre la direction indiquée sur ma bande","Oui, si je mets mon clignotant"],"answer":1,"explain":"Les flèches de sélection marquent la bande à suivre pour prendre la direction indiquée. Au carrefour, le conducteur doit suivre la ou une des directions indiquées sur la bande où il se trouve.","ref":"Art. 77.1 AR 01/12/1975"},{"id":"SIG-059","theme":"signalisation","q":"Des flèches blanches obliques (flèches de rabattement) apparaissent le long d'une ligne discontinue. Que m'annoncent-elles ?","choices":["Une sortie d'autoroute","Un sens giratoire","La réduction du nombre de bandes de circulation dans mon sens"],"answer":2,"explain":"Les flèches de rabattement complètent la ligne discontinue annonçant une ligne continue et signalent la réduction du nombre de bandes utilisables dans le sens suivi.","ref":"Art. 77.2 AR 01/12/1975"},{"id":"SIG-060","theme":"signalisation","q":"Une zone d'évitement est marquée au sol par des lignes blanches parallèles obliques. Puis-je m'y arrêter un instant ?","choices":["Non, je ne peux ni y circuler, ni m'y arrêter, ni y stationner","Oui, si j'allume mes feux de détresse","Oui, pour moins de 2 minutes"],"answer":0,"explain":"Les îlots directionnels et zones d'évitement marqués par des lignes obliques ne peuvent être utilisés ni pour circuler, ni pour s'arrêter, ni pour stationner.","ref":"Art. 77.4 AR 01/12/1975"},{"id":"SIG-061","theme":"signalisation","q":"Des marques en damier composées de carrés blancs sont peintes sur le sol devant un passage à niveau. Puis-je m'arrêter sur ces marques ?","choices":["Non","Oui, si les barrières sont ouvertes"],"answer":0,"explain":"Les marques en damier délimitent notamment un site spécial franchissable ou un passage à niveau. L'arrêt et le stationnement y sont interdits.","grave":true,"ref":"Art. 77.8 AR 01/12/1975"},{"id":"SIG-062","theme":"signalisation","q":"Au feu rouge, une zone située entre deux lignes d'arrêt porte le symbole d'une bicyclette. En voiture, où dois-je m'arrêter ?","choices":["Devant la seconde ligne d'arrêt, dans la zone vélo","Devant la première ligne d'arrêt","N'importe où, si aucun cycliste n'est présent"],"answer":1,"explain":"La zone avancée est réservée aux cyclistes et conducteurs de cyclomoteurs à deux roues pendant la phase rouge. Les autres conducteurs doivent s'arrêter devant la première ligne d'arrêt.","ref":"Art. 77.6 AR 01/12/1975"},{"id":"SIG-063","theme":"signalisation","q":"Les panneaux ronds à bord rouge, comme celui-ci, appartiennent à quelle catégorie ?","choices":["Signaux de danger","Signaux d'indication","Signaux d'interdiction"],"answer":2,"explain":"Les signaux routiers se divisent en six catégories (danger, priorité, interdiction, obligation, arrêt et stationnement, indication). Le C43 (vitesse maximale) est un signal d'interdiction.","sign":"C43-70","ref":"Art. 65.1 et 68.3 AR 01/12/1975"},{"id":"STA-001","theme":"stationnement","q":"Je m'immobilise devant une boulangerie le temps de faire descendre un passager, puis je repars aussitôt. Ma voiture était :","choices":["À l'arrêt","En stationnement"],"answer":0,"explain":"Un véhicule est « à l'arrêt » lorsqu'il est immobilisé pendant le temps requis pour l'embarquement ou le débarquement de personnes ou de choses.","ref":"Art. 2.22 AR 01/12/1975"},{"id":"STA-002","theme":"stationnement","q":"Je laisse ma voiture devant une boulangerie pendant que j'achète du pain. Ma voiture est :","choices":["À l'arrêt","En stationnement"],"answer":1,"explain":"Dès que l'immobilisation dépasse le temps nécessaire pour charger ou décharger des personnes ou des choses, il s'agit de stationnement.","ref":"Art. 2.23 AR 01/12/1975"},{"id":"STA-003","theme":"stationnement","q":"Je recharge ma voiture électrique à une borne sur la voie publique. Juridiquement, ma voiture est :","choices":["À l'arrêt","En circulation","En stationnement"],"answer":2,"explain":"Le code précise que faire le plein de carburant ou charger la batterie d'un véhicule électrique est considéré comme du stationnement.","ref":"Art. 2.23 AR 01/12/1975"},{"id":"STA-004","theme":"stationnement","q":"Dans une rue à double sens de circulation, sans signalisation particulière, je veux stationner. De quel côté dois-je me ranger ?","choices":["Du côté gauche ou droit, au choix","Du côté droit par rapport à mon sens de marche"],"answer":1,"explain":"En règle générale, tout véhicule à l'arrêt ou en stationnement doit être rangé à droite par rapport à son sens de marche.","ref":"Art. 23.1.1° AR 01/12/1975"},{"id":"STA-005","theme":"stationnement","q":"Je circule dans une rue à sens unique. Puis-je stationner du côté gauche de la chaussée ?","choices":["Non, jamais","Oui, si la chaussée est à sens unique, je peux me ranger d'un côté ou de l'autre","Oui, mais uniquement la nuit"],"answer":1,"explain":"Sur une chaussée à sens unique, le véhicule peut être rangé de l'un ou de l'autre côté.","sign":"F19","ref":"Art. 23.1.1° AR 01/12/1975"},{"id":"STA-006","theme":"stationnement","q":"Je stationne sur un accotement que les piétons doivent emprunter. Quelle largeur minimale dois-je leur laisser du côté extérieur de la voie publique ?","choices":["1 mètre","2 mètres","1,50 mètre"],"answer":2,"explain":"Une bande praticable d'au moins 1,50 m doit rester disponible pour les piétons du côté extérieur de la voie publique.","ref":"Art. 23.1.2° AR 01/12/1975"},{"id":"STA-007","theme":"stationnement","q":"L'accotement de plain-pied est trop étroit pour accueillir entièrement ma voiture. Comment dois-je stationner ?","choices":["Partiellement sur l'accotement et partiellement sur la chaussée","Entièrement sur la chaussée","Je ne peux pas stationner à cet endroit"],"answer":0,"explain":"Si l'accotement n'est pas suffisamment large, le véhicule en stationnement doit être rangé en partie sur l'accotement et en partie sur la chaussée.","ref":"Art. 23.1.2° AR 01/12/1975"},{"id":"STA-008","theme":"stationnement","q":"Je stationne sur la chaussée, sans marquage particulier. Comment dois-je placer ma voiture ?","choices":["En épi, pour gagner de la place","Parallèlement au bord de la chaussée, en une seule file, le plus loin possible de l'axe"],"answer":1,"explain":"Sur la chaussée, le véhicule doit être placé le plus loin possible de l'axe, parallèlement au bord (sauf aménagement particulier) et en une seule file.","ref":"Art. 23.2 AR 01/12/1975"},{"id":"STA-009","theme":"stationnement","q":"Dans une agglomération, sans réglementation locale, puis-je stationner ma voiture sur le trottoir ?","choices":["Oui, si je laisse 1,50 m aux piétons","Oui, pour moins de 15 minutes","Non"],"answer":2,"explain":"L'arrêt et le stationnement sont interdits sur les trottoirs et, en agglomération, sur les accotements en saillie, sauf réglementation locale.","ref":"Art. 24.1° AR 01/12/1975"},{"id":"STA-010","theme":"stationnement","q":"Je dépose un passager en m'arrêtant quelques secondes sur une piste cyclable. Est-ce autorisé ?","choices":["Oui, car il s'agit d'un simple arrêt","Non, l'arrêt et le stationnement y sont interdits"],"answer":1,"explain":"L'arrêt comme le stationnement sont interdits sur les pistes cyclables : on force les cyclistes à se déporter sur la chaussée.","grave":true,"ref":"Art. 24.2° AR 01/12/1975"},{"id":"STA-011","theme":"stationnement","q":"À quelle distance minimale en deçà d'un passage pour piétons puis-je m'arrêter ou stationner sur la chaussée ?","choices":["3 mètres","5 mètres","10 mètres"],"answer":1,"explain":"L'arrêt et le stationnement sont interdits sur les passages pour piétons et sur la chaussée à moins de 5 m en deçà de ces passages, pour préserver la visibilité.","grave":true,"ref":"Art. 24.4° AR 01/12/1975"},{"id":"STA-012","theme":"stationnement","q":"Puis-je m'arrêter sur un passage à niveau pour laisser descendre un passager ?","choices":["Oui, si les barrières sont levées","Oui, si aucun train n'est en vue","Non, jamais"],"answer":2,"explain":"L'arrêt et le stationnement sont interdits sur les passages à niveau.","grave":true,"ref":"Art. 24.3° AR 01/12/1975"},{"id":"STA-013","theme":"stationnement","q":"Hors agglomération, je veux m'arrêter sur la chaussée juste après le sommet d'une côte où la visibilité est mauvaise. Est-ce autorisé ?","choices":["Non","Oui, si j'allume mes feux de détresse"],"answer":0,"explain":"L'arrêt et le stationnement sont interdits sur la chaussée à proximité du sommet d'une côte et dans un virage lorsque la visibilité est insuffisante.","grave":true,"ref":"Art. 24.6° AR 01/12/1975"},{"id":"STA-014","theme":"stationnement","q":"Sauf réglementation locale, à quelle distance minimale d'un carrefour puis-je m'arrêter ou stationner ?","choices":["10 mètres du centre du carrefour","5 mètres du prolongement du bord le plus rapproché de la chaussée transversale","15 mètres de tout panneau de priorité"],"answer":1,"explain":"Aux abords des carrefours, l'arrêt et le stationnement sont interdits à moins de 5 m du prolongement du bord le plus rapproché de la chaussée transversale.","grave":true,"ref":"Art. 24.7° AR 01/12/1975"},{"id":"STA-015","theme":"stationnement","q":"Sauf réglementation locale, je ne peux pas m'arrêter ni stationner à moins de … en deçà des feux de signalisation placés à un carrefour.","choices":["5 mètres","10 mètres","20 mètres"],"answer":2,"explain":"L'arrêt et le stationnement sont interdits à moins de 20 m en deçà des signaux lumineux de circulation, pour ne pas les masquer.","sign":"FEU-rouge","ref":"Art. 24.8° AR 01/12/1975"},{"id":"STA-016","theme":"stationnement","q":"Je conduis une voiture de 1,50 m de haut. Puis-je m'arrêter à 10 m en deçà d'un panneau routier dont le bord inférieur est à 2,20 m au-dessus de la chaussée ?","choices":["Non, il faut toujours 20 mètres","Oui"],"answer":1,"explain":"L'interdiction à moins de 20 m en deçà des signaux routiers ne s'applique pas aux véhicules de 1,65 m maximum (chargement compris) si le bas du signal est à au moins 2 m du sol.","ref":"Art. 24.10° et dernier alinéa AR 01/12/1975"},{"id":"STA-017","theme":"stationnement","q":"Puis-je m'arrêter sur la chaussée dans un tunnel pour consulter mon GPS ?","choices":["Non","Oui, avec les feux de détresse"],"answer":0,"explain":"L'arrêt et le stationnement sont interdits sur la chaussée dans les passages inférieurs et dans les tunnels.","grave":true,"ref":"Art. 24.5° AR 01/12/1975"},{"id":"STA-018","theme":"stationnement","q":"Je me gare derrière une autre voiture. Quelle distance minimale dois-je laisser entre les deux véhicules ?","choices":["50 centimètres","2 mètres","1 mètre"],"answer":2,"explain":"Il est interdit de stationner à moins de 1 m devant ou derrière un autre véhicule à l'arrêt ou en stationnement.","ref":"Art. 25.1.1° AR 01/12/1975"},{"id":"STA-019","theme":"stationnement","q":"Un panneau indique un arrêt de bus. À quelle distance de ce panneau le stationnement est-il interdit ?","choices":["À moins de 15 m de part et d'autre du panneau","À moins de 5 m avant le panneau seulement","À moins de 20 m après le panneau seulement"],"answer":0,"explain":"Le stationnement est interdit à moins de 15 m de part et d'autre d'un panneau d'arrêt d'autobus, de trolleybus ou de tram.","ref":"Art. 25.1.2° AR 01/12/1975"},{"id":"STA-020","theme":"stationnement","q":"Mon numéro d'immatriculation est reproduit lisiblement sur la porte de mon garage. Puis-je stationner devant cette entrée carrossable ?","choices":["Non, personne ne peut y stationner","Oui"],"answer":1,"explain":"Le stationnement devant les accès carrossables est interdit, sauf pour le véhicule dont le signe d'immatriculation est reproduit lisiblement à cet accès.","ref":"Art. 25.1.3° AR 01/12/1975"},{"id":"STA-021","theme":"stationnement","q":"Si je stationne ici, la largeur du passage libre sur la chaussée sera de 2,50 m. Est-ce permis ?","choices":["Non, il faut laisser au moins 3 m de passage libre","Oui, une voiture passe en 2,50 m"],"answer":0,"explain":"Le stationnement est interdit lorsque la largeur du passage libre sur la chaussée serait réduite à moins de 3 m.","ref":"Art. 25.1.7° AR 01/12/1975"},{"id":"STA-022","theme":"stationnement","q":"Hors agglomération, je circule sur une route signalée par ce panneau. Puis-je stationner sur la chaussée ?","choices":["Oui, du côté droit","Non"],"answer":1,"explain":"En dehors des agglomérations, le stationnement est interdit sur la chaussée d'une voie publique pourvue du signal B9 (route prioritaire).","sign":"B9","ref":"Art. 25.1.8° AR 01/12/1975"},{"id":"STA-023","theme":"stationnement","q":"Une ligne jaune discontinue est tracée le long de la bordure du trottoir. Que signifie-t-elle ?","choices":["L'arrêt est interdit, mais le stationnement est autorisé","Le stationnement est interdit sur la chaussée le long de cette ligne","Le stationnement est réservé aux livraisons"],"answer":1,"explain":"Le stationnement est interdit sur la chaussée le long de la ligne discontinue jaune tracée au bord de la chaussée ou du trottoir ; l'arrêt reste possible.","ref":"Art. 25.1.10° et 75.1.2° AR 01/12/1975"},{"id":"STA-024","theme":"stationnement","q":"Je ne possède pas de carte spéciale pour personnes handicapées. Puis-je stationner 5 minutes sur un emplacement réservé aux personnes handicapées ?","choices":["Oui, si je reste près de ma voiture","Non"],"answer":1,"explain":"Ces emplacements sont réservés aux véhicules utilisés par des personnes handicapées titulaires de la carte spéciale, apposée derrière le pare-brise.","ref":"Art. 25.1.14° et 27bis AR 01/12/1975"},{"id":"STA-025","theme":"stationnement","q":"Que signifie ce panneau ?","choices":["Stationnement interdit, l'arrêt reste permis","Arrêt et stationnement interdits","Stationnement à durée limitée"],"answer":0,"explain":"Le signal E1 interdit le stationnement ; s'arrêter pour charger ou décharger des personnes ou des choses reste autorisé.","sign":"E1","ref":"Art. 70.2.1.1° AR 01/12/1975"},{"id":"STA-026","theme":"stationnement","q":"Je souhaite déposer rapidement un ami à hauteur de ce panneau. Est-ce autorisé ?","choices":["Oui, puisque c'est un simple arrêt","Non, l'arrêt est aussi interdit"],"answer":1,"explain":"Le signal E3 interdit à la fois l'arrêt et le stationnement.","sign":"E3","ref":"Art. 70.2.1.1° AR 01/12/1975"},{"id":"STA-027","theme":"stationnement","q":"Sauf indication contraire, jusqu'où s'applique un signal E1 placé dans une rue ?","choices":["Des deux côtés de la rue, sur 100 mètres","Jusqu'au prochain signal F3a","Du côté où il est placé, jusqu'au prochain carrefour"],"answer":2,"explain":"Les signaux E1, E3 et E9 ont effet du côté de la voie publique où ils sont placés, à partir du signal jusqu'au prochain carrefour.","sign":"E1","ref":"Art. 70.2.2.1° AR 01/12/1975"},{"id":"STA-028","theme":"stationnement","q":"Sur une chaussée divisée en bandes de circulation, je vois ce panneau. Puis-je stationner sur la chaussée ?","choices":["Non, jamais sur une chaussée à bandes","Oui, à cet endroit le stationnement est autorisé"],"answer":1,"explain":"Le stationnement est normalement interdit sur une chaussée divisée en bandes de circulation, sauf aux endroits pourvus du signal E9a ou E9b.","sign":"E9a","ref":"Art. 25.1.9° et 70.2.1.3° AR 01/12/1975"},{"id":"STA-029","theme":"stationnement","q":"En zone bleue, sans indication particulière, quand le disque de stationnement est-il obligatoire et pour quelle durée maximale ?","choices":["Tous les jours de 8 h à 20 h, 3 heures maximum","Les jours ouvrables de 9 h à 18 h, 2 heures maximum","Les jours ouvrables de 9 h à 18 h, 1 heure maximum"],"answer":1,"explain":"Sauf modalités particulières indiquées, le disque est obligatoire de 9 h à 18 h les jours ouvrables, pour une durée maximale de 2 heures.","ref":"Art. 27.1.2 AR 01/12/1975"},{"id":"STA-030","theme":"stationnement","q":"J'arrive en zone bleue à 10 h 05. Sur quelle heure dois-je placer la flèche de mon disque ?","choices":["10 h 00","12 h 00","10 h 30"],"answer":2,"explain":"La flèche du disque doit être placée sur le trait qui suit l'heure d'arrivée (les traits sont par demi-heure).","ref":"Art. 27.1.2 AR 01/12/1975"},{"id":"STA-031","theme":"stationnement","q":"En zone bleue, le parcmètre de l'emplacement où je me gare est hors d'usage. Que dois-je faire ?","choices":["Utiliser mon disque de stationnement","Rien, le stationnement est alors gratuit et illimité"],"answer":0,"explain":"Lorsque le parcmètre ou l'horodateur est hors d'usage, le disque de stationnement doit être utilisé selon les règles de la zone bleue.","ref":"Art. 27.3.1.2° AR 01/12/1975"},{"id":"STA-032","theme":"stationnement","q":"Dans une agglomération où le stationnement alterné semi-mensuel s'applique, de quel côté puis-je stationner le 10 du mois ?","choices":["Du côté des numéros pairs","Du côté des numéros impairs","Des deux côtés"],"answer":1,"explain":"Du 1er au 15 du mois, le stationnement n'est autorisé que du côté des immeubles à numéros impairs ; du 16 à la fin du mois, du côté des numéros pairs.","ref":"Art. 26.1 AR 01/12/1975"},{"id":"STA-033","theme":"stationnement","q":"En stationnement alterné semi-mensuel, quand dois-je changer ma voiture de côté ?","choices":["Le dernier jour de la période, entre 19 h 30 et 20 h","Le premier jour de la nouvelle période, avant 9 h"],"answer":0,"explain":"Le changement de côté doit se faire le dernier jour de chaque période entre 19 h 30 et 20 h.","ref":"Art. 26.1 et 70.2.1.2° AR 01/12/1975"},{"id":"STA-034","theme":"stationnement","q":"Je suis stationné le long du trottoir et je veux sortir de ma voiture côté chaussée. Que dois-je faire avant d'ouvrir ma portière ?","choices":["Rien, les autres usagers doivent s'écarter des voitures stationnées","M'assurer qu'aucun usager, notamment un cycliste, ne risque d'être mis en danger ou gêné"],"answer":1,"explain":"Il est interdit d'ouvrir une portière ou de descendre d'un véhicule sans s'être assuré que cela ne crée ni danger ni gêne, en particulier pour les piétons et les deux-roues.","grave":true,"ref":"Art. 28 AR 01/12/1975"},{"id":"STA-036","theme":"stationnement","q":"Puis-je m'arrêter ou stationner sur des marques blanches obliques parallèles (zone d'évitement) tracées sur la chaussée ?","choices":["Oui, pour un arrêt bref","Non"],"answer":1,"explain":"Les conducteurs ne peuvent ni circuler, ni s'arrêter, ni stationner sur les îlots directionnels et zones d'évitement marqués par des lignes obliques blanches.","ref":"Art. 77.4 AR 01/12/1975"},{"id":"USR-001","theme":"usagers","q":"Le feu est vert et je tourne à droite. Un piéton traverse la rue dans laquelle je m'engage. Que dois-je faire ?","choices":["Passer avant lui, car mon feu est vert","Lui céder le passage","Klaxonner pour qu'il se presse"],"answer":1,"explain":"Le conducteur qui change de direction doit céder le passage aux piétons qui traversent la chaussée sur laquelle il va s'engager, même si son feu est vert.","grave":true,"sign":"FEU-vert","ref":"Art. 19.5 AR 01/12/1975"},{"id":"USR-002","theme":"usagers","q":"Je tourne à gauche à un carrefour. Un piéton traverse la chaussée dans laquelle je m'engage. Puis-je passer devant lui puisqu'il ne marche pas sur un passage pour piétons ?","choices":["Oui","Non, je dois lui céder le passage"],"answer":1,"explain":"Le conducteur qui change de direction doit céder le passage aux piétons qui traversent la chaussée sur laquelle il va s'engager, qu'il y ait ou non un passage pour piétons.","grave":true,"ref":"Art. 19.5 AR 01/12/1975"},{"id":"USR-003","theme":"usagers","q":"J'approche d'un passage pour piétons sans feux ni agent. Un piéton attend au bord du trottoir, visiblement sur le point de traverser. Je dois…","choices":["continuer : il n'est pas encore engagé","ralentir, mais je reste prioritaire","lui céder le passage"],"answer":2,"explain":"Aux passages pour piétons non réglés par des feux ou un agent, le conducteur s'approche à allure modérée et cède le passage aux piétons engagés ou sur le point de s'y engager.","grave":true,"ref":"Art. 40.4.2 AR 01/12/1975"},{"id":"USR-004","theme":"usagers","q":"Mon feu passe au vert. Un piéton, engagé régulièrement pendant son feu vert, n'a pas encore fini de traverser devant moi. Que dois-je faire ?","choices":["Le laisser achever sa traversée","Démarrer : le piéton doit se dépêcher","Le contourner par l'arrière"],"answer":0,"explain":"Même si la circulation est ouverte dans son sens, le conducteur doit permettre aux piétons régulièrement engagés d'achever leur traversée à allure normale.","grave":true,"sign":"FEU-vert","ref":"Art. 40.4.1 AR 01/12/1975"},{"id":"USR-005","theme":"usagers","q":"Je m'arrête à un feu rouge. Juste avant le carrefour se trouve un passage pour piétons. Où dois-je m'arrêter ?","choices":["Sur le passage pour piétons, au plus près du feu","En deçà du passage pour piétons","Peu importe, tant que je ne franchis pas le feu"],"answer":1,"explain":"Lorsque la circulation est fermée dans son sens, le conducteur doit de toute manière s'arrêter en deçà du passage pour piétons.","sign":"FEU-rouge","ref":"Art. 40.4.1 AR 01/12/1975"},{"id":"USR-006","theme":"usagers","q":"La circulation est très dense : si j'avance, je risque d'être immobilisé sur le passage pour piétons. Puis-je m'y engager ?","choices":["Oui, si mon feu est vert","Non"],"answer":1,"explain":"Le conducteur ne peut s'engager sur un passage pour piétons si l'encombrement est tel qu'il y serait vraisemblablement immobilisé.","ref":"Art. 40.5 AR 01/12/1975"},{"id":"USR-007","theme":"usagers","q":"En agglomération, un piéton marche sur la chaussée car il n'y a pas de trottoir. Quelle distance latérale minimale dois-je laisser en le dépassant ?","choices":["50 centimètres","2 mètres","1 mètre"],"answer":2,"explain":"Le conducteur laisse au moins 1 mètre entre son véhicule et un piéton qui circule sur la chaussée (au moins 1,5 m hors agglomération). Sinon, il roule à l'allure du pas et s'arrête au besoin.","ref":"Art. 40.7 AR 01/12/1975"},{"id":"USR-008","theme":"usagers","q":"Hors agglomération, je vais dépasser un cycliste. Quelle distance latérale minimale dois-je laisser ?","choices":["1,5 mètre","1 mètre","50 centimètres"],"answer":0,"explain":"Le conducteur laisse au moins 1 m entre son véhicule et le cycliste ; en dehors des agglomérations, cette distance est d'au moins 1,5 m.","ref":"Art. 40ter AR 01/12/1975"},{"id":"USR-009","theme":"usagers","q":"Une voiture en stationnement occupe le trottoir et oblige les piétons à la contourner par la chaussée. Un piéton la contourne au moment où je passe et je ne peux pas laisser 1 mètre d'espace. Je dois…","choices":["passer à l'allure du pas","klaxonner et passer normalement","accélérer pour passer avant lui"],"answer":0,"explain":"Près d'un obstacle que les piétons contournent par la chaussée, il faut laisser au moins 1 m ; si c'est impossible et qu'un piéton est à hauteur de l'obstacle, on ne passe qu'à l'allure du pas.","ref":"Art. 40.6 AR 01/12/1975"},{"id":"USR-010","theme":"usagers","q":"Une personne munie d'une canne blanche se tient au bord du trottoir, près du carrefour que j'aborde. Que dois-je faire ?","choices":["Klaxonner pour la prévenir de mon arrivée","Redoubler de prudence, ralentir et au besoin m'arrêter","Rien de particulier si elle n'est pas sur un passage pour piétons"],"answer":1,"explain":"Le conducteur doit redoubler de prudence en présence de personnes handicapées, notamment les aveugles munis d'une canne blanche ou jaune ; il doit ralentir et au besoin s'arrêter.","grave":true,"ref":"Art. 40.2 AR 01/12/1975"},{"id":"USR-011","theme":"usagers","q":"Un autobus est arrêté à un arrêt sans refuge, du côté où je roule. Des voyageurs descendent pour rejoindre le trottoir. Que dois-je faire ?","choices":["M'arrêter pour leur permettre de gagner le trottoir en sécurité","Le longer à vitesse modérée sans m'arrêter","Klaxonner pour signaler ma présence"],"answer":0,"explain":"S'il n'y a pas de refuge à l'arrêt, le conducteur qui circule du côté de l'embarquement ou du débarquement doit s'arrêter et ne repartir qu'à allure modérée.","grave":true,"ref":"Art. 40.3.2 AR 01/12/1975"},{"id":"USR-012","theme":"usagers","q":"Je longe un tram arrêté pour l'embarquement des voyageurs ; un refuge sépare les voyageurs de ma voie. Je dois…","choices":["garder ma vitesse, les voyageurs sont protégés","modérer ma vitesse"],"answer":1,"explain":"Le conducteur doit modérer sa vitesse pour longer un autocar, un autobus, un trolleybus, un minibus ou un véhicule sur rails arrêté pour l'embarquement ou le débarquement des voyageurs.","ref":"Art. 40.3.1 AR 01/12/1975"},{"id":"USR-013","theme":"usagers","q":"En agglomération, je roule dans le même sens qu'un autobus arrêté à son arrêt. Il actionne son clignotant gauche pour repartir. Que dois-je faire ?","choices":["Le dépasser rapidement avant qu'il ne démarre","Klaxonner : il doit me céder le passage","Ralentir et au besoin m'arrêter pour le laisser partir"],"answer":2,"explain":"En agglomération, le conducteur qui suit la même direction doit permettre à l'autobus ou au trolleybus de quitter son arrêt lorsqu'il l'a indiqué au moyen de ses clignotants.","ref":"Art. 39 AR 01/12/1975"},{"id":"USR-014","theme":"usagers","q":"La règle qui oblige à laisser un autobus quitter son arrêt lorsqu'il a mis son clignotant s'applique…","choices":["partout","uniquement dans les agglomérations","uniquement sur les routes limitées à 50 km/h"],"answer":1,"explain":"L'article 39 vise les conducteurs qui circulent dans les agglomérations ; il y déroge à l'obligation pour l'autobus de céder le passage lors de sa manœuvre.","sign":"F1a","ref":"Art. 39 AR 01/12/1975"},{"id":"USR-015","theme":"usagers","q":"Je m'approche d'un véhicule de transport scolaire arrêté, portant le panneau réglementaire et dont tous les clignotants fonctionnent. Que signifie ce signal et que dois-je faire ?","choices":["Il est en panne : je le dépasse normalement","Il va repartir : je dois lui céder le passage","Des enfants vont monter ou descendre : je ralentis fortement et je m'arrête au besoin"],"answer":2,"explain":"Quand le conducteur du véhicule de transport scolaire fait fonctionner tous les feux indicateurs de direction, les enfants vont embarquer ou débarquer : il faut redoubler de prudence, ralentir fortement et au besoin s'arrêter.","grave":true,"ref":"Art. 39bis.2 AR 01/12/1975"},{"id":"USR-016","theme":"usagers","q":"Près d'une école, une surveillante habilitée lève un disque rouge et blanc (signal C3) pour faire traverser des enfants. Que dois-je faire ?","choices":["M'arrêter et obéir à ses indications","Passer si aucun enfant n'est encore sur la chaussée","Passer si mon feu est vert"],"answer":0,"explain":"Les usagers doivent obéir aux indications des surveillants habilités qui assurent la traversée d'enfants ; pour arrêter la circulation, ceux-ci utilisent un disque reproduisant le signal C3.","grave":true,"ref":"Art. 40bis.2 et 40bis.3 AR 01/12/1975"},{"id":"USR-017","theme":"usagers","q":"Un groupe d'écoliers en rangs, conduit par un guide, traverse la chaussée. Il reste un espace entre deux rangs. Puis-je y passer ?","choices":["Oui, si je roule lentement","Non, il est interdit de couper le groupe"],"answer":1,"explain":"Il est interdit de couper un groupe d'enfants, d'écoliers, de personnes handicapées ou âgées en rangs sous la conduite d'un guide ou traversant sous la conduite d'un surveillant.","grave":true,"ref":"Art. 40bis.1 AR 01/12/1975"},{"id":"USR-019","theme":"usagers","q":"Dans une zone de rencontre, des enfants jouent au ballon au milieu de la rue. Est-ce autorisé ?","choices":["Non, ils doivent rester sur le côté","Oui, les piétons peuvent utiliser toute la largeur et les jeux sont autorisés"],"answer":1,"explain":"Dans ces zones, les piétons peuvent utiliser toute la largeur de la voie publique et les jeux sont autorisés. Les conducteurs ne peuvent ni les mettre en danger ni les gêner et doivent s'arrêter au besoin.","ref":"Art. 22bis, 1° et 2° AR 01/12/1975"},{"id":"USR-020","theme":"usagers","q":"Dans une zone résidentielle, où puis-je stationner ?","choices":["Partout, du côté droit","Uniquement aux emplacements marqués d'un « P » ou là où un signal l'autorise","Nulle part, le stationnement y est toujours interdit"],"answer":1,"explain":"Le stationnement est interdit en zone résidentielle ou de rencontre, sauf aux emplacements délimités portant la lettre « P » et aux endroits où un signal l'autorise.","ref":"Art. 22bis, 4° AR 01/12/1975"},{"id":"USR-021","theme":"usagers","q":"Je suis autorisé à circuler dans une zone piétonne pour une livraison. Comment dois-je rouler ?","choices":["À 20 km/h maximum","À 30 km/h maximum","À l'allure du pas, en cédant le passage aux piétons"],"answer":2,"explain":"Dans une zone piétonne, les conducteurs admis circulent à l'allure du pas, cèdent le passage aux piétons et s'arrêtent au besoin.","ref":"Art. 22sexies.2 AR 01/12/1975"},{"id":"USR-022","theme":"usagers","q":"Mon garage se trouve dans une zone piétonne et n'est accessible qu'en la traversant. Puis-je y accéder en voiture ?","choices":["Oui, avec un laissez-passer délivré par le bourgmestre ou son délégué apposé sur le pare-brise","Non, jamais","Oui, sans aucune formalité"],"answer":0,"explain":"Les conducteurs dont le garage n'est accessible qu'en traversant la zone piétonne peuvent y accéder, à condition d'apposer derrière le pare-brise un laissez-passer délivré par le bourgmestre ou son délégué.","ref":"Art. 22sexies.1 AR 01/12/1975"},{"id":"USR-023","theme":"usagers","q":"Puis-je stationner dans une zone piétonne si je n'y gêne personne ?","choices":["Oui","Non, le stationnement y est interdit"],"answer":1,"explain":"Le stationnement est interdit dans les zones piétonnes.","ref":"Art. 22sexies.2 AR 01/12/1975"},{"id":"USR-024","theme":"usagers","q":"Pour gagner du temps, je voudrais emprunter en voiture un chemin réservé aux piétons, cyclistes, cavaliers et speed pedelecs (signal F99a). Est-ce permis ?","choices":["Oui, à 30 km/h maximum","Non, sauf autorisation du gestionnaire (riverains, fournisseurs…) ou véhicule prioritaire en mission","Oui, si je cède le passage aux piétons"],"answer":1,"explain":"Seuls les usagers dont le symbole figure sur le signal peuvent circuler sur ces chemins, outre les véhicules prioritaires en mission et certains véhicules autorisés par le gestionnaire (riverains, fournisseurs, entretien, immondices).","ref":"Art. 22quinquies.1 AR 01/12/1975"},{"id":"USR-025","theme":"usagers","q":"Quelle est la vitesse maximale sur un chemin réservé aux piétons, cyclistes, cavaliers et conducteurs de speed pedelecs ?","choices":["20 km/h","50 km/h","30 km/h"],"answer":2,"explain":"Sur ces chemins, la vitesse est limitée à 30 km/h.","ref":"Art. 22quinquies.4 AR 01/12/1975"},{"id":"USR-027","theme":"usagers","q":"Dans une zone cyclable, je roule derrière un cycliste qui avance à 20 km/h. Puis-je le dépasser ?","choices":["Oui, en laissant 1 mètre d'écart","Oui, s'il roule au milieu de la chaussée","Non"],"answer":2,"explain":"Une zone cyclable est accessible aux véhicules à moteur, mais ceux-ci ne peuvent pas y dépasser les cyclistes (ni les conducteurs de speed pedelecs, qui leur sont assimilés).","ref":"Art. 22novies AR 01/12/1975"},{"id":"USR-028","theme":"usagers","q":"Quelle est la vitesse maximale autorisée dans une zone cyclable ?","choices":["30 km/h","50 km/h","20 km/h"],"answer":0,"explain":"Dans une zone cyclable, la vitesse ne peut jamais être supérieure à 30 km/h.","ref":"Art. 22novies AR 01/12/1975"},{"id":"USR-029","theme":"usagers","q":"Dans une zone cyclable à double sens, quelle partie de la chaussée un cycliste peut-il utiliser ?","choices":["Uniquement le bord droit","La moitié droite de la chaussée","Toute la largeur de la chaussée"],"answer":1,"explain":"Le cycliste peut utiliser toute la largeur si la chaussée n'est ouverte qu'à son sens, et la moitié droite si elle est ouverte aux deux sens de circulation.","ref":"Art. 22novies AR 01/12/1975"},{"id":"USR-030","theme":"usagers","q":"Au feu rouge, une zone avancée pour cyclistes (bicyclette peinte entre deux lignes d'arrêt) se trouve devant moi. Où dois-je m'arrêter ?","choices":["Devant la première ligne d'arrêt","Dans la zone, si aucun cycliste n'est présent","Devant la seconde ligne d'arrêt"],"answer":0,"explain":"Pendant la phase rouge, la zone avancée est réservée aux cyclistes et cyclomotoristes à deux roues ; les autres conducteurs s'arrêtent devant la première ligne d'arrêt.","sign":"FEU-rouge","ref":"Art. 77.6 AR 01/12/1975"},{"id":"USR-031","theme":"usagers","q":"Je m'engage dans une rue à sens unique dont le signal est complété par un panneau additionnel montrant une bicyclette et deux flèches opposées. Que signifie-t-il ?","choices":["Les cyclistes peuvent y circuler dans les deux sens : je peux en croiser","Les cyclistes ne peuvent pas y entrer","Je peux circuler dans les deux sens si je suis prudent"],"answer":0,"explain":"Le panneau additionnel M4 complète le signal F19 lorsque les cyclistes sont autorisés à circuler dans les deux sens ; il faut donc s'attendre à croiser des cyclistes.","sign":"F19","ref":"Art. 71.3 et 65.2 AR 01/12/1975"},{"id":"USR-032","theme":"usagers","q":"À un feu rouge muni d'un panneau B22, un cycliste tourne à droite sans attendre le vert. Est-ce permis ?","choices":["Non, le feu rouge s'impose à tous","Oui, à condition qu'il cède le passage aux autres usagers"],"answer":1,"explain":"Le panneau B22 autorise les cyclistes et les conducteurs de speed pedelecs à franchir le feu rouge ou jaune-orange pour tourner à droite, à condition de céder le passage aux autres usagers.","sign":"FEU-rouge","ref":"Art. 61.5 et 67.3 AR 01/12/1975"},{"id":"USR-033","theme":"usagers","q":"Je tourne à droite. Un cycliste arrive derrière moi sur la piste cyclable et continue tout droit. Qui doit céder le passage ?","choices":["Le cycliste, car il est à ma droite","Celui qui arrive en dernier au carrefour","Moi"],"answer":2,"explain":"Le conducteur qui change de direction doit céder le passage aux conducteurs qui circulent sur les autres parties de la même voie publique, dont la piste cyclable.","grave":true,"ref":"Art. 19.4 AR 01/12/1975"},{"id":"USR-034","theme":"usagers","q":"Je sors de chez moi en voiture et je dois traverser une piste cyclable pour atteindre la chaussée. Un cycliste approche. Je dois…","choices":["lui céder le passage","passer avant lui, je suis déjà engagé","klaxonner pour le prévenir"],"answer":0,"explain":"Le conducteur qui traverse un trottoir ou une piste cyclable doit céder le passage aux usagers qui y circulent ; déboucher d'une propriété est en outre une manœuvre.","grave":true,"ref":"Art. 12.4 et 12.4bis AR 01/12/1975"},{"id":"USR-037","theme":"usagers","q":"En agglomération, deux cyclistes roulent côte à côte devant moi sur une chaussée large où l'on peut se croiser. Est-ce permis ?","choices":["Oui","Non, ils doivent toujours rouler en file"],"answer":0,"explain":"Les cyclistes peuvent rouler à deux de front sauf lorsque le croisement n'est pas possible. Hors agglomération, ils doivent se mettre en file à l'approche d'un véhicule venant de l'arrière.","ref":"Art. 43.2 AR 01/12/1975"},{"id":"USR-038","theme":"usagers","q":"Un enfant de 8 ans roule à vélo sur le trottoir en agglomération. Est-ce autorisé ?","choices":["Non, le trottoir est réservé aux piétons","Oui"],"answer":1,"explain":"Les cyclistes âgés de moins de 10 ans peuvent emprunter en toutes circonstances les trottoirs et les accotements en saillie.","ref":"Art. 9.1.2, 5° AR 01/12/1975"},{"id":"USR-040","theme":"usagers","q":"Deux cavaliers circulent côte à côte sur la chaussée. Est-ce autorisé ?","choices":["Non, ils doivent circuler en file","Oui"],"answer":1,"explain":"Les cavaliers qui empruntent la chaussée peuvent circuler à deux de front.","ref":"Art. 55.4 AR 01/12/1975"},{"id":"USR-041","theme":"usagers","q":"Je dépasse en agglomération l'utilisateur d'une trottinette électrique qui roule sur la chaussée. Quelles règles dois-je respecter à son égard ?","choices":["Celles applicables aux cyclistes, dont une distance latérale d'au moins 1 mètre","Celles applicables aux piétons uniquement","Aucune règle particulière : c'est un jouet"],"answer":0,"explain":"Les utilisateurs d'engins de déplacement motorisés (trottinettes électriques…) sont assimilés aux cyclistes ; les règles à respecter envers les cyclistes s'appliquent donc envers eux.","ref":"Art. 7bis et 40ter AR 01/12/1975"},{"id":"USR-042","theme":"usagers","q":"Sur une route limitée à 70 km/h, une piste cyclable signalée par le signal D7 longe la chaussée. Le conducteur d'un speed pedelec…","choices":["doit emprunter cette piste cyclable","doit rouler sur la chaussée","a le libre choix"],"answer":0,"explain":"Là où la vitesse autorisée dépasse 50 km/h, les conducteurs de speed pedelecs doivent emprunter la piste cyclable D7 (ou marquée) présente et praticable ; à 50 km/h ou moins, ils peuvent l'emprunter.","ref":"Art. 9.1.2, 2° AR 01/12/1975"},{"id":"USR-043","theme":"usagers","q":"Hors agglomération, sur une route sans trottoir ni accotement praticable, de quel côté dois-je m'attendre à voir des piétons marcher sur la chaussée ?","choices":["En principe à gauche, face aux véhicules","Toujours à droite","Au milieu de la chaussée"],"answer":0,"explain":"Sur la chaussée, les piétons se tiennent le plus près possible du bord et circulent à gauche par rapport à leur sens de marche, ou à droite si la sécurité le justifie.","ref":"Art. 42.1 AR 01/12/1975"},{"id":"USR-044","theme":"usagers","q":"Un véhicule portant un drapeau rouge annonce une course cycliste qui arrive en face. Que dois-je faire ?","choices":["Continuer prudemment en serrant à droite","M'écarter, dégager la chaussée et m'arrêter jusqu'au passage du véhicule au drapeau vert","M'arrêter seulement si un signaleur me le demande"],"answer":1,"explain":"À l'approche du véhicule d'ouverture au drapeau rouge, tout usager doit s'écarter, dégager la chaussée et s'arrêter ; il reste à l'arrêt jusqu'au passage du véhicule de fermeture au drapeau vert.","ref":"Art. 40quater AR 01/12/1975"},{"id":"VIT-001","theme":"vitesse","q":"Vous roulez en voiture dans une agglomération en Wallonie. Aucun panneau de vitesse n'est placé. Quelle est la vitesse maximale autorisée ?","choices":["30 km/h","70 km/h","50 km/h"],"answer":2,"explain":"En Région wallonne (comme en Flandre), la vitesse est limitée à 50 km/h dans les agglomérations, sauf autre limitation imposée par un signal C43.","sign":"F1a","ref":"Art. 11.1 AR 01/12/1975"},{"id":"VIT-002","theme":"vitesse","q":"Vous circulez dans une agglomération de la Région de Bruxelles-Capitale, sans panneau de vitesse particulier. Vous pouvez rouler au maximum à…","choices":["50 km/h","30 km/h"],"answer":1,"explain":"En Région de Bruxelles-Capitale, la règle générale en agglomération est 30 km/h ; un C43 peut toutefois imposer ou permettre une autre vitesse sur certaines voies.","ref":"Art. 11.1 (Région de Bruxelles-Capitale) AR 01/12/1975"},{"id":"VIT-003","theme":"vitesse","q":"Hors agglomération en Wallonie, sur une route ordinaire à une bande par sens, sans panneau de vitesse. Ma vitesse maximale est de…","choices":["70 km/h","90 km/h","120 km/h"],"answer":1,"explain":"En Région wallonne, hors agglomération, la vitesse est limitée à 90 km/h sur les voies publiques ordinaires (en Flandre, la règle générale est 70 km/h).","ref":"Art. 11.2 (Région wallonne) AR 01/12/1975"},{"id":"VIT-004","theme":"vitesse","q":"Hors agglomération en Flandre, sur une route ordinaire sans aucun panneau de vitesse, quelle est la vitesse maximale ?","choices":["70 km/h","90 km/h"],"answer":0,"explain":"En Région flamande, hors agglomération, la vitesse est limitée à 70 km/h, sauf si un C43 permet 90 km/h.","ref":"Art. 11.2 (Région flamande) AR 01/12/1975"},{"id":"VIT-005","theme":"vitesse","q":"Je roule en voiture sur l'autoroute, sans panneau de vitesse particulier. Ma vitesse maximale est de…","choices":["100 km/h","130 km/h","120 km/h"],"answer":2,"explain":"Sur autoroute, la vitesse est limitée à 120 km/h pour les voitures, sauf limitation inférieure indiquée par un C43.","sign":"F5","ref":"Art. 11.2.1° a) AR 01/12/1975"},{"id":"VIT-006","theme":"vitesse","q":"Hors agglomération, je roule sur une route à 2 x 2 bandes dont les sens de circulation sont séparés par une berme centrale (pas seulement par des marques). Ce n'est pas une autoroute. Ma vitesse maximale en voiture est de…","choices":["90 km/h","120 km/h","70 km/h"],"answer":1,"explain":"Sur une route d'au moins 2 bandes par sens dont les sens sont séparés autrement que par des marques routières (berme, glissière), la limite est de 120 km/h, comme sur autoroute.","ref":"Art. 11.2.1° b) AR 01/12/1975"},{"id":"VIT-007","theme":"vitesse","q":"Hors agglomération en Wallonie, sur une route à 2 x 2 bandes dont les sens de circulation sont séparés uniquement par des lignes blanches au sol, quelle est la vitesse maximale en voiture ?","choices":["120 km/h","70 km/h","90 km/h"],"answer":2,"explain":"Lorsque les sens de circulation ne sont séparés que par des marques routières, la limite est celle des routes ordinaires : 90 km/h en Wallonie.","ref":"Art. 11.2 (Région wallonne) 2° a) AR 01/12/1975"},{"id":"VIT-009","theme":"vitesse","q":"Je conduis une camionnette dont la masse maximale autorisée est de 5 tonnes. Sur l'autoroute, ma vitesse maximale est de…","choices":["120 km/h","90 km/h","100 km/h"],"answer":1,"explain":"Sur autoroute, les véhicules dont la masse maximale autorisée dépasse 3,5 tonnes sont limités à 90 km/h.","ref":"Art. 11.2.1° a) AR 01/12/1975"},{"id":"VIT-010","theme":"vitesse","q":"Vous entrez dans une zone signalée par ce panneau. Quelle est la vitesse maximale ?","choices":["30 km/h jusqu'au prochain carrefour","50 km/h, le panneau n'est qu'un conseil","30 km/h jusqu'au panneau de fin de zone"],"answer":2,"explain":"Le signal F4a marque le début d'une zone où la vitesse est limitée à 30 km/h ; la limite vaut jusqu'au signal F4b de fin de zone, même après les carrefours.","sign":"F4a","ref":"Art. 22quater et 71 AR 01/12/1975"},{"id":"VIT-011","theme":"vitesse","q":"Je viens de passer un panneau C43 « 70 » en agglomération, puis je traverse un carrefour sans voir d'autre panneau. Que se passe-t-il ?","choices":["La limite de 70 km/h reste valable jusqu'à la sortie de l'agglomération","La limite générale de l'agglomération s'applique à nouveau après le carrefour","Je peux rouler à 90 km/h"],"answer":1,"explain":"Un C43 (non zonal) vaut jusqu'au prochain carrefour inclus ; après, la vitesse générale de l'agglomération est de nouveau en vigueur.","sign":"C43-70","ref":"Art. 68 (C43) et 71 (F1a) AR 01/12/1975"},{"id":"VIT-012","theme":"vitesse","q":"Que signifie ce panneau ?","choices":["Vitesse minimale de 50 km/h","Interdiction de rouler à plus de 50 km/h","Fin de la limitation de vitesse à 50 km/h imposée par un C43"],"answer":2,"explain":"Le signal C45 indique la fin de la limitation de vitesse imposée par le signal C43 correspondant. Les règles générales de vitesse s'appliquent ensuite.","sign":"C45-50","ref":"Art. 68 (C45) AR 01/12/1975"},{"id":"VIT-013","theme":"vitesse","q":"Ce panneau est placé sur une route. Jusqu'où vaut-il, s'il n'est pas à validité zonale ?","choices":["Jusqu'au prochain carrefour inclus ou jusqu'à un autre C43","Jusqu'à la fin de la commune","Sur 1 kilomètre exactement"],"answer":0,"explain":"Le C43 interdit de dépasser la vitesse indiquée à partir du signal jusqu'au prochain carrefour inclus, jusqu'à un autre C43, ou jusqu'au signal de début ou de fin d'agglomération, de zone résidentielle, de rencontre ou piétonne.","sign":"C43-50","ref":"Art. 68 (C43) AR 01/12/1975"},{"id":"VIT-014","theme":"vitesse","q":"Un panneau C43 « 30 » est placé au-dessus du panneau de début d'agglomération. Que signifie cette combinaison ?","choices":["30 km/h jusqu'au premier carrefour seulement","30 km/h uniquement près des écoles","30 km/h sur toutes les voiries de l'agglomération"],"answer":2,"explain":"Le C43 « 30 » placé au-dessus du signal F1 (F1a/F1b) vaut sur l'ensemble des voiries comprises dans les limites de l'agglomération.","sign":"C43-30","ref":"Art. 68 (C43) AR 01/12/1975"},{"id":"VIT-015","theme":"vitesse","q":"Je suis en voiture dans une zone résidentielle (ou zone de rencontre). Quelle est la vitesse maximale ?","choices":["30 km/h","20 km/h","Au pas"],"answer":1,"explain":"Dans les zones résidentielles et de rencontre, la vitesse est limitée à 20 km/h ; les piétons peuvent utiliser toute la largeur de la voie publique.","ref":"Art. 22bis, 3° AR 01/12/1975"},{"id":"VIT-016","theme":"vitesse","q":"Dans une zone de rencontre, des enfants jouent au milieu de la rue. Que dois-je faire ?","choices":["Klaxonner pour qu'ils s'écartent, car la chaussée est pour les véhicules","Les contourner à 20 km/h sans ralentir","Ne pas les mettre en danger ni les gêner et, au besoin, m'arrêter"],"answer":2,"explain":"Dans les zones résidentielles et de rencontre, les jeux sont autorisés sur toute la largeur ; le conducteur ne peut mettre les piétons en danger ni les gêner, doit redoubler de prudence en présence d'enfants et s'arrêter au besoin.","grave":true,"ref":"Art. 22bis, 1° et 2° AR 01/12/1975"},{"id":"VIT-017","theme":"vitesse","q":"Comment est délimitée une zone « abords d'école » ?","choices":["Par les signaux F4a et F4b, avec le signal A23 associé au F4a","Uniquement par un marquage jaune au sol","Par un signal C3"],"answer":0,"explain":"Les abords d'école sont délimités par les signaux F4a (début) et F4b (fin) ; le signal A23 est associé au F4a. La vitesse y est donc limitée à 30 km/h.","sign":"F4a","ref":"Art. 2.37 et 22quater AR 01/12/1975"},{"id":"VIT-018","theme":"vitesse","q":"Je passe devant une école, dans une zone abords d'école délimitée par un F4a. Je peux rouler au maximum à…","choices":["50 km/h","20 km/h","30 km/h"],"answer":2,"explain":"Les abords d'école sont délimités par les signaux F4a et F4b : la vitesse y est limitée à 30 km/h. Excéder cette vitesse près d'une école met gravement en danger des enfants.","grave":true,"sign":"F4a","ref":"Art. 2.37 et 22quater AR 01/12/1975"},{"id":"VIT-019","theme":"vitesse","q":"J'aborde un dispositif surélevé (ralentisseur) annoncé par la signalisation. À quelle vitesse maximale dois-je le franchir ?","choices":["30 km/h","50 km/h","20 km/h"],"answer":0,"explain":"Les conducteurs doivent approcher ces dispositifs avec prudence et à allure modérée, de manière à les franchir à une vitesse n'excédant pas 30 km/h.","ref":"Art. 22ter.1, 1° AR 01/12/1975"},{"id":"VIT-020","theme":"vitesse","q":"La limite est de 90 km/h mais il pleut fortement et la visibilité est réduite. Que dois-je faire ?","choices":["Je peux rouler à 90 km/h puisque c'est autorisé","Je dois rouler exactement à 50 km/h","Je dois adapter ma vitesse aux conditions climatiques et à la visibilité"],"answer":2,"explain":"La vitesse maximale n'est pas une vitesse obligatoire : tout conducteur doit régler sa vitesse selon les conditions climatiques, le champ de visibilité, l'état de la route, etc.","sign":"C43-90","ref":"Art. 10.1, 1° AR 01/12/1975"},{"id":"VIT-021","theme":"vitesse","q":"La nuit, sur une route de campagne non éclairée, je roule en feux de croisement. Je dois pouvoir m'arrêter…","choices":["Devant tout obstacle prévisible","Seulement si la route est éclairée","Dans une distance de 100 m quelle que soit ma vitesse"],"answer":0,"explain":"Le conducteur doit en toute circonstance pouvoir s'arrêter devant un obstacle prévisible : la vitesse doit donc être adaptée à la portée de l'éclairage et au champ de visibilité.","grave":true,"ref":"Art. 10.1, 3° AR 01/12/1975"},{"id":"VIT-022","theme":"vitesse","q":"J'approche d'une sortie d'école à l'heure où les enfants sortent. Même si la limite affichée est respectée, je dois…","choices":["Garder ma vitesse, puisque je respecte la limite","Klaxonner pour prévenir les enfants","Régler ma vitesse en tenant compte en particulier des usagers les plus vulnérables"],"answer":2,"explain":"La vitesse doit être réglée en fonction de la présence d'autres usagers et en particulier des plus vulnérables ; elle ne peut jamais être une cause d'accident.","grave":true,"ref":"Art. 10.1, 1° AR 01/12/1975"},{"id":"VIT-023","theme":"vitesse","q":"Ma voiture est lourdement chargée (coffre plein et galerie de toit). Dois-je en tenir compte dans ma vitesse ?","choices":["Oui, l'état et le chargement du véhicule doivent être pris en compte","Non, seuls les panneaux comptent"],"answer":0,"explain":"Le code impose de régler sa vitesse notamment en fonction de l'état et du chargement du véhicule.","ref":"Art. 10.1, 1° AR 01/12/1975"},{"id":"VIT-024","theme":"vitesse","q":"Quelle distance dois-je laisser avec le véhicule qui me précède ?","choices":["Toujours 5 mètres","Une distance de sécurité suffisante compte tenu de ma vitesse","Aucune distance n'est imposée aux voitures"],"answer":1,"explain":"Le conducteur doit, compte tenu de sa vitesse, maintenir une distance de sécurité suffisante avec le véhicule qui le précède. Plus on roule vite, plus cette distance doit être grande.","grave":true,"ref":"Art. 10.1, 2° AR 01/12/1975"},{"id":"VIT-025","theme":"vitesse","q":"Sur une route dégagée, sans raison valable, je roule à 30 km/h là où la limite est 90 km/h et je gêne la file derrière moi. Est-ce permis ?","choices":["Non, je ne peux pas gêner la marche normale des autres en roulant anormalement lentement sans raison valable","Oui, rouler lentement est toujours plus sûr"],"answer":0,"explain":"Aucun conducteur ne peut gêner la marche normale des autres en circulant sans raison valable à une vitesse anormalement réduite.","ref":"Art. 10.2 AR 01/12/1975"},{"id":"VIT-026","theme":"vitesse","q":"Je freine brusquement sur une route fluide, sans aucune raison de sécurité, pour « donner une leçon » au conducteur qui me suit. Est-ce autorisé ?","choices":["Oui","Non"],"answer":1,"explain":"Il est interdit de gêner les autres conducteurs par un freinage soudain non exigé par des raisons de sécurité. Ce comportement provoque des collisions par l'arrière.","grave":true,"ref":"Art. 10.2 AR 01/12/1975"},{"id":"VIT-027","theme":"vitesse","q":"Je dois ralentir fortement. Ma voiture a des feux-stop en état de marche. Comment dois-je signaler mon intention ?","choices":["En allumant les feux de détresse obligatoirement","Je ne dois rien signaler","Par les feux-stop"],"answer":2,"explain":"Le conducteur qui veut ralentir de façon notable doit l'indiquer au moyen des feux-stop lorsque le véhicule en est pourvu.","ref":"Art. 10.2 AR 01/12/1975"},{"id":"VIT-028","theme":"vitesse","q":"Sur une route de campagne, des chevaux montés approchent et l'un d'eux montre des signes de frayeur. Que dois-je faire ?","choices":["Les dépasser rapidement pour écourter la situation","M'arrêter","Klaxonner pour avertir le cavalier"],"answer":1,"explain":"Il faut ralentir à l'approche d'animaux de trait, de charge, de monture ou de bestiaux, et s'arrêter lorsqu'ils montrent des signes de frayeur.","grave":true,"ref":"Art. 10.3 AR 01/12/1975"},{"id":"VIT-029","theme":"vitesse","q":"Mon passager m'encourage à « tester » la puissance de la voiture en roulant bien au-delà de la limite. Son comportement est-il permis ?","choices":["Non, il est interdit d'inciter ou de provoquer un conducteur à circuler à une vitesse excessive","Oui, seul le conducteur est responsable"],"answer":0,"explain":"Le code interdit expressément d'inciter ou de provoquer un conducteur à circuler à une vitesse excessive.","ref":"Art. 10.4 AR 01/12/1975"},{"id":"VIT-030","theme":"vitesse","q":"Je roule à 120 km/h sur l'autoroute et j'arrive dans une zone de travaux où un panneau C43 « 70 » est placé. Que dois-je faire ?","choices":["Garder 120 km/h, c'est une autoroute","Réduire seulement à 90 km/h","Réduire ma vitesse à 70 km/h maximum"],"answer":2,"explain":"Les limitations inférieures imposées par un signal C43 restent d'application, même sur autoroute. Traverser une zone de travaux à pleine vitesse est très dangereux pour les ouvriers.","grave":true,"sign":"C43-70","ref":"Art. 11.2.1° et 68 (C43) AR 01/12/1975"},{"id":"VIT-031","theme":"vitesse","q":"Hors agglomération, je conduis un camion de 12 tonnes de masse maximale autorisée derrière un autre camion de plus de 7,5 tonnes. Quel intervalle minimum dois-je respecter ?","choices":["20 mètres","50 mètres","100 mètres"],"answer":1,"explain":"En dehors des agglomérations, les véhicules de plus de 7,5 tonnes ou de plus de 7 mètres de long doivent maintenir entre eux un intervalle d'au moins 50 mètres.","ref":"Art. 18.2 AR 01/12/1975"},{"id":"VIT-032","theme":"vitesse","q":"Dans une agglomération en Wallonie, un C43 « 70 » m'autorise 70 km/h. J'entre ensuite dans une zone de rencontre. Quelle vitesse dois-je respecter ?","choices":["70 km/h","30 km/h","20 km/h"],"answer":2,"explain":"Le C43 cesse de valoir au signal de début de zone de rencontre ; dans une zone de rencontre ou résidentielle, la vitesse est limitée à 20 km/h.","ref":"Art. 68 (C43) et 22bis AR 01/12/1975"}];
